package io.robrichardson.banklessbank;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup(BanklessBankConfig.CONFIG_GROUP)
public interface BanklessBankConfig extends Config
{
	String CONFIG_GROUP = "banklessbank";

	@ConfigSection(
		name = "Bank view",
		description = "How the bank view is opened and drawn",
		position = 0
	)
	String VIEW_SECTION = "view";

	@ConfigSection(
		name = "Death storage",
		description = "Deathpile and grave tracking",
		position = 1
	)
	String DEATH_SECTION = "death";

	@ConfigItem(
		keyName = "toggleKeybind",
		name = "Toggle bank view",
		description = "Hotkey that opens and closes the Bankless Bank view",
		section = VIEW_SECTION,
		position = 0
	)
	default Keybind toggleKeybind()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "showHudButton",
		name = "Show HUD button",
		description = "Draw an always-visible button on the game canvas that opens the bank view",
		section = VIEW_SECTION,
		position = 1
	)
	default boolean showHudButton()
	{
		return true;
	}

	@ConfigItem(
		keyName = "placeholders",
		name = "Placeholders",
		description = "Keep a greyed-out slot for items you no longer own, like real bank placeholders",
		section = VIEW_SECTION,
		position = 2
	)
	default boolean placeholders()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showEmptyStorages",
		name = "Show empty storages",
		description = "List storages with no tracked items in the storage tab",
		section = VIEW_SECTION,
		position = 3
	)
	default boolean showEmptyStorages()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showValue",
		name = "Show GE value",
		description = "Show the Grand Exchange value of the visible tab in the title bar",
		section = VIEW_SECTION,
		position = 4
	)
	default boolean showValue()
	{
		return true;
	}

	@ConfigItem(
		keyName = "deathpilesUseAccountPlayTime",
		name = "Cross-client tracking",
		description = "When enabled, deathpile/grave expiry is based on account play time, so time played on "
			+ "another client (like mobile) counts. Requires visiting the Character Summary tab so the plugin "
			+ "can read your play time.",
		section = DEATH_SECTION,
		position = 0
	)
	default boolean deathpilesUseAccountPlayTime()
	{
		return false;
	}

	@Range(min = 1, max = 59)
	@ConfigItem(
		keyName = "deathpileContingencyMinutes",
		name = "Contingency (minutes)",
		description = "This many minutes are removed from the deathpile/grave timer. If set to 15, new "
			+ "deathpiles start with 45 minutes until expiry.",
		section = DEATH_SECTION,
		position = 1
	)
	default int deathpileContingencyMinutes()
	{
		return 1;
	}
}

package io.robrichardson.banklessbank;

import com.google.inject.Injector;
import com.google.inject.Provides;
import io.robrichardson.banklessbank.bootstrap.DwmsImporter;
import io.robrichardson.banklessbank.tracking.ClientState;
import io.robrichardson.banklessbank.tracking.ItemContainerWatcher;
import io.robrichardson.banklessbank.tracking.StorageManagerManager;
import io.robrichardson.banklessbank.tracking.carryable.CarryableStorageManager;
import io.robrichardson.banklessbank.tracking.death.DeathStorageManager;
import io.robrichardson.banklessbank.tracking.playerownedhouse.PlayerOwnedHouseStorageManager;
import io.robrichardson.banklessbank.tracking.sailing.SailingStorageManager;
import io.robrichardson.banklessbank.tracking.stash.StashStorageManager;
import io.robrichardson.banklessbank.tracking.world.WorldStorageManager;
import io.robrichardson.banklessbank.ui.BankInputListener;
import io.robrichardson.banklessbank.ui.BankOverlay;
import io.robrichardson.banklessbank.ui.BankViewController;
import io.robrichardson.banklessbank.ui.BanklessBankPanel;
import io.robrichardson.banklessbank.ui.HudButtonOverlay;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.VarClientInt;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ConfigSync;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Bankless Bank",
	description = "A bank-style in-game view of every item you own, without visiting a bank. Built for UIMs.",
	tags = {"uim", "bank", "storage", "items", "inventory", "looting bag", "poh", "stash", "overlay"}
)
public class BanklessBankPlugin extends Plugin
{
	private static final String CONFIG_KEY_SHOW_HUD_BUTTON = "showHudButton";
	private static final String CONFIG_KEY_PLACEHOLDERS = "placeholders";
	private static final String CONFIG_KEY_SHOW_EMPTY_STORAGES = "showEmptyStorages";

	static final String CONFIG_KEY_IS_MEMBER = "isMember";
	static final String CONFIG_KEY_ACCOUNT_TYPE = "accountType";

	@Getter
	@Inject
	private Client client;

	@Getter
	@Inject
	private ClientThread clientThread;

	@Getter
	@Inject
	private ConfigManager configManager;

	@Getter
	@Inject
	private ItemManager itemManager;

	@Getter
	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private Injector injector;

	@Inject
	private DwmsImporter dwmsImporter;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private BankViewController viewController;

	@Inject
	private BankOverlay bankOverlay;

	@Inject
	private HudButtonOverlay hudButtonOverlay;

	@Inject
	private BankInputListener inputListener;

	private BanklessBankPanel panel;
	private NavigationButton navButton;

	@Getter
	@Inject
	private BanklessBankConfig config;

	@Inject
	private CarryableStorageManager carryableStorageManager;

	@Inject
	private DeathStorageManager deathStorageManager;

	@Getter
	@Inject
	private SailingStorageManager sailingStorageManager;

	@Inject
	private StashStorageManager stashStorageManager;

	@Inject
	private PlayerOwnedHouseStorageManager playerOwnedHouseStorageManager;

	@Getter
	@Inject
	private WorldStorageManager worldStorageManager;

	@Getter
	private StorageManagerManager storageManagerManager;

	private ClientState clientState = ClientState.LOGGED_OUT;
	private boolean pluginStartedAlreadyLoggedIn;
	private String profileKey;

	/**
	 * The profile whose tracked storages are actually loaded; null until the deferred load has
	 * run.
	 */
	@Getter
	private volatile String loadedProfileKey;

	/** Set when any tracked storage changes; the view clears it when it redraws. */
	@Getter
	private volatile boolean storagesDirty;

	@Override
	protected void startUp()
	{
		if (storageManagerManager == null)
		{
			deathStorageManager.setCarryableStorageManager(carryableStorageManager);
			worldStorageManager
				.getLeprechaun()
				.setBottomlessBucketStorage(carryableStorageManager.getBottomlessBucket());
			storageManagerManager = new StorageManagerManager(
				itemManager,
				sailingStorageManager,
				carryableStorageManager,
				deathStorageManager,
				stashStorageManager,
				playerOwnedHouseStorageManager,
				worldStorageManager);

			ItemContainerWatcher.init(client);
		}

		reset();

		final GameState gameState = client.getGameState();
		if (gameState == GameState.LOGGED_IN || gameState == GameState.LOGGING_IN)
		{
			clientState = ClientState.LOGGING_IN;
		}

		if (gameState == GameState.LOGGED_IN)
		{
			// Already in-game, so the login sequence we hook the initial load onto has been and gone;
			// onGameTick replays the item containers instead.
			pluginStartedAlreadyLoggedIn = true;
		}

		panel = injector.getInstance(BanklessBankPanel.class);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Bankless Bank")
			.icon(icon)
			.panel(panel)
			.priority(5)
			.build();
		clientToolbar.addNavigation(navButton);

		viewController.startUp();
		overlayManager.add(bankOverlay);
		if (config.showHudButton())
		{
			overlayManager.add(hudButtonOverlay);
		}
		// Appended, never inserted at position 0. RuneLite's Stretched Mode plugin registers a
		// coordinate-translating listener at position 0 that rewrites every event from stretched
		// screen pixels to real canvas pixels; core plugins start before hub plugins, so inserting at
		// 0 here would land ahead of it and every hit-test in BankInputListener would compare raw
		// screen coordinates against canvas-space bounds and miss. Appending keeps us behind the
		// translator whether it started before us or gets enabled later (a later enable inserts at
		// 0, still ahead). Consumption is what stops an event reaching the game, not list position,
		// so nothing is lost by sitting behind RuneLite's own overlay listener either.
		mouseManager.registerMouseListener(inputListener);
		mouseManager.registerMouseWheelListener(inputListener);
		keyManager.registerKeyListener(inputListener);
		keyManager.registerKeyListener(inputListener.getHotkeyListener());

		log.debug("Bankless Bank started");
	}

	@Override
	protected void shutDown()
	{
		mouseManager.unregisterMouseListener(inputListener);
		mouseManager.unregisterMouseWheelListener(inputListener);
		keyManager.unregisterKeyListener(inputListener);
		keyManager.unregisterKeyListener(inputListener.getHotkeyListener());
		overlayManager.remove(bankOverlay);
		overlayManager.remove(hudButtonOverlay);
		inputListener.publish(false, null, false, false);
		inputListener.publishHud(false, null);
		viewController.stop();

		// startUp/shutDown run on the EDT, but BankOverlay.render() -> refresh() mutates the same
		// BankViewModel/BankLayout state on the client thread; overlayManager.remove above does not
		// cancel a frame already in flight. Route the flush through the client thread so it
		// serialises against that in-flight render instead of racing it. If the client thread never
		// runs again (client exiting), at worst the last second of layout edits is lost; tracked
		// storages themselves are still flushed separately by the existing onClientShutdown/
		// onConfigSync handlers.
		clientThread.invoke(() ->
		{
			viewController.flush();
			save();
		});

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;

		log.debug("Bankless Bank stopped");
	}

	/** Toggles the bank view overlay. Safe from any thread. */
	public void toggleView()
	{
		viewController.toggle();
	}

	/** Opens or closes the bank view overlay. Safe from any thread. */
	public void setViewOpen(boolean viewOpen)
	{
		viewController.setOpen(viewOpen);
	}

	/** Whether the bank view overlay is currently open. */
	public boolean isViewOpen()
	{
		return viewController.isOpen();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged configChanged)
	{
		if (!BanklessBankConfig.CONFIG_GROUP.equals(configChanged.getGroup()))
		{
			return;
		}

		if (CONFIG_KEY_SHOW_HUD_BUTTON.equals(configChanged.getKey()))
		{
			if (config.showHudButton())
			{
				overlayManager.add(hudButtonOverlay);
			}
			else
			{
				overlayManager.remove(hudButtonOverlay);
				inputListener.publishHud(false, null);
			}
		}
		else if (CONFIG_KEY_PLACEHOLDERS.equals(configChanged.getKey())
			|| CONFIG_KEY_SHOW_EMPTY_STORAGES.equals(configChanged.getKey()))
		{
			viewController.post(() -> viewController.getViewModel().invalidate());
			storagesChanged();
		}
	}

	private void reset()
	{
		clientState = ClientState.LOGGED_OUT;

		ItemContainerWatcher.reset();
		storageManagerManager.reset();
		storagesChanged();
		loadedProfileKey = null;
	}

	/** No tracked storage is loaded, so events carry nothing we can attribute to a profile. */
	private boolean isLoggedOut()
	{
		return clientState == ClientState.LOGGED_OUT;
	}

	/** Called by the tracking layer whenever tracked items change. */
	public void storagesChanged()
	{
		storagesDirty = true;
	}

	/** The view calls this after it has rebuilt from the tracked data. */
	public void clearStoragesDirty()
	{
		storagesDirty = false;
	}

	private void load(String profileKey)
	{
		this.profileKey = profileKey;
		loadedProfileKey = null;

		clientThread.invokeLater(() ->
		{
			storageManagerManager.reset();
			storageManagerManager.load(profileKey);
			storagesChanged();
			loadedProfileKey = profileKey;
			maybeAutoImportFromDwms(profileKey);
			refreshPanel();
		});
	}

	/**
	 * On first login for a profile with no tracked data of our own, and that we have never
	 * imported into before, automatically pulls in whatever DWMS has (fill-gaps only, so it never
	 * clobbers anything). No-op otherwise; the player can still trigger a manual import from the
	 * sidebar panel at any time.
	 */
	private void maybeAutoImportFromDwms(String profileKey)
	{
		if (profileKey == null)
		{
			return;
		}

		if (dwmsImporter.hasOwnData(profileKey) || dwmsImporter.hasImportedBefore(profileKey))
		{
			return;
		}

		if (!dwmsImporter.hasDwmsData(profileKey) && !dwmsImporter.isDwmsEnabled())
		{
			return;
		}

		dwmsImporter.importNow(DwmsImporter.Mode.FILL_GAPS, result ->
		{
			log.debug("Auto-import from DWMS on first login: {}", result.getMessage());
			reload();
			refreshPanel();
		});
	}

	private void refreshPanel()
	{
		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::refresh);
		}
	}

	/** Saves all tracked storages for the current profile. */
	public void save()
	{
		if (profileKey == null)
		{
			return;
		}

		storageManagerManager.save(profileKey);
	}

	/** Re-reads all tracked storages from config (used after a bootstrap import). Client thread only. */
	public void reload()
	{
		if (profileKey == null)
		{
			profileKey = configManager.getRSProfileKey();
		}

		storageManagerManager.reset();
		storageManagerManager.load(profileKey);
		storagesChanged();
		loadedProfileKey = profileKey;
	}

	/**
	 * Re-reads every persisted setting for the current profile after an external import: tracked
	 * storages, the bank layout and the view state. Client thread only.
	 */
	public void reloadAfterImport()
	{
		reload();                       // resets + reloads storages, clears each Storage.lastSaveString
		viewController.reloadFromConfig();
	}

	@Subscribe
	public void onConfigSync(ConfigSync configSync)
	{
		save();
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown clientShutdown)
	{
		save();
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged e)
	{
		save();
		load(configManager.getRSProfileKey());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		storageManagerManager.onGameStateChanged(gameStateChanged);

		final GameState gameState = gameStateChanged.getGameState();
		if (gameState == GameState.LOGGING_IN)
		{
			clientState = ClientState.LOGGING_IN;
		}

		if (gameState == GameState.LOGGED_IN
			|| gameState == GameState.LOGIN_SCREEN
			|| gameState == GameState.HOPPING)
		{
			refreshPanel();
		}
	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{
		if (isLoggedOut())
		{
			return;
		}

		if (clientState == ClientState.LOGGING_IN)
		{
			final boolean isMember = client.getVarcIntValue(VarClientInt.MEMBERSHIP_STATUS) == 1;
			final int accountType = client.getVarbitValue(VarbitID.IRONMAN);

			configManager.setRSProfileConfiguration(BanklessBankConfig.CONFIG_GROUP, CONFIG_KEY_IS_MEMBER, isMember);
			configManager.setRSProfileConfiguration(BanklessBankConfig.CONFIG_GROUP, CONFIG_KEY_ACCOUNT_TYPE, accountType);

			storageManagerManager.logIn(isMember, accountType);
			clientState = ClientState.LOGGED_IN;

			if (pluginStartedAlreadyLoggedIn)
			{
				load(configManager.getRSProfileKey());

				clientThread.invokeLater(() ->
				{
					for (ItemContainer itemContainer : client.getItemContainers())
					{
						onItemContainerChanged(new ItemContainerChanged(itemContainer.getId(), itemContainer));
					}

					VarbitChanged varbitChanged = new VarbitChanged();
					varbitChanged.setVarbitId(-999);
					onVarbitChanged(varbitChanged);
				});

				pluginStartedAlreadyLoggedIn = false;
			}

			return;
		}

		ItemContainerWatcher.onGameTick(this);
		storageManagerManager.onGameTick();
		storageManagerManager.softUpdate();
		dwmsImporter.onGameTick();
	}

	@Subscribe
	public void onPluginMessage(PluginMessage pluginMessage)
	{
		dwmsImporter.onPluginMessage(pluginMessage);
	}

	@Subscribe
	public void onActorDeath(ActorDeath actorDeath)
	{
		storageManagerManager.onActorDeath(actorDeath);
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		if (isLoggedOut())
		{
			return;
		}

		storageManagerManager.onChatMessage(chatMessage);
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned gameObjectSpawned)
	{
		if (isLoggedOut())
		{
			return;
		}

		storageManagerManager.onGameObjectSpawned(gameObjectSpawned);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked menuOption)
	{
		if (isLoggedOut())
		{
			return;
		}

		storageManagerManager.onMenuOptionClicked(menuOption);
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded widgetLoaded)
	{
		if (isLoggedOut())
		{
			return;
		}

		storageManagerManager.onWidgetLoaded(widgetLoaded);
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed widgetClosed)
	{
		if (isLoggedOut())
		{
			return;
		}

		storageManagerManager.onWidgetClosed(widgetClosed);
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged varbitChanged)
	{
		if (isLoggedOut())
		{
			return;
		}

		storageManagerManager.onVarbitChanged(varbitChanged);
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged itemContainerChanged)
	{
		if (isLoggedOut())
		{
			return;
		}

		storageManagerManager.onItemContainerChanged(itemContainerChanged);
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned itemDespawned)
	{
		if (isLoggedOut())
		{
			return;
		}

		storageManagerManager.onItemDespawned(itemDespawned);
	}

	@Provides
	BanklessBankConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BanklessBankConfig.class);
	}
}

package io.robrichardson.banklessbank.bootstrap;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonSyntaxException;
import io.robrichardson.banklessbank.BanklessBankConfig;
import java.time.Instant;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.TreeSet;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Exports and imports every {@code banklessbank} config key for one RS profile as a single JSON
 * document, so a player can move their bank layout and tracked storages to another machine or
 * account without waiting on RuneLite's own cloud sync (which only covers the signed-in case).
 *
 * <p>An export is a faithful copy of both config scopes {@link ConfigManager} uses for this
 * plugin: the active-profile scope (view state, settings) and the RS-profile scope (layout,
 * placeholder ignore list, every tracked storage). Import always replaces the *currently
 * logged-in* character's data, never the one recorded in the file, which is what makes moving
 * between machines and accounts work.
 */
@Slf4j
@Singleton
public class DataExporter
{
	public static final int SCHEMA_VERSION = 1;
	static final String SCHEMA_PLUGIN = "banklessbank";

	/**
	 * One exported document. Plain fields, no Lombok, so Gson round-trips it without Unsafe.
	 *
	 * <p>{@code schema} and {@code plugin} deliberately carry no field initialiser: they are what
	 * {@link #parse(String)} identifies the file by, and a default would make every JSON object
	 * (including an unrelated one, or {@code "{}"}) validate as an empty export of ours - which an
	 * import would honour by wiping both config scopes and writing nothing back. {@link
	 * #buildExport} sets both explicitly.
	 */
	public static class ExportDocument
	{
		public int schema;
		public String plugin;
		public long exportedAt;
		public String exportedAtIso;
		public String rsProfileKey;
		public String displayName;
		public Map<String, String> profileConfig = new LinkedHashMap<>();
		public Map<String, String> rsProfileConfig = new LinkedHashMap<>();
	}

	@Value
	public static class ImportResult
	{
		int keysRemoved;
		int profileKeysWritten;
		int rsProfileKeysWritten;
		int keysSkipped;
		String message;
	}

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	public DataExporter(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson.newBuilder().setPrettyPrinting().disableHtmlEscaping().create();
	}

	/** Snapshots both config scopes for one RS profile. Any thread; {@link ConfigManager} is thread safe. */
	public ExportDocument buildExport(@Nullable String rsProfileKey, @Nullable String displayName)
	{
		ExportDocument doc = new ExportDocument();
		doc.schema = SCHEMA_VERSION;
		doc.plugin = SCHEMA_PLUGIN;
		doc.exportedAt = System.currentTimeMillis();
		doc.exportedAtIso = DateTimeFormatter.ISO_INSTANT.format(Instant.ofEpochMilli(doc.exportedAt));
		doc.rsProfileKey = rsProfileKey;
		doc.displayName = displayName;

		String prefix = BanklessBankConfig.CONFIG_GROUP + ".";
		for (String key : new TreeSet<>(configManager.getConfigurationKeys(prefix)))
		{
			String shortKey = key.substring(prefix.length());
			String value = configManager.getConfiguration(BanklessBankConfig.CONFIG_GROUP, shortKey);
			if (value != null)
			{
				doc.profileConfig.put(shortKey, value);
			}
		}

		if (rsProfileKey != null)
		{
			for (String key : new TreeSet<>(configManager.getRSProfileConfigurationKeys(
				BanklessBankConfig.CONFIG_GROUP, rsProfileKey, "")))
			{
				String value = configManager.getConfiguration(BanklessBankConfig.CONFIG_GROUP, rsProfileKey, key);
				if (value != null)
				{
					doc.rsProfileConfig.put(key, value);
				}
			}
		}

		return doc;
	}

	/** Pretty-prints a document. */
	public String toJson(ExportDocument doc)
	{
		return gson.toJson(doc);
	}

	/** @throws IllegalArgumentException with a user-showable message if the file is not ours. */
	public ExportDocument parse(String json)
	{
		ExportDocument doc;
		try
		{
			doc = gson.fromJson(json, ExportDocument.class);
		}
		catch (JsonSyntaxException e)
		{
			throw new IllegalArgumentException("File is not valid JSON.");
		}

		if (doc == null)
		{
			throw new IllegalArgumentException("File is empty or not JSON.");
		}
		if (!SCHEMA_PLUGIN.equals(doc.plugin))
		{
			throw new IllegalArgumentException("Not a Bankless Bank export file.");
		}
		if (doc.schema < 1)
		{
			throw new IllegalArgumentException("Export file has no version; it is not a Bankless Bank"
				+ " export file.");
		}
		if (doc.schema > SCHEMA_VERSION)
		{
			throw new IllegalArgumentException("Unsupported export version " + doc.schema
				+ "; this build reads up to " + SCHEMA_VERSION + ".");
		}
		if (doc.profileConfig == null)
		{
			doc.profileConfig = new LinkedHashMap<>();
		}
		if (doc.rsProfileConfig == null)
		{
			doc.rsProfileConfig = new LinkedHashMap<>();
		}
		return doc;
	}

	/** Replaces every banklessbank key in both scopes with the document's. Any thread. */
	public ImportResult applyImport(ExportDocument doc, @Nullable String targetRsProfileKey)
	{
		int removed = 0;
		int skipped = 0;

		// 1. clear active-profile scope
		String prefix = BanklessBankConfig.CONFIG_GROUP + ".";
		for (String whole : new ArrayList<>(configManager.getConfigurationKeys(prefix)))
		{
			configManager.unsetConfiguration(BanklessBankConfig.CONFIG_GROUP, null, whole.substring(prefix.length()));
			removed++;
		}

		// 2. clear RS-profile scope (only when we have a target profile)
		if (targetRsProfileKey != null)
		{
			for (String key : new ArrayList<>(configManager.getRSProfileConfigurationKeys(
				BanklessBankConfig.CONFIG_GROUP, targetRsProfileKey, "")))
			{
				configManager.unsetConfiguration(BanklessBankConfig.CONFIG_GROUP, targetRsProfileKey, key);
				removed++;
			}
		}

		// 3. write active-profile scope
		int profileKeysWritten = 0;
		for (Map.Entry<String, String> e : doc.profileConfig.entrySet())
		{
			if (!isWritableKey(e.getKey()) || e.getValue() == null)
			{
				skipped++;
				continue;
			}
			configManager.setConfiguration(BanklessBankConfig.CONFIG_GROUP, e.getKey(), e.getValue());
			profileKeysWritten++;
		}

		// 4. write RS-profile scope
		int rsProfileKeysWritten = 0;
		if (targetRsProfileKey != null)
		{
			for (Map.Entry<String, String> e : doc.rsProfileConfig.entrySet())
			{
				if (!isWritableKey(e.getKey()) || e.getValue() == null)
				{
					skipped++;
					continue;
				}
				configManager.setConfiguration(BanklessBankConfig.CONFIG_GROUP, targetRsProfileKey, e.getKey(), e.getValue());
				rsProfileKeysWritten++;
			}
		}
		else
		{
			skipped += doc.rsProfileConfig.size();
		}

		StringBuilder message = new StringBuilder("Imported ")
			.append(profileKeysWritten)
			.append(" settings and ")
			.append(rsProfileKeysWritten)
			.append(" storage keys.");
		if (skipped > 0)
		{
			message.append(" Skipped ").append(skipped).append(" unusable keys.");
		}
		if (targetRsProfileKey == null)
		{
			message.append(" Not logged in, so per-character data was not imported.");
		}

		return new ImportResult(removed, profileKeysWritten, rsProfileKeysWritten, skipped, message.toString());
	}

	/** e.g. banklessbank-Zezima-20260905-142233.json */
	public static String defaultFileName(@Nullable String displayName, long whenMillis)
	{
		String safeName = displayName == null || displayName.trim().isEmpty()
			? "export"
			: displayName.replaceAll("[^A-Za-z0-9_-]", "_");
		String timestamp = new java.text.SimpleDateFormat("yyyyMMdd-HHmmss").format(new java.util.Date(whenMillis));
		return "banklessbank-" + safeName + "-" + timestamp + ".json";
	}

	/** Mirrors {@code ConfigManager.setConfiguration}'s own rejects, so a hostile file cannot throw. */
	static boolean isWritableKey(String key)
	{
		return key != null && !key.isEmpty() && key.indexOf(':') == -1 && !key.startsWith("$");
	}
}

package io.robrichardson.banklessbank.bootstrap;

import io.robrichardson.banklessbank.BanklessBankConfig;
import io.robrichardson.banklessbank.BanklessBankPlugin;
import io.robrichardson.banklessbank.tracking.ItemStack;
import io.robrichardson.banklessbank.tracking.ItemStorage;
import io.robrichardson.banklessbank.tracking.Storage;
import io.robrichardson.banklessbank.tracking.StorageManager;
import io.robrichardson.banklessbank.tracking.StorageManagerManager;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

/**
 * One-time bootstrap of tracked storages from the "Dude, Where's My Stuff?" (DWMS) plugin.
 *
 * <p>Two sources are combined:
 * <ol>
 *   <li>DWMS's saved RS-profile config (group {@code dudewheresmystuff}). Our tracking layer is a
 *       port of DWMS's, so the save strings are copied key-for-key into our own group. This keeps
 *       per-storage metadata (deathpile expiry, UUIDs, last-updated times) and works even when
 *       DWMS is disabled.</li>
 *   <li>If DWMS is running, its live state via the {@code storages-request} PluginMessage, which
 *       refreshes the item lists of storages that DWMS has updated since it last saved.</li>
 * </ol>
 *
 * <p>In {@link Mode#FILL_GAPS} only storages we had no data for are touched; {@link Mode#OVERWRITE}
 * replaces everything. Imports never run on a timer. After import there is no dependency on DWMS.
 */
@Slf4j
@Singleton
public class DwmsImporter
{
	public static final String DWMS_CONFIG_GROUP = "dudewheresmystuff";
	public static final String DWMS_PLUGIN_CLASS = "dev.thource.runelite.dudewheresmystuff.DudeWheresMyStuffPlugin";
	public static final String DWMS_STORAGES_REQUEST = "storages-request";
	public static final String DWMS_STORAGES_RESPONSE = "storages-response";
	public static final String PLUGIN_MESSAGE_SOURCE = "Bankless Bank";
	public static final String CONFIG_KEY_IMPORTED_AT = "dwmsImportedAt";

	/** Config key prefixes to copy from DWMS. Coins, minigames and UI settings are skipped. */
	static final List<String> IMPORTED_KEY_PREFIXES = List.of(
		"carryable.", "death.", "poh.", "world.", "sailing.", "stash.", "minutesPlayed");

	private static final int RESPONSE_TIMEOUT_TICKS = 10;

	public enum Mode
	{
		FILL_GAPS,
		OVERWRITE
	}

	@Value
	public static class Result
	{
		int configKeysCopied;
		int liveStoragesApplied;
		boolean liveResponseReceived;
		String message;
	}

	private final BanklessBankPlugin plugin;
	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final PluginManager pluginManager;
	private final EventBus eventBus;

	@Getter
	@Nullable
	private Result lastResult;

	@Getter
	private boolean importing;

	@Nullable
	private Pending pending;

	@Inject
	public DwmsImporter(
		BanklessBankPlugin plugin,
		Client client,
		ClientThread clientThread,
		ConfigManager configManager,
		PluginManager pluginManager,
		EventBus eventBus)
	{
		this.plugin = plugin;
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.pluginManager = pluginManager;
		this.eventBus = eventBus;
	}

	@Nullable
	private Plugin findDwmsPlugin()
	{
		for (Plugin p : pluginManager.getPlugins())
		{
			if (DWMS_PLUGIN_CLASS.equals(p.getClass().getName()))
			{
				return p;
			}
		}
		return null;
	}

	public boolean isDwmsInstalled()
	{
		return findDwmsPlugin() != null;
	}

	public boolean isDwmsEnabled()
	{
		Plugin p = findDwmsPlugin();
		return p != null && pluginManager.isPluginEnabled(p);
	}

	/** Whether DWMS has saved anything for the given RS profile. */
	public boolean hasDwmsData(String profileKey)
	{
		return profileKey != null
			&& !configManager.getRSProfileConfigurationKeys(DWMS_CONFIG_GROUP, profileKey, "").isEmpty();
	}

	/** Whether Bankless Bank has any tracked storage saved for the given RS profile. */
	public boolean hasOwnData(String profileKey)
	{
		if (profileKey == null)
		{
			return false;
		}

		for (String prefix : IMPORTED_KEY_PREFIXES)
		{
			if (!configManager.getRSProfileConfigurationKeys(BanklessBankConfig.CONFIG_GROUP, profileKey, prefix).isEmpty())
			{
				return true;
			}
		}
		return false;
	}

	public boolean hasImportedBefore(String profileKey)
	{
		return profileKey != null
			&& configManager.getConfiguration(BanklessBankConfig.CONFIG_GROUP, profileKey, CONFIG_KEY_IMPORTED_AT) != null;
	}

	/**
	 * Runs an import for the current RS profile. Work happens on the client thread; the callback is
	 * invoked (on the client thread) once the config copy and, if DWMS is running, the live response
	 * have been applied or timed out.
	 */
	public void importNow(Mode mode, @Nullable Consumer<Result> callback)
	{
		if (importing)
		{
			return;
		}
		importing = true;

		clientThread.invokeLater(() ->
		{
			try
			{
				String profileKey = configManager.getRSProfileKey();
				if (profileKey == null)
				{
					finish(new Result(0, 0, false, "Log in first"), callback);
					return;
				}

				StorageManagerManager smm = plugin.getStorageManagerManager();
				Set<String> storagesWithDataBefore = storagesWithData(smm, profileKey);

				plugin.save();
				int copied = copyConfig(profileKey, mode, storagesWithDataBefore);
				plugin.reload();

				if (!isDwmsEnabled())
				{
					finish(new Result(copied, 0, false,
						copied + " storages copied from saved DWMS data (DWMS not running)"), callback);
					return;
				}

				pending = new Pending(mode, callback, copied, storagesWithDataBefore, client.getTickCount() + RESPONSE_TIMEOUT_TICKS);
				Map<String, Object> data = new HashMap<>();
				data.put("source", PLUGIN_MESSAGE_SOURCE);
				eventBus.post(new PluginMessage(DWMS_CONFIG_GROUP, DWMS_STORAGES_REQUEST, data));
			}
			catch (RuntimeException e)
			{
				log.warn("DWMS import failed", e);
				pending = null;
				finish(new Result(0, 0, false, "Import failed: " + e.getMessage()), callback);
			}
		});
	}

	/** Config keys of the storages we currently hold data for, from their live state. */
	private Set<String> storagesWithData(StorageManagerManager smm, String profileKey)
	{
		Set<String> keys = new HashSet<>();
		for (StorageManager<?, ?> manager : smm.getStorageManagers())
		{
			for (Storage<?> storage : manager.getStorages())
			{
				if (storage.hasData() || !storage.getItems().isEmpty())
				{
					keys.add(storageKey(manager, storage));
				}
			}
		}
		keys.addAll(configManager.getRSProfileConfigurationKeys(BanklessBankConfig.CONFIG_GROUP, profileKey, ""));
		return keys;
	}

	private static String storageKey(StorageManager<?, ?> manager, Storage<?> storage)
	{
		return manager.getConfigKey() + "." + storage.getType().getConfigKey();
	}

	/**
	 * Copies DWMS's saved storage strings into our config group.
	 *
	 * @return number of keys copied
	 */
	int copyConfig(String profileKey, Mode mode, Set<String> existingKeys)
	{
		int copied = 0;
		for (String key : configManager.getRSProfileConfigurationKeys(DWMS_CONFIG_GROUP, profileKey, ""))
		{
			if (!isImportedKey(key))
			{
				continue;
			}

			if (mode == Mode.FILL_GAPS && existingKeys.contains(key))
			{
				continue;
			}

			String value = configManager.getConfiguration(DWMS_CONFIG_GROUP, profileKey, key);
			if (value == null)
			{
				continue;
			}

			configManager.setConfiguration(BanklessBankConfig.CONFIG_GROUP, profileKey, key, value);
			copied++;
		}

		configManager.setConfiguration(BanklessBankConfig.CONFIG_GROUP, profileKey, CONFIG_KEY_IMPORTED_AT,
			String.valueOf(System.currentTimeMillis()));
		return copied;
	}

	static boolean isImportedKey(String key)
	{
		for (String prefix : IMPORTED_KEY_PREFIXES)
		{
			if (key.startsWith(prefix))
			{
				return true;
			}
		}
		return false;
	}

	/** Must be called every game tick so a missing DWMS response times out. */
	public void onGameTick()
	{
		Pending p = pending;
		if (p != null && client.getTickCount() >= p.deadlineTick)
		{
			pending = null;
			finish(new Result(p.configKeysCopied, 0, false,
				p.configKeysCopied + " storages copied; DWMS did not answer the live request"), p.callback);
		}
	}

	/** Handles the DWMS "storages-response" message. Posted by DWMS on the client thread. */
	public void onPluginMessage(PluginMessage message)
	{
		if (!DWMS_CONFIG_GROUP.equals(message.getNamespace())
			|| !DWMS_STORAGES_RESPONSE.equals(message.getName())
			|| message.getData() == null
			|| !PLUGIN_MESSAGE_SOURCE.equals(message.getData().get("target")))
		{
			return;
		}

		Pending p = pending;
		if (p == null)
		{
			return;
		}
		pending = null;

		try
		{
			int applied = applyLiveStorages(message.getData(), p.mode, p.storagesWithDataBefore);
			plugin.save();
			plugin.storagesChanged();
			finish(new Result(p.configKeysCopied, applied, true,
				p.configKeysCopied + " storages copied, " + applied + " refreshed from DWMS live data"), p.callback);
		}
		catch (RuntimeException e)
		{
			log.warn("DWMS import failed", e);
			finish(new Result(p.configKeysCopied, 0, false, "Import failed: " + e.getMessage()), p.callback);
		}
	}

	@SuppressWarnings("unchecked")
	int applyLiveStorages(Map<String, Object> data, Mode mode, Set<String> storagesWithDataBefore)
	{
		Object storagesObj = data.get("storages");
		if (!(storagesObj instanceof List))
		{
			return 0;
		}

		StorageManagerManager smm = plugin.getStorageManagerManager();
		int applied = 0;
		for (Object entryObj : (List<Object>) storagesObj)
		{
			if (!(entryObj instanceof Map))
			{
				continue;
			}
			Map<String, Object> entry = (Map<String, Object>) entryObj;
			String category = Objects.toString(entry.get("category"), "");
			String name = Objects.toString(entry.get("name"), "");

			// Death storages are per-instance (uuid keyed) and were copied with their metadata already.
			if ("death".equals(category))
			{
				continue;
			}

			Storage<?> storage = smm.findStorage(category, name).orElse(null);
			if (!(storage instanceof ItemStorage))
			{
				continue;
			}

			String key = category + "." + storage.getType().getConfigKey();
			if (mode == Mode.FILL_GAPS && storagesWithDataBefore.contains(key))
			{
				continue;
			}

			((ItemStorage<?>) storage).importItems(parseStacks(entry.get("items")),
				toLong(entry.get("lastUpdated"), -1));
			applied++;
		}

		return applied;
	}

	/** Reads the {@code items} list of one storage entry from a DWMS live response. */
	@SuppressWarnings("unchecked")
	private List<ItemStack> parseStacks(Object itemsObj)
	{
		List<ItemStack> stacks = new ArrayList<>();
		if (!(itemsObj instanceof List))
		{
			return stacks;
		}

		for (Object itemObj : (List<Object>) itemsObj)
		{
			if (!(itemObj instanceof Map))
			{
				continue;
			}

			Map<String, Object> item = (Map<String, Object>) itemObj;
			long id = toLong(item.get("id"), -1);
			long quantity = toLong(item.get("quantity"), 0);
			if (id > 0 && quantity > 0)
			{
				stacks.add(new ItemStack((int) id, quantity, plugin));
			}
		}
		return stacks;
	}

	private static long toLong(Object value, long fallback)
	{
		return value instanceof Number ? ((Number) value).longValue() : fallback;
	}

	private void finish(Result result, @Nullable Consumer<Result> callback)
	{
		lastResult = result;
		importing = false;
		log.info("DWMS import: {}", result.getMessage());
		if (callback != null)
		{
			callback.accept(result);
		}
	}

	@Value
	private static class Pending
	{
		Mode mode;
		@Nullable Consumer<Result> callback;
		int configKeysCopied;
		Set<String> storagesWithDataBefore;
		int deadlineTick;
	}
}

package io.robrichardson.banklessbank.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Getter;

/**
 * The player's arrangement of items into tabs and free-floating slots. Exactly one tab is always
 * flagged {@link BankTab#isMain()} and always exists (see {@link #getMainTab()}); it can sit
 * anywhere in {@link #getTabs()} - it is reorderable like any other tab, just never deletable. Up
 * to {@link #MAX_TABS} tabs exist in total. Keys are canonical item ids.
 */
public class BankLayout
{
	/**
	 * Most tabs a layout may hold, the main tab included. The real bank stops at nine; we do not,
	 * because the tab strip wraps onto extra rows rather than clipping (see {@code BankGeometry}).
	 *
	 * <p>Not unlimited, for three reasons. The strip is capped at {@code BankGeometry.MAX_STRIP_ROWS}
	 * rows, past which buttons shrink towards illegibility. {@link #normalise()} needs a deterministic
	 * bound to merge a surplus against. And the decisive one: the layout is a single RS-profile config
	 * value, which always cloud-syncs and is truncated server-side past 262144 bytes, so the largest
	 * layout the model can express has to stay inside that. A tab holds up to
	 * {@link BankTab#MAX_SLOTS} ids, which is roughly 9.5KB of JSON, so twenty tabs is about 190KB -
	 * inside the limit with headroom, where thirty would be about 280KB and could be silently cut off.
	 * At twenty, the minimum-width window still lays all 22 strip buttons out six to a row over four
	 * rows at 34px each, close to the natural {@code BankGeometry.TAB_W} and far above
	 * {@code BankGeometry.MIN_TAB_W}.
	 */
	public static final int MAX_TABS = 20;

	@Getter
	private List<BankTab> tabs = new ArrayList<>();

	/** Canonical ids that must never be drawn as placeholders. Insertion-ordered for stable JSON. */
	private Set<Integer> placeholderIgnoreIds = new LinkedHashSet<>();

	public BankLayout()
	{
		BankTab main = new BankTab("Main");
		main.setMain(true);
		tabs.add(main);
	}

	/**
	 * The one tab flagged {@link BankTab#isMain()}, wherever it currently sits in the strip.
	 * {@link #normalise()} guarantees exactly one exists; falls back to index 0 defensively for a
	 * layout used before normalisation (e.g. directly in a test).
	 */
	public BankTab getMainTab()
	{
		int idx = indexOfMainTab();
		return tabs.get(idx >= 0 ? idx : 0);
	}

	/** Index of the tab flagged {@link BankTab#isMain()}, or -1 if none is (pre-normalise only). */
	public int indexOfMainTab()
	{
		for (int i = 0; i < tabs.size(); i++)
		{
			if (tabs.get(i).isMain())
			{
				return i;
			}
		}
		return -1;
	}

	/** Repairs a layout loaded from config (missing main tab, duplicates, empty custom tabs). */
	public void normalise()
	{
		if (tabs == null)
		{
			tabs = new ArrayList<>();
		}
		// Deserialised JSON can carry a null element where a tab object was expected; drop those
		// before anything below dereferences one.
		tabs.removeIf(Objects::isNull);
		if (tabs.isEmpty())
		{
			BankTab main = new BankTab("Main");
			main.setMain(true);
			tabs.add(main);
		}

		// Exactly one tab is ever flagged main. Legacy JSON saved before the flag existed has none,
		// so slot 0 becomes main, matching the old implicit rule; corrupt JSON with more than one
		// keeps only the first and demotes the rest, never leaving zero or several.
		boolean foundMain = false;
		for (BankTab tab : tabs)
		{
			if (tab.isMain())
			{
				if (foundMain)
				{
					tab.setMain(false);
				}
				foundMain = true;
			}
		}
		if (!foundMain)
		{
			tabs.get(0).setMain(true);
		}

		for (int t = 0; t < tabs.size(); t++)
		{
			BankTab tab = tabs.get(t);
			if (tab.getSlots() == null)
			{
				tab.setSlots(new ArrayList<>());
			}
			// Null (JSON saved before the name field existed) or blank (a rename that emptied it out
			// without going through renameTab, or corrupt JSON) both fall back to the same default a
			// rename resets to - "Main"/"Tab N" - so a legacy or corrupted layout never shows a blank
			// title or divider label.
			if (tab.getName() == null || tab.getName().trim().isEmpty())
			{
				tab.setName(defaultTabName(t));
			}

			// A corrupt or absent width would otherwise divide the grid by zero.
			tab.setCols(tab.getCols());

			List<Integer> slots = tab.getSlots();
			while (slots.size() > tab.maxSlots())
			{
				slots.remove(slots.size() - 1);
			}

			// Card 27: uniqueness is per-tab, not per-layout, so the "seen" set is scoped to this tab
			// alone - the same id may legitimately repeat across different tabs.
			Set<Integer> seenInTab = new HashSet<>();
			for (int i = 0; i < slots.size(); i++)
			{
				Integer id = slots.get(i);
				if (id != null && (id <= 0 || !seenInTab.add(id)))
				{
					slots.set(i, null);
				}
			}
			tab.trimTrailingNulls();
		}

		for (BankTab tab : tabs)
		{
			if (tab.getIcon() > 0 && !tab.contains(tab.getIcon()))
			{
				tab.setIcon(-1);
			}
		}

		// Delete from the end, but never the main tab (deleteTab is already a no-op on it) - skip
		// back past it so a main tab saved last still lets surplus tabs merge away.
		while (tabs.size() > MAX_TABS)
		{
			int victim = tabs.size() - 1;
			while (victim >= 0 && tabs.get(victim).isMain())
			{
				victim--;
			}
			deleteTab(victim);
		}

		if (placeholderIgnoreIds == null)
		{
			placeholderIgnoreIds = new LinkedHashSet<>();
		}
		placeholderIgnoreIds.removeIf(id -> id == null || id <= 0);
	}

	/**
	 * Brings the layout in line with what the player owns: unseen ids are appended after the last
	 * occupied slot of the main tab and, when placeholders are off, ids no longer owned have their
	 * slot blanked (never removed from the list, so later items keep their positions).
	 *
	 * @return true if the layout changed
	 */
	public boolean sync(Set<Integer> ownedIds, boolean keepPlaceholders)
	{
		boolean changed = false;
		Set<Integer> present = new HashSet<>();

		for (int t = tabs.size() - 1; t >= 0; t--)
		{
			BankTab tab = tabs.get(t);
			List<Integer> slots = tab.getSlots();
			for (int i = 0; i < slots.size(); i++)
			{
				Integer id = slots.get(i);
				if (id == null)
				{
					continue;
				}
				if (!keepPlaceholders && !ownedIds.contains(id))
				{
					slots.set(i, null);
					changed = true;
					continue;
				}
				present.add(id);
			}

			tab.trimTrailingNulls();
			if (!tab.isMain() && tab.isEmpty())
			{
				tabs.remove(t);
				changed = true;
			}
		}

		for (int id : ownedIds)
		{
			if (present.add(id))
			{
				getMainTab().append(id);
				changed = true;
			}
		}

		return changed;
	}

	/**
	 * The <b>first</b> tab holding this id, or -1. With duplication there may be several - see
	 * {@link #tabsContaining(int)}.
	 */
	public int indexOfTab(int itemId)
	{
		for (int i = 0; i < tabs.size(); i++)
		{
			if (tabs.get(i).contains(itemId))
			{
				return i;
			}
		}
		return -1;
	}

	/** Number of tabs holding this id: 0, or 1 when it is not duplicated. */
	public int copyCount(int itemId)
	{
		return tabsContaining(itemId).size();
	}

	/** Tab indices holding this id, in strip order. Empty when the id is not in the layout. */
	public List<Integer> tabsContaining(int itemId)
	{
		List<Integer> result = new ArrayList<>();
		for (int i = 0; i < tabs.size(); i++)
		{
			if (tabs.get(i).contains(itemId))
			{
				result.add(i);
			}
		}
		return result;
	}

	/** True when {@code toTab} exists, does not already hold the id, and has room for one more. */
	public boolean canCopyTo(int itemId, int toTab)
	{
		BankTab tab = getTab(toTab);
		return tab != null && !tab.contains(itemId) && tab.appendIndex() < tab.maxSlots();
	}

	/**
	 * Moves the id at {@code (fromTab, fromSlot)} to {@code (toTab, toSlot)}. When the target slot is
	 * occupied the two swap, the occupant taking the vacated source slot. A no-op (returns false) for
	 * an out-of-range tab or slot, an empty source slot, a drop onto the source's own slot, or when
	 * the move would put an id into a tab that already holds another copy of it (see below). Prunes
	 * emptied non-main tabs.
	 */
	public boolean moveSlot(int fromTab, int fromSlot, int toTab, int toSlot)
	{
		BankTab from = getTab(fromTab);
		BankTab to = getTab(toTab);
		if (from == null || to == null || fromSlot < 0 || fromSlot >= from.getSlots().size()
			|| toSlot < 0 || toSlot >= to.maxSlots())
		{
			return false;
		}

		Integer itemId = from.itemAt(fromSlot);
		if (itemId == null)
		{
			return false;
		}

		if (from == to && fromSlot == toSlot)
		{
			return false;
		}

		Integer occupant = to.itemAt(toSlot);

		// Card 27: a move can never duplicate an id within one tab. Same-tab moves/swaps can never
		// break per-tab uniqueness (a permutation of one tab's own slots), so only cross-tab moves are
		// checked, in both directions for a swap.
		if (from != to)
		{
			if (occupant == null && to.contains(itemId))
			{
				return false;
			}
			if (occupant != null && (occupant.equals(itemId) || to.contains(itemId) || from.contains(occupant)))
			{
				return false;
			}
		}

		from.removeAt(fromSlot);
		if (occupant != null)
		{
			from.setAt(fromSlot, occupant);
		}
		to.setAt(toSlot, itemId);

		pruneEmptyTabs();
		return true;
	}

	/**
	 * Moves the id at {@code (fromTab, fromSlot)} to the end of {@code toTab}
	 * ({@link BankTab#appendIndex()}). Same duplication refusal as {@link #moveSlot}.
	 */
	public boolean moveSlotToTab(int fromTab, int fromSlot, int toTab)
	{
		BankTab to = getTab(toTab);
		if (to == null)
		{
			return false;
		}
		return moveSlot(fromTab, fromSlot, toTab, to.appendIndex());
	}

	/**
	 * Blanks the slot, pruning the tab when it is a non-main tab left empty. This is "remove this
	 * copy": the id survives in every other tab holding it.
	 */
	public boolean removeSlot(int tabIndex, int slotIndex)
	{
		BankTab tab = getTab(tabIndex);
		if (tab == null || !tab.removeAt(slotIndex))
		{
			return false;
		}
		pruneEmptyTabs();
		return true;
	}

	/**
	 * Adds a second (or third...) slot for an id at the end of {@code toTab}. A no-op returning -1
	 * for a non-positive id, an out-of-range tab, a tab that already holds the id, or a tab with no
	 * room ({@link BankTab#maxSlots()}).
	 *
	 * @return the slot index the copy landed at, or -1
	 */
	public int copyItemToTab(int itemId, int toTab)
	{
		if (itemId <= 0)
		{
			return -1;
		}
		BankTab tab = getTab(toTab);
		if (tab == null || tab.contains(itemId))
		{
			return -1;
		}
		int index = tab.appendIndex();
		if (index >= tab.maxSlots())
		{
			return -1;
		}
		tab.setAt(index, itemId);
		return index;
	}

	/**
	 * A new tab holding {@code itemId}, leaving every existing copy where it is. Used by a drop of a
	 * search result onto the plus button, which copies rather than moves.
	 *
	 * @return the new tab's index, or -1 at the tab limit
	 */
	public int createTabWith(int itemId)
	{
		if (itemId <= 0 || tabs.size() >= MAX_TABS)
		{
			return -1;
		}
		BankTab tab = new BankTab("Tab " + tabs.size());
		tab.append(itemId);
		tabs.add(tab);
		return tabs.indexOf(tab);
	}

	/**
	 * A new tab holding the id at {@code (fromTab, fromSlot)}, blanking that slot. Used by a grid drag
	 * onto the plus button and by the "New tab from <item>" menu row.
	 *
	 * @return the new tab's index, or -1 at the tab limit or for an empty source slot
	 */
	public int createTabFrom(int fromTab, int fromSlot)
	{
		BankTab from = getTab(fromTab);
		if (from == null || tabs.size() >= MAX_TABS)
		{
			return -1;
		}
		Integer itemId = from.itemAt(fromSlot);
		if (itemId == null)
		{
			return -1;
		}
		from.removeAt(fromSlot);
		BankTab tab = new BankTab("Tab " + tabs.size());
		tab.append(itemId);
		tabs.add(tab);
		pruneEmptyTabs();
		return tabs.indexOf(tab);
	}

	/**
	 * Blanks the slot if the player does not own the id it holds. The slot-addressed form of
	 * {@link #releasePlaceholder(int, Set)}; releases one copy only.
	 */
	public boolean releasePlaceholderAt(int tabIndex, int slotIndex, Set<Integer> ownedIds)
	{
		BankTab tab = getTab(tabIndex);
		if (tab == null)
		{
			return false;
		}
		Integer itemId = tab.itemAt(slotIndex);
		if (itemId == null || ownedIds.contains(itemId))
		{
			return false;
		}
		tab.removeAt(slotIndex);
		if (!tab.isMain() && tab.isEmpty())
		{
			tabs.remove(tabIndex);
		}
		return true;
	}

	/**
	 * Moves a tab from one index to another (list move, not a swap). Any tab, including the main
	 * tab, can move to any position - main is identified by {@link BankTab#isMain()}, not by list
	 * position, so dragging it elsewhere in the strip does not change what it is. {@code to} is
	 * clamped into {@code [0, tabs.size() - 1]}.
	 *
	 * @return true when the order changed
	 */
	public boolean moveTab(int from, int to)
	{
		if (from < 0 || from >= tabs.size())
		{
			return false;
		}

		int clampedTo = Math.max(0, Math.min(to, tabs.size() - 1));
		if (clampedTo == from)
		{
			return false;
		}

		BankTab tab = tabs.remove(from);
		int insertAt = Math.max(0, Math.min(clampedTo, tabs.size()));
		tabs.add(insertAt, tab);
		return true;
	}

	/**
	 * Sets a tab's icon. The item must occupy a slot in that tab; otherwise this is a no-op.
	 * {@code itemId <= 0} clears the icon back to "first occupied slot".
	 *
	 * @return true when the icon changed
	 */
	public boolean setTabIcon(int tabIndex, int itemId)
	{
		BankTab tab = getTab(tabIndex);
		if (tab == null)
		{
			return false;
		}

		if (itemId <= 0)
		{
			if (tab.getIcon() == -1)
			{
				return false;
			}
			tab.setIcon(-1);
			return true;
		}

		if (!tab.contains(itemId) || tab.getIcon() == itemId)
		{
			return false;
		}

		tab.setIcon(itemId);
		return true;
	}

	/**
	 * Longest name a rename can set (in UTF-16 chars); anything longer is truncated.
	 */
	public static final int MAX_TAB_NAME_LENGTH = 20;

	/**
	 * Renames a tab: the given name is trimmed and capped at {@link #MAX_TAB_NAME_LENGTH} chars,
	 * and a blank (or all-whitespace) name resets the tab back to its default - "Main" for the main
	 * tab, "Tab {@code N}" (1-based on its current position in the strip) for any other. A no-op for
	 * an out-of-range index.
	 *
	 * @return true when the name changed
	 */
	public boolean renameTab(int tabIndex, String newName)
	{
		BankTab tab = getTab(tabIndex);
		if (tab == null)
		{
			return false;
		}

		String trimmed = newName == null ? "" : newName.trim();
		if (trimmed.length() > MAX_TAB_NAME_LENGTH)
		{
			trimmed = trimmed.substring(0, MAX_TAB_NAME_LENGTH);
		}

		String resolved = trimmed.isEmpty() ? defaultTabName(tabIndex) : trimmed;
		if (resolved.equals(tab.getName()))
		{
			return false;
		}

		tab.setName(resolved);
		return true;
	}

	/** "Main" for the main tab, "Tab {@code N}" (1-based) for any other tab at this index. */
	private String defaultTabName(int tabIndex)
	{
		BankTab tab = getTab(tabIndex);
		return tab != null && tab.isMain() ? "Main" : "Tab " + (tabIndex + 1);
	}

	/**
	 * Collapses a tab's interior blank slots, packing its items down while preserving their order
	 * (a hidden placeholder still holds its slot, so it packs down with everything else rather than
	 * being dropped) and re-laying them out at {@code cols} - the window's current column count when
	 * this comes from "Collapse blank spaces", which is what makes that entry reflow the tab to fit
	 * the window. A no-op for an out-of-range index, or a tab that already has no gaps and is already
	 * that wide.
	 *
	 * @return true when the tab changed
	 */
	public boolean compactTab(int tabIndex, int cols)
	{
		BankTab tab = getTab(tabIndex);
		return tab != null && tab.compact(cols);
	}

	/**
	 * Widens a tab's layout to at least {@code cols} columns, re-indexing its ids so each keeps the
	 * {@code (row, col)} it renders at. What a drop onto a blank column past the tab's right edge
	 * does. A no-op for an out-of-range index or a tab that is already that wide.
	 *
	 * @return true when the tab changed
	 */
	public boolean widenTab(int tabIndex, int cols)
	{
		BankTab tab = getTab(tabIndex);
		return tab != null && tab.widenTo(cols);
	}

	public Set<Integer> getPlaceholderIgnoreIds()
	{
		return Collections.unmodifiableSet(placeholderIgnoreIds);
	}

	public boolean isPlaceholderIgnored(int itemId)
	{
		return placeholderIgnoreIds.contains(itemId);
	}

	/** @return true when newly added */
	public boolean addPlaceholderIgnore(int itemId)
	{
		return itemId > 0 && placeholderIgnoreIds.add(itemId);
	}

	/** @return true when removed */
	public boolean removePlaceholderIgnore(int itemId)
	{
		return placeholderIgnoreIds.remove(itemId);
	}

	/** Removes every id from the ignore list. @return true when anything was removed */
	public boolean clearPlaceholderIgnores()
	{
		if (placeholderIgnoreIds.isEmpty())
		{
			return false;
		}
		placeholderIgnoreIds.clear();
		return true;
	}

	/**
	 * Adds an item the player need not own to the end of a tab, at {@link BankTab#appendIndex()}.
	 * This is the manual-add path (the bottom bar's item search): until the item is owned it renders
	 * as an ordinary placeholder, and from then on it drags, moves and releases like anything else.
	 *
	 * <p>Card 27: the guard is per-tab, not layout-wide - an id already elsewhere in the layout can
	 * still be added here as a second copy. This is {@link #copyItemToTab(int, int)} in boolean
	 * clothing; the manual-add entry point is kept as its own method for callers.
	 *
	 * @return true when the layout changed
	 */
	public boolean addItem(int itemId, int tabIndex)
	{
		return copyItemToTab(itemId, tabIndex) >= 0;
	}

	/**
	 * Deletes a custom tab, appending its occupied ids (gaps dropped) to the end of the main tab.
	 * A no-op for an out-of-range index or the main tab itself, wherever it currently sits.
	 *
	 * <p>Card 27: an id main already holds is skipped rather than merged again, which would otherwise
	 * duplicate it within main - the copy is dropped because main already has one; that is a merge,
	 * not a loss.
	 */
	public void deleteTab(int index)
	{
		if (index < 0 || index >= tabs.size() || tabs.get(index).isMain())
		{
			return;
		}

		BankTab tab = tabs.remove(index);
		BankTab main = getMainTab();
		for (int id : tab.itemIds())
		{
			if (!main.contains(id))
			{
				main.append(id);
			}
		}
	}

	/**
	 * Releases a placeholder: blanks its slot if the player does not own it. Delegates to
	 * {@link #releasePlaceholderAt(int, int, Set)} on the <b>first</b> tab holding it; only meaningful
	 * where {@link #copyCount(int)} is 1, since with duplication the other copies are untouched.
	 */
	public boolean releasePlaceholder(int itemId, Set<Integer> ownedIds)
	{
		int tabIdx = indexOfTab(itemId);
		if (tabIdx == -1)
		{
			return false;
		}
		return releasePlaceholderAt(tabIdx, tabs.get(tabIdx).indexOf(itemId), ownedIds);
	}

	/** Releases every placeholder in a tab (or every tab when index is -1). */
	public int releaseAllPlaceholders(int tabIndex, Set<Integer> ownedIds)
	{
		int released = 0;
		for (int t = tabs.size() - 1; t >= 0; t--)
		{
			if (tabIndex != -1 && t != tabIndex)
			{
				continue;
			}

			BankTab tab = tabs.get(t);
			for (int id : new ArrayList<>(tab.itemIds()))
			{
				if (!ownedIds.contains(id))
				{
					tab.removeItem(id);
					released++;
				}
			}

			if (!tab.isMain() && tab.isEmpty())
			{
				tabs.remove(t);
			}
		}

		return released;
	}

	private void pruneEmptyTabs()
	{
		for (int t = tabs.size() - 1; t >= 0; t--)
		{
			if (!tabs.get(t).isMain() && tabs.get(t).isEmpty())
			{
				tabs.remove(t);
			}
		}
	}

	@Nullable
	public BankTab getTab(int index)
	{
		return index >= 0 && index < tabs.size() ? tabs.get(index) : null;
	}
}

package io.robrichardson.banklessbank.model;

import java.util.ArrayList;
import java.util.List;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One bank tab: a sparse, positional list of canonical item ids. Index i in {@link #getSlots()} is
 * grid slot i; a {@code null} entry is a deliberate empty slot. Ids the player no longer owns stay
 * in place as placeholders until released. Trailing nulls are never stored.
 *
 * <p>A tab also carries its own layout width, {@link #getCols()}, which alone decides where a slot
 * index lands: index {@code i} is at {@code (i / cols, i % cols)}. The window's column count is a
 * viewport over that grid, never an input to it, so resizing the window never moves an item.
 * Widening the tab ({@link #widenTo(int)}) re-indexes every id so each keeps its {@code (row, col)};
 * {@link #compact(int)} is the deliberate reflow, packing the ids down at a new width.
 *
 * <p>An id occurs at most once in a tab, but may occur in several tabs - see {@link BankLayout} for
 * the duplication rules.
 */
@Data
@NoArgsConstructor
public class BankTab
{
	/** Narrowest layout width, matching the window's narrowest column count. */
	public static final int MIN_COLS = 4;
	/** Widest layout width, matching the window's widest column count. */
	public static final int MAX_COLS = 16;
	/** Layout width of a tab saved before tabs had one, and of every new tab. */
	public static final int DEFAULT_COLS = 8;
	/** Hard cap on a tab's rows, to bound a corrupt saved layout. */
	public static final int MAX_ROWS = 100;
	/**
	 * Absolute cap on a tab's addressable slots: {@link #MAX_ROWS} rows at the widest layout. The
	 * per-tab cap is {@link #maxSlots()}, which is this only at {@link #MAX_COLS}; the constant
	 * exists so widening a full narrow tab can never push an id past an addressable index.
	 */
	public static final int MAX_SLOTS = MAX_ROWS * MAX_COLS;

	private String name = "";
	/** Sparse: entry i is the id at slot i, or null for an empty slot. Never has trailing nulls. */
	private List<Integer> slots = new ArrayList<>();
	/** Explicit icon item id, or -1 to fall back to the first occupied slot. */
	private int icon = -1;
	/**
	 * Whether this is the one tab that always exists and cannot be deleted. Identifies "Main" by
	 * flag, not by list position, so it stays main wherever the player drags it in the strip.
	 * Absent (false) on JSON saved before this flag existed; {@link BankLayout#normalise()} then
	 * treats slot 0 as main, matching the old implicit rule.
	 */
	private boolean main;
	/**
	 * This tab's layout width in columns: index {@code i} sits at {@code (i / cols, i % cols)}.
	 * Absent (so {@value #DEFAULT_COLS}) on JSON saved before tabs had a width, which is exactly the
	 * fixed column count those layouts were arranged at. Always in
	 * {@link #MIN_COLS}..{@link #MAX_COLS}; {@link BankLayout#normalise()} repairs a corrupt value.
	 */
	private int cols = DEFAULT_COLS;

	public BankTab(String name)
	{
		this.name = name;
	}

	// ---- reads -------------------------------------------------------------------------------

	/** {@code c} brought into {@link #MIN_COLS}..{@link #MAX_COLS}. */
	public static int clampCols(int c)
	{
		return Math.max(MIN_COLS, Math.min(MAX_COLS, c));
	}

	/** Highest addressable slot count at this tab's width: {@link #MAX_ROWS} rows of it. */
	public int maxSlots()
	{
		return MAX_ROWS * cols;
	}

	/** Grid row of a flat slot index, at this tab's layout width. */
	public int rowOf(int index)
	{
		return index / cols;
	}

	/** Grid column of a flat slot index, at this tab's layout width. */
	public int colOf(int index)
	{
		return index % cols;
	}

	/** Flat slot index of a grid position, at this tab's layout width. */
	public int indexAt(int row, int col)
	{
		return row * cols + col;
	}

	/** Id at the slot, or null when the slot is empty or out of range. */
	public Integer itemAt(int index)
	{
		if (index < 0 || index >= slots.size())
		{
			return null;
		}
		return slots.get(index);
	}

	/** Slot index of the id, or -1. */
	public int indexOf(int itemId)
	{
		return slots.indexOf(Integer.valueOf(itemId));
	}

	public boolean contains(int itemId)
	{
		return indexOf(itemId) != -1;
	}

	/** Non-null ids in slot order. A fresh list; mutating it does not affect the tab. */
	public List<Integer> itemIds()
	{
		List<Integer> ids = new ArrayList<>();
		for (Integer id : slots)
		{
			if (id != null)
			{
				ids.add(id);
			}
		}
		return ids;
	}

	/** Number of occupied slots. */
	public int itemCount()
	{
		int count = 0;
		for (Integer id : slots)
		{
			if (id != null)
			{
				count++;
			}
		}
		return count;
	}

	/** True when no slot is occupied. */
	public boolean isEmpty()
	{
		return itemCount() == 0;
	}

	/** Highest occupied slot index, or -1 when empty. */
	public int maxOccupiedIndex()
	{
		for (int i = slots.size() - 1; i >= 0; i--)
		{
			if (slots.get(i) != null)
			{
				return i;
			}
		}
		return -1;
	}

	/** Where a new item goes: {@code maxOccupiedIndex() + 1}. */
	public int appendIndex()
	{
		return maxOccupiedIndex() + 1;
	}

	/**
	 * The icon to draw: {@link #getIcon()} when it is set and still occupies a slot in this tab,
	 * otherwise the first occupied slot's id, otherwise -1.
	 */
	public int getIconItemId()
	{
		if (icon > 0 && contains(icon))
		{
			return icon;
		}
		for (Integer id : slots)
		{
			if (id != null)
			{
				return id;
			}
		}
		return -1;
	}

	// ---- writes --------------------------------------------------------------------------------

	/** Sets the layout width, clamped to {@link #MIN_COLS}..{@link #MAX_COLS}. Does not re-index. */
	public void setCols(int cols)
	{
		this.cols = clampCols(cols);
	}

	/**
	 * Puts an id (or null) at a slot, growing the backing list with nulls as needed. Ignores an
	 * index below 0 or at/above {@link #maxSlots()}. Trims trailing nulls afterwards.
	 */
	public void setAt(int index, Integer itemId)
	{
		if (index < 0 || index >= maxSlots())
		{
			return;
		}
		while (slots.size() <= index)
		{
			slots.add(null);
		}
		slots.set(index, itemId);
		trimTrailingNulls();
	}

	/** Appends at {@link #appendIndex()}. Convenience for callers and tests. */
	public void append(int itemId)
	{
		setAt(appendIndex(), itemId);
	}

	/** Blanks the slot holding the id. Returns true when something was removed. */
	public boolean removeItem(int itemId)
	{
		int idx = indexOf(itemId);
		if (idx == -1)
		{
			return false;
		}
		setAt(idx, null);
		return true;
	}

	/**
	 * Blanks slot {@code index} whatever it holds, trimming trailing nulls. Unlike
	 * {@link #removeItem(int)} this addresses a slot rather than an id, which is what removing one
	 * copy of a duplicated item needs.
	 *
	 * @return true when the slot held an id
	 */
	public boolean removeAt(int index)
	{
		if (index < 0 || index >= slots.size() || slots.get(index) == null)
		{
			return false;
		}
		setAt(index, null);
		return true;
	}

	/**
	 * Widens the tab, re-indexing every id so each keeps the {@code (row, col)} it renders at. This
	 * is what a drop onto a blank column past the tab's right edge does; the tab grows to hold that
	 * column and nothing already placed appears to move. A no-op when {@code newCols} is not wider
	 * than the current width (narrowing would collide two ids on one cell - {@link #compact(int)} is
	 * the way to a narrower width).
	 *
	 * @return true when the width changed
	 */
	public boolean widenTo(int newCols)
	{
		final int target = clampCols(newCols);
		if (target <= cols)
		{
			return false;
		}

		final List<Integer> widened = new ArrayList<>();
		for (int i = 0; i < slots.size(); i++)
		{
			final Integer id = slots.get(i);
			if (id == null)
			{
				continue;
			}
			final int index = rowOf(i) * target + colOf(i);
			while (widened.size() <= index)
			{
				widened.add(null);
			}
			widened.set(index, id);
		}

		slots = widened;
		cols = target;
		trimTrailingNulls();
		return true;
	}

	/**
	 * Removes interior empty slots, packing the occupied ones down to the front in their existing
	 * order (trailing nulls are already absent, so this alone makes the tab dense). A hidden,
	 * unowned placeholder is still an id in {@link #slots}, so it packs down with everything else
	 * rather than being dropped. A no-op when the tab already has no gaps (including when empty).
	 *
	 * <p>This is also the one place a tab is re-laid-out at a different width: the packed ids are
	 * re-indexed at {@code newCols} (the window's current column count when this comes from
	 * "Collapse blank spaces"), which is what makes the entry reflow the tab to fit the window.
	 *
	 * @return true when the slots or the width changed
	 */
	public boolean compact(int newCols)
	{
		final int target = clampCols(newCols);
		final List<Integer> ids = itemIds();
		if (ids.size() == slots.size() && target == cols)
		{
			return false;
		}

		slots.clear();
		slots.addAll(ids);
		cols = target;
		while (slots.size() > maxSlots())
		{
			slots.remove(slots.size() - 1);
		}
		return true;
	}

	/** Drops trailing nulls. Called by every write above; exposed for {@code normalise()}. */
	public void trimTrailingNulls()
	{
		int last = slots.size() - 1;
		while (last >= 0 && slots.get(last) == null)
		{
			slots.remove(last);
			last--;
		}
	}
}

package io.robrichardson.banklessbank.model;

import com.google.gson.Gson;
import io.robrichardson.banklessbank.BanklessBankConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/** Persists a {@link BankLayout} per RS profile as JSON under the plugin's config group. */
@Slf4j
@Singleton
public class LayoutStore
{
	static final String CONFIG_KEY_LAYOUT = "layout";

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	public LayoutStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public BankLayout load(String profileKey)
	{
		String json = profileKey == null ? null
			: configManager.getConfiguration(BanklessBankConfig.CONFIG_GROUP, profileKey, CONFIG_KEY_LAYOUT);
		if (json == null || json.isEmpty())
		{
			return new BankLayout();
		}

		try
		{
			BankLayout layout = gson.fromJson(json, BankLayout.class);
			if (layout == null)
			{
				return new BankLayout();
			}
			layout.normalise();
			return layout;
		}
		catch (RuntimeException e)
		{
			// JsonSyntaxException for malformed JSON, but also anything normalise() cannot repair in
			// structurally valid but nonsensical saved state. A fresh layout beats letting the
			// exception escape into the render loop, where it would recur every frame.
			log.warn("Discarding unreadable bank layout for profile {}", profileKey, e);
			return new BankLayout();
		}
	}

	public void save(String profileKey, BankLayout layout)
	{
		if (profileKey == null)
		{
			return;
		}

		configManager.setConfiguration(BanklessBankConfig.CONFIG_GROUP, profileKey, CONFIG_KEY_LAYOUT, gson.toJson(layout));
	}
}

