package io.robrichardson.banklessbank.ui;

import io.robrichardson.banklessbank.model.BankTab;
import java.awt.Dimension;
import java.awt.Rectangle;

/**
 * All geometry constants and pure rect maths for the bank overlay. All rects are in overlay-local
 * coordinates (0,0 = overlay top-left).
 *
 * <p>The numbers are taken from a 400x275 screenshot of the real bank interface, which is the
 * game's 488x334 bank widget scaled by 400/488 = 0.8197. Dividing the measured pixels back out
 * gives a 48x36 item slot on an 8-column grid, an 8px steel frame, a 16px scrollbar and a ~30px
 * button bar along the bottom, which is what the constants below encode. Two places deliberately
 * differ: the real bank keeps a ~58px gutter down the left for its deposit buttons, which a viewer
 * has no use for, and its tab buttons are 36 wide rather than the real bank's 48.
 *
 * <p>Unlike the real bank, the window is resizable on both axes, so the column and row counts are
 * per-view values rather than constants: an instance carries one {@code (cols, rows)} pair and
 * every rect is derived from it. Columns run {@link #MIN_COLS}..{@link #MAX_COLS} in whole slots,
 * rows {@link #MIN_ROWS}..{@link #MAX_ROWS}. These are the window's columns, i.e. a viewport: a
 * slot's flat index maps to {@code (index / tabCols, index % tabCols)} at the tab's own layout
 * width, so resizing never moves an item. A window wider than the tab shows blank columns to the
 * right of it; a narrower one scrolls horizontally, which is why the grid has a scrollbar along the
 * bottom as well as down the right.
 *
 * <p>The tab strip holds {@code [All] + up to MAX_TABS tabs + [+]}. At {@value #TAB_W} wide a button
 * is exactly {@link #ITEM_SPRITE_W}, so tab icons draw unscaled. More buttons than fit on one row
 * <i>wrap</i> onto further rows rather than clipping or scrolling: the strip is
 * {@code stripRows * }{@value #TAB_STRIP_H} tall and every rect below it - the grid, both
 * scrollbars, the bottom bar and the resize grip - shifts down with it, so the window simply grows.
 * The strip is capped at {@value #MAX_STRIP_ROWS} rows; only when that cap binds do the buttons fall
 * back to sharing their row evenly (see {@link #tabWidth(int)}), which is what keeps every tab and
 * the [+] reachable at the minimum window width rather than pushing some off the right edge.
 * {@code stripRows} is the geometry's third dimension alongside {@code (cols, rows)}: it is derived
 * from the strip length by {@link #stripRowsFor(int, int)} and is an input to {@link #of(int, int,
 * int)}, never recomputed piecemeal by a caller.
 */
public final class BankGeometry
{
	public static final int BORDER = 8;
	public static final int TITLE_H = 26;
	public static final int CLOSE_SIZE = 25;
	/** Height of one row of the tab strip. The strip is {@code stripRows} of these tall. */
	public static final int TAB_STRIP_H = 40;
	/**
	 * Most rows the tab strip may wrap onto. Past this the buttons shrink to share their row instead,
	 * so a large tab count cannot push the grid off the bottom of the canvas.
	 */
	public static final int MAX_STRIP_ROWS = 4;
	public static final int TAB_W = 36;
	public static final int TAB_H = 36;
	/** Floor on a shrunk tab button, so the strip never collapses to slivers. */
	public static final int MIN_TAB_W = 12;
	public static final int SLOT_W = 48;
	public static final int SLOT_H = 36;
	/** Header/divider row height. Tall enough to fit a small tab icon in the All-view dividers. */
	public static final int HEADER_H = 24;
	/** Left margin reserved for a divider's tab icon, before its label starts. */
	public static final int DIVIDER_ICON_W = 20;
	/** Button bar along the bottom: search button, search text, view-mode button. */
	public static final int BOTTOM_H = 30;
	public static final int BOTTOM_BUTTON = 24;
	public static final int MODE_BUTTON_W = 58;
	public static final int SCROLLBAR_W = 16;
	/** Height of each of the scrollbar's two arrow buttons; also their width. */
	public static final int SCROLL_ARROW = 16;
	public static final int SCROLL_MIN_THUMB = 20;
	/** Window column range, kept identical to a tab's layout width range. */
	public static final int DEFAULT_COLS = BankTab.DEFAULT_COLS;
	public static final int MIN_COLS = BankTab.MIN_COLS;
	public static final int MAX_COLS = BankTab.MAX_COLS;
	public static final int DEFAULT_ROWS = 6;
	public static final int MIN_ROWS = 3;
	public static final int MAX_ROWS = 20;
	/** Self-drawn bottom-right resize grip; square, sits over the frame corner. */
	public static final int GRIP = 16;
	public static final int ITEM_SPRITE_W = 36;
	public static final int ITEM_SPRITE_H = 32;
	public static final int ITEM_DX = 6;
	public static final int ITEM_DY = 2;
	public static final int SCROLL_STEP = 36;

	// Context menu geometry, copied from the game's own "Choose Option" menu so ours is
	// indistinguishable from it: a 1px frame, a 18px header band, then 15px rows, with the text
	// inset 3px from the left and the whole box 8px wider than its widest row. Not part of the
	// design's constant table; used only by ContextMenu / BankViewModel's menu building, which
	// needs some fixed metric since Tier 1 has no Graphics2D / FontMetrics to measure with.
	public static final int MENU_ENTRY_H = 15;
	/** Height of the header band holding {@link ContextMenu#TITLE}, frame included. */
	public static final int MENU_HEADER_H = 18;
	/** Gap between the header band and the first row, as the game leaves. */
	public static final int MENU_BODY_GAP = 2;
	/** Slack added below the last row so the frame closes, matching the game's {@code 15n + 22}. */
	public static final int MENU_BOTTOM_PAD = 2;
	/** Text inset from the menu's left edge, for the header and every row alike. */
	public static final int MENU_TEXT_X = 3;
	/** Total padding added to the widest row's text width. */
	public static final int MENU_PADDING = 8;
	/**
	 * Per-character width estimate for the RuneScape font at the size the menu draws it. Tier 1 has
	 * no FontMetrics, so row widths are estimated; this deliberately over-estimates (real mixed-case
	 * text averages nearer 6px) so a row can never render wider than the box that was sized for it.
	 */
	public static final int MENU_CHAR_W = 7;

	/** The menu box's height for {@code n} rows: the game's {@code 15n + 22}. */
	public static int menuHeight(int entryCount)
	{
		return MENU_HEADER_H + MENU_BODY_GAP + entryCount * MENU_ENTRY_H + MENU_BOTTOM_PAD;
	}

	private final int cols;
	private final int rows;
	private final int stripRows;

	private BankGeometry(int cols, int rows, int stripRows)
	{
		this.cols = cols;
		this.rows = rows;
		this.stripRows = stripRows;
	}

	/**
	 * A geometry for this many columns and rows, both clamped to their legal range, with a
	 * single-row tab strip. Convenience for the many callers whose tab count cannot wrap.
	 */
	public static BankGeometry of(int cols, int rows)
	{
		return of(cols, rows, 1);
	}

	/** A geometry for this many columns, grid rows and tab-strip rows, each clamped. */
	public static BankGeometry of(int cols, int rows, int stripRows)
	{
		return new BankGeometry(clamp(cols, MIN_COLS, MAX_COLS), clamp(rows, MIN_ROWS, MAX_ROWS),
			clamp(stripRows, 1, MAX_STRIP_ROWS));
	}

	public static BankGeometry defaults()
	{
		return of(DEFAULT_COLS, DEFAULT_ROWS);
	}

	public int getCols()
	{
		return cols;
	}

	public int getRows()
	{
		return rows;
	}

	public int getStripRows()
	{
		return stripRows;
	}

	/** The whole strip's height: one {@value #TAB_STRIP_H} band per wrapped row. */
	public int stripHeight()
	{
		return stripRows * TAB_STRIP_H;
	}

	// ---- static size maths -------------------------------------------------------------------

	/** Window width for a column count: both borders, the grid and the scrollbar. */
	public static int width(int cols)
	{
		return chromeWidth() + cols * SLOT_W;
	}

	public static int height(int rows)
	{
		return height(rows, 1);
	}

	/** Window height for a grid row count and a tab strip of {@code stripRows} rows. */
	public static int height(int rows, int stripRows)
	{
		return chromeHeight(stripRows) + rows * SLOT_H;
	}

	/** Chrome width with no columns at all: both borders and the scrollbar. */
	public static int chromeWidth()
	{
		return BORDER * 2 + SCROLLBAR_W;
	}

	/**
	 * Chrome height with no rows at all: both borders, title, tab strip and the bottom bar. No row is
	 * reserved for the horizontal scrollbar: unlike the vertical bar's always-present column, it is
	 * drawn overlaying the bottom of the grid only when the active tab needs it, so the window's
	 * height depends only on {@link #DEFAULT_ROWS} / the viewport row count, never on which tab is
	 * showing or how wide its layout happens to be.
	 */
	public static int chromeHeight()
	{
		return chromeHeight(1);
	}

	/** Chrome height with no rows at all, for a tab strip {@code stripRows} rows tall. */
	public static int chromeHeight(int stripRows)
	{
		return BORDER * 2 + TITLE_H + Math.max(1, stripRows) * TAB_STRIP_H + BOTTOM_H;
	}

	public static Dimension size(int cols, int rows)
	{
		return new Dimension(width(cols), height(rows));
	}

	/** Inner width available to the tab strip at a given window column count. */
	public static int stripWidth(int cols)
	{
		return width(cols) - BORDER * 2;
	}

	/**
	 * How many rows the strip needs to show {@code stripLength} buttons at a window of {@code cols}
	 * columns: as many as it takes to keep every button at its natural {@value #TAB_W}, capped at
	 * {@value #MAX_STRIP_ROWS}. Past the cap the buttons shrink instead ({@link #tabWidth(int)}).
	 */
	public static int stripRowsFor(int cols, int stripLength)
	{
		if (stripLength <= 0)
		{
			return 1;
		}
		int perRow = Math.max(1, stripWidth(clamp(cols, MIN_COLS, MAX_COLS)) / TAB_W);
		int needed = (stripLength + perRow - 1) / perRow;
		return clamp(needed, 1, MAX_STRIP_ROWS);
	}

	/** Columns that a window of this pixel width would have, unclamped. */
	public static int colsForWidth(int pixelWidth)
	{
		return Math.round((pixelWidth - chromeWidth()) / (float) SLOT_W);
	}

	/** Rows that a window of this pixel height would have, unclamped. */
	public static int rowsForHeight(int pixelHeight)
	{
		return rowsForHeight(pixelHeight, 1);
	}

	/** Rows that a window of this pixel height would have with a {@code stripRows}-row strip. */
	public static int rowsForHeight(int pixelHeight, int stripRows)
	{
		return Math.round((pixelHeight - chromeHeight(stripRows)) / (float) SLOT_H);
	}

	// ---- instance rects ----------------------------------------------------------------------

	public int width()
	{
		return width(cols);
	}

	public int height()
	{
		return height(rows, stripRows);
	}

	public int gridWidth()
	{
		return cols * SLOT_W;
	}

	public Dimension size()
	{
		return new Dimension(width(), height());
	}

	/** The resize grip, in overlay-local coordinates. */
	public Rectangle resizeGrip()
	{
		return new Rectangle(width() - GRIP, height() - GRIP, GRIP, GRIP);
	}

	public Rectangle titleBar()
	{
		return new Rectangle(BORDER, BORDER, width() - BORDER * 2, TITLE_H);
	}

	public Rectangle closeButton()
	{
		Rectangle bar = titleBar();
		int x = width() - BORDER - 2 - CLOSE_SIZE;
		int y = bar.y + (TITLE_H - CLOSE_SIZE) / 2;
		return new Rectangle(x, y, CLOSE_SIZE, CLOSE_SIZE);
	}

	public Rectangle tabStrip()
	{
		return new Rectangle(BORDER, BORDER + TITLE_H, width() - BORDER * 2, stripHeight());
	}

	/**
	 * How many buttons sit on each strip row: the strip length spread evenly over
	 * {@link #getStripRows()} rows, so the last row is the only short one.
	 */
	public int tabsPerRow(int stripLength)
	{
		if (stripLength <= 0)
		{
			return 1;
		}
		return Math.max(1, (stripLength + stripRows - 1) / stripRows);
	}

	/**
	 * Width of one tab button when the strip holds {@code stripLength} of them: the natural
	 * {@value #TAB_W} whenever they all fit, otherwise an even share of the strip so nothing is
	 * pushed off the right edge. Never below {@value #MIN_TAB_W}.
	 */
	public int tabWidth(int stripLength)
	{
		if (stripLength <= 0)
		{
			return TAB_W;
		}
		int share = tabStrip().width / tabsPerRow(stripLength);
		return clamp(share, MIN_TAB_W, TAB_W);
	}

	/**
	 * 0 = All, 1..n = layout tabs, n+1 = plus, wrapping onto successive strip rows once one row is
	 * full.
	 */
	public Rectangle tabAt(int stripIndex, int stripLength)
	{
		Rectangle strip = tabStrip();
		int w = tabWidth(stripLength);
		int perRow = tabsPerRow(stripLength);
		int row = Math.max(0, stripIndex) / perRow;
		int col = Math.max(0, stripIndex) % perRow;
		int x = strip.x + col * w;
		int y = strip.y + row * TAB_STRIP_H + (TAB_STRIP_H - TAB_H) / 2;
		return new Rectangle(x, y, w, TAB_H);
	}

	/** Viewport, excludes the scrollbar. */
	public Rectangle grid()
	{
		int y = BORDER + TITLE_H + stripHeight();
		return new Rectangle(BORDER, y, gridWidth(), rows * SLOT_H);
	}

	/** The whole scrollbar column: up arrow, track, down arrow. */
	public Rectangle scrollbar()
	{
		Rectangle grid = grid();
		return new Rectangle(grid.x + grid.width, grid.y, SCROLLBAR_W, grid.height);
	}

	public Rectangle scrollUp()
	{
		Rectangle bar = scrollbar();
		return new Rectangle(bar.x, bar.y, SCROLLBAR_W, SCROLL_ARROW);
	}

	public Rectangle scrollDown()
	{
		Rectangle bar = scrollbar();
		return new Rectangle(bar.x, bar.y + bar.height - SCROLL_ARROW, SCROLLBAR_W, SCROLL_ARROW);
	}

	/** The draggable part of the scrollbar, between the two arrow buttons. */
	public Rectangle scrollTrack()
	{
		Rectangle bar = scrollbar();
		int h = Math.max(0, bar.height - SCROLL_ARROW * 2);
		return new Rectangle(bar.x, bar.y + SCROLL_ARROW, SCROLLBAR_W, h);
	}

	/**
	 * The whole horizontal scrollbar row: left arrow, track, right arrow. Unlike the vertical
	 * scrollbar's own column, this is not reserved space - it overlays the bottom 16px of the grid
	 * area, so it is only meaningful to draw or hit-test when the caller knows a wider-than-viewport
	 * tab makes it visible ({@code BankViewModel.isHScrollbarVisible()}).
	 */
	public Rectangle hScrollbar()
	{
		Rectangle grid = grid();
		return new Rectangle(grid.x, grid.y + grid.height - SCROLLBAR_W, gridWidth(), SCROLLBAR_W);
	}

	public Rectangle hScrollLeft()
	{
		Rectangle bar = hScrollbar();
		return new Rectangle(bar.x, bar.y, SCROLL_ARROW, SCROLLBAR_W);
	}

	public Rectangle hScrollRight()
	{
		Rectangle bar = hScrollbar();
		return new Rectangle(bar.x + bar.width - SCROLL_ARROW, bar.y, SCROLL_ARROW, SCROLLBAR_W);
	}

	/** The draggable part of the horizontal scrollbar, between its two arrow buttons. */
	public Rectangle hScrollTrack()
	{
		Rectangle bar = hScrollbar();
		int w = Math.max(0, bar.width - SCROLL_ARROW * 2);
		return new Rectangle(bar.x + SCROLL_ARROW, bar.y, w, SCROLLBAR_W);
	}

	/** The whole bottom button bar, full inner width. Sits directly under the grid. */
	public Rectangle bottomBar()
	{
		Rectangle grid = grid();
		return new Rectangle(BORDER, grid.y + grid.height, gridWidth() + SCROLLBAR_W, BOTTOM_H);
	}

	public Rectangle searchButton()
	{
		Rectangle bar = bottomBar();
		return new Rectangle(bar.x + 2, bar.y + (BOTTOM_H - BOTTOM_BUTTON) / 2,
			BOTTOM_BUTTON, BOTTOM_BUTTON);
	}

	public Rectangle modeButton()
	{
		Rectangle bar = bottomBar();
		return new Rectangle(bar.x + bar.width - 2 - MODE_BUTTON_W,
			bar.y + (BOTTOM_H - BOTTOM_BUTTON) / 2, MODE_BUTTON_W, BOTTOM_BUTTON);
	}

	/**
	 * The "add an item" button, immediately left of the view-mode button. Square like the search
	 * button, and the reason {@link #searchBox()} measures its right edge from here rather than from
	 * the mode button.
	 */
	public Rectangle addButton()
	{
		Rectangle mode = modeButton();
		return new Rectangle(mode.x - 3 - BOTTOM_BUTTON, mode.y, BOTTOM_BUTTON, BOTTOM_BUTTON);
	}

	/** The search text field: everything on the bar between the search button and the add button. */
	public Rectangle searchBox()
	{
		Rectangle button = searchButton();
		Rectangle add = addButton();
		int x = button.x + button.width + 3;
		return new Rectangle(x, button.y, Math.max(0, add.x - 3 - x), BOTTOM_BUTTON);
	}

	public Rectangle slotInRow(int rowLocalY, int col)
	{
		return new Rectangle(BORDER + col * SLOT_W, rowLocalY, SLOT_W, SLOT_H);
	}

	public static Rectangle thumb(Rectangle track, int scroll, int maxScroll, int contentH, int viewportH)
	{
		int thumbH = track.height;
		if (contentH > 0 && contentH > viewportH)
		{
			thumbH = Math.max(SCROLL_MIN_THUMB, track.height * viewportH / contentH);
			thumbH = Math.min(thumbH, track.height);
		}

		int thumbY = track.y;
		if (maxScroll > 0)
		{
			int range = track.height - thumbH;
			thumbY = track.y + (int) ((long) range * scroll / maxScroll);
		}

		return new Rectangle(track.x, thumbY, track.width, thumbH);
	}

	/** {@link #thumb} turned on its side, for the horizontal scrollbar. */
	public static Rectangle hThumb(Rectangle track, int scroll, int maxScroll, int contentW, int viewportW)
	{
		int thumbW = track.width;
		if (contentW > 0 && contentW > viewportW)
		{
			thumbW = Math.max(SCROLL_MIN_THUMB, track.width * viewportW / contentW);
			thumbW = Math.min(thumbW, track.width);
		}

		int thumbX = track.x;
		if (maxScroll > 0)
		{
			int range = track.width - thumbW;
			thumbX = track.x + (int) ((long) range * scroll / maxScroll);
		}

		return new Rectangle(thumbX, track.y, thumbW, track.height);
	}

	private static int clamp(int v, int lo, int hi)
	{
		return Math.max(lo, Math.min(hi, v));
	}
}

package io.robrichardson.banklessbank.ui;

import io.robrichardson.banklessbank.BanklessBankConfig;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.Getter;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseWheelListener;
import net.runelite.client.util.HotkeyListener;

/**
 * All input for the bank view. Runs on the AWT event thread and never touches the view model
 * directly: it decides whether to consume from three volatile fields published by
 * {@link BankOverlay} on the client thread, and posts every mutation to the controller's queue so
 * it runs on the client thread at the top of the next frame.
 *
 * <p>Registered by appending to RuneLite's mouse listener list, never at position 0: the
 * Stretched Mode plugin's coordinate translator lives at position 0 and everything behind it,
 * including this listener and RuneLite's own overlay listener, sees canvas-space coordinates that
 * match the bounds published here. A consumed event stops the listener chain and never reaches
 * the game whatever this listener's position is. It must still stand aside while alt is held, or
 * alt-dragging other overlays would stop working.
 */
@Singleton
public class BankInputListener implements MouseListener, MouseWheelListener, KeyListener
{
	private static final Rectangle EMPTY = new Rectangle();
	private static final int DRAG_SLOP = 4;

	private final BanklessBankConfig config;
	private final BankViewController controller;

	// published from the client thread
	private volatile boolean open;
	private volatile Rectangle bounds = EMPTY;
	private volatile boolean altHeld;
	private volatile boolean menuOpen;
	private volatile boolean hudVisible;
	private volatile Rectangle hudBounds = EMPTY;

	/** Canvas coordinates of the last mouse position, or null. Replaced wholesale. */
	@Getter
	private volatile Point lastMouse;

	// Armed on the client thread by the runnable posted from mousePressed, read and cleared on
	// the AWT thread, hence volatile.
	private volatile boolean titleDrag;
	private volatile boolean thumbDrag;
	private volatile boolean hThumbDrag;
	private volatile boolean slotDragArmed;
	private volatile boolean tabDragArmed;
	private volatile int tabPressStripIndex = -1;
	private volatile boolean resizeDrag;

	// AWT thread only
	private Point titleDragOffset;
	private Point resizeGrabOffset;
	private boolean slotDragActive;
	private boolean tabDragActive;
	private Point pressPoint;

	/** True while a consumed press is outstanding, so its release is consumed too. */
	private boolean pressConsumed;

	/** True when the press+release that preceded the next click were both consumed. */
	private boolean clickConsumed;

	@Getter
	private final HotkeyListener hotkeyListener;

	@Inject
	BankInputListener(BanklessBankConfig config, BankViewController controller)
	{
		this.config = config;
		this.controller = controller;
		this.hotkeyListener = new HotkeyListener(this.config::toggleKeybind)
		{
			@Override
			public void hotkeyPressed()
			{
				BankInputListener.this.controller.toggle();
			}
		};
	}

	/** Client thread, from {@link BankOverlay#render}. */
	public void publish(boolean open, Rectangle bounds, boolean altHeld, boolean menuOpen)
	{
		this.open = open;
		this.bounds = bounds == null ? EMPTY : bounds;
		this.altHeld = altHeld;
		this.menuOpen = menuOpen;
	}

	/** Client thread, from {@link HudButtonOverlay#render}. */
	public void publishHud(boolean visible, Rectangle bounds)
	{
		this.hudVisible = visible;
		this.hudBounds = bounds == null ? EMPTY : bounds;
	}

	/**
	 * Client thread. Whether the bank window is open this frame, as most recently published by
	 * {@link BankOverlay#render}. {@link HudButtonOverlay} reads this to decide whether it would be
	 * drawn on top of the bank window (see the draw-order note in its {@code render}), since
	 * OverlayManager's draw order cannot be fixed with priority alone.
	 */
	public boolean isBankOpen()
	{
		return open;
	}

	/** Client thread. The bank window's current on-screen bounds, as most recently published by
	 * {@link BankOverlay#render}; empty when the bank is closed. */
	public Rectangle getBankBounds()
	{
		return bounds;
	}

	private boolean inside(MouseEvent e)
	{
		return open && !altHeld && bounds.contains(e.getPoint());
	}

	private boolean overHud(MouseEvent e)
	{
		return hudVisible && !altHeld && hudBounds.contains(e.getPoint());
	}

	private int localX(MouseEvent e)
	{
		return e.getX() - bounds.x;
	}

	private int localY(MouseEvent e)
	{
		return e.getY() - bounds.y;
	}

	private MouseEvent consume(MouseEvent e)
	{
		e.consume();
		return e;
	}

	private void trackMouse(MouseEvent e)
	{
		lastMouse = new Point(e.getX(), e.getY());
	}

	/** Drops every in-flight drag; the caller decides what happens to the consumed-press flags. */
	private void clearDragState()
	{
		titleDrag = false;
		thumbDrag = false;
		hThumbDrag = false;
		slotDragArmed = false;
		slotDragActive = false;
		tabDragArmed = false;
		tabDragActive = false;
		tabPressStripIndex = -1;
		resizeDrag = false;
		pressPoint = null;
		titleDragOffset = null;
		resizeGrabOffset = null;
	}

	// ---- mouse -----------------------------------------------------------------------------

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		trackMouse(e);
		return inside(e) ? consume(e) : e;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		trackMouse(e);
		pressConsumed = false;

		if (!inside(e))
		{
			if (overHud(e))
			{
				controller.toggle();
				pressConsumed = true;
				return consume(e);
			}

			// A click outside an open context menu dismisses it and is eaten, as every menu does.
			// Any other outside click belongs to the game.
			if (menuOpen && !altHeld)
			{
				controller.post(() -> controller.getViewModel().closeMenu());
				pressConsumed = true;
				return consume(e);
			}

			return e;
		}

		if (SwingUtilities.isRightMouseButton(e))
		{
			final int lx = localX(e);
			final int ly = localY(e);
			controller.post(() -> controller.getViewModel().openMenu(lx, ly));
			pressConsumed = true;
			return consume(e);
		}

		if (!SwingUtilities.isLeftMouseButton(e))
		{
			pressConsumed = true;
			return consume(e);
		}

		pressConsumed = true;

		final int lx = localX(e);
		final int ly = localY(e);
		clearDragState();
		pressPoint = new Point(lx, ly);
		titleDragOffset = new Point(lx, ly);
		resizeGrabOffset = new Point(bounds.x + bounds.width - e.getX(), bounds.y + bounds.height - e.getY());

		controller.post(() ->
		{
			final BankViewModel model = controller.getViewModel();

			if (model.isMenuOpen())
			{
				if (model.activateMenu(lx, ly))
				{
					controller.saveLayoutIfChanged();
				}
				// Card 27: activateMenu() already owns the menu's lifecycle end-to-end - it closes
				// itself in every ordinary case, and deliberately leaves a new one open for the
				// COPY_TO_TAB_MENU two-step flow. An unconditional closeMenu() here used to stomp on
				// that reopened step-2 menu the instant it appeared, so it never stayed open.
				if (model.consumeCloseRequest())
				{
					controller.setOpen(false);
				}
				int renameTab = model.consumeRenameTabRequest();
				if (renameTab >= 0)
				{
					// Opens RuneLite's own chatbox text input, so the keys it needs are ours to leave
					// alone from here on - controller.chatboxInputOpen makes that happen.
					controller.openTabRename(renameTab);
				}
				return;
			}

			final Hit hit = model.hitTest(lx, ly);
			switch (hit.getType())
			{
				case CLOSE:
					controller.setOpen(false);
					break;
				case TAB:
					model.setActiveTab(hit.getIndex() == 0 ? -1 : hit.getIndex() - 1);
					controller.saveViewState();
					tabDragArmed = true;
					tabPressStripIndex = hit.getIndex();
					break;
				case SEARCH:
					// Text entry belongs to RuneLite's chatbox text input now (card 32): the box we
					// draw is a click target and a read-out of the active filter, nothing more.
					controller.openSearch();
					break;
				case SEARCH_BUTTON:
					// Card 31: the icon toggles - it clears an active filter, and only opens the
					// prompt when there is nothing to clear. The pure tier decides which.
					if (model.clickSearchButton())
					{
						controller.openSearch();
					}
					else
					{
						// Cleared the filter; the prompt, if it is still up, goes with it.
						controller.closeSearchPrompt();
					}
					break;
				case MODE_BUTTON:
					model.toggleMode();
					controller.saveViewState();
					break;
				case ADD_BUTTON:
					// Focus was cleared above, so the keys the chatbox item search needs are ours to
					// leave alone from here on.
					controller.openItemSearch();
					break;
				case SCROLL_UP:
					model.scrollBy(-BankGeometry.SCROLL_STEP);
					break;
				case SCROLL_DOWN:
					model.scrollBy(BankGeometry.SCROLL_STEP);
					break;
				case SCROLL_TRACK:
					model.scrollBy(ly < model.scrollThumbRect().y
						? -model.getViewportHeight() : model.getViewportHeight());
					break;
				case SCROLL_THUMB:
					thumbDrag = true;
					break;
				case HSCROLL_LEFT:
					model.hScrollBy(-BankGeometry.SCROLL_STEP);
					break;
				case HSCROLL_RIGHT:
					model.hScrollBy(BankGeometry.SCROLL_STEP);
					break;
				case HSCROLL_TRACK:
					model.hScrollBy(lx < model.hScrollThumbRect().x
						? -model.getViewportWidth() : model.getViewportWidth());
					break;
				case HSCROLL_THUMB:
					hThumbDrag = true;
					break;
				case TITLE_BAR:
					titleDrag = true;
					break;
				case SLOT:
					slotDragArmed = true;
					break;
				case RESIZE_GRIP:
					resizeDrag = true;
					break;
				default:
					break;
			}
		});

		return consume(e);
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		trackMouse(e);

		if (!open)
		{
			return e;
		}

		if (titleDrag && titleDragOffset != null)
		{
			final int x = e.getX() - titleDragOffset.x;
			final int y = e.getY() - titleDragOffset.y;
			controller.setPosition(x, y);
			return consume(e);
		}

		if (resizeDrag && resizeGrabOffset != null)
		{
			// Both axes off one grip: the pointer's distance from the window's top-left, converted to
			// whole columns and rows. The view model clamps each to its own legal range.
			final int w = e.getX() + resizeGrabOffset.x - bounds.x;
			final int h = e.getY() + resizeGrabOffset.y - bounds.y;
			final int cols = BankGeometry.colsForWidth(w);
			controller.post(() ->
			{
				controller.getViewModel().setVisibleCols(cols);
				// Rows are converted on the client thread, not here: the chrome the pixel height has
				// to pay for includes the tab strip, whose row count follows the tab count and the
				// column count we just applied.
				controller.getViewModel().setVisibleRows(controller.getViewModel().rowsForHeight(h));
			});
			return consume(e);
		}

		final int lx = localX(e);
		final int ly = localY(e);

		// pressPoint is AWT-only state, cleared the moment the button comes up. Every drag branch
		// pairs its client-thread-armed flag with one of these, so a flag armed by a posted runnable
		// that ran after the release cannot make a later, unrelated drag ours.
		if (thumbDrag && pressPoint != null)
		{
			controller.post(() -> controller.getViewModel().scrollThumbTo(ly));
			return consume(e);
		}

		if (hThumbDrag && pressPoint != null)
		{
			controller.post(() -> controller.getViewModel().hScrollThumbTo(lx));
			return consume(e);
		}

		if (slotDragArmed && pressPoint != null)
		{
			if (!slotDragActive)
			{
				if (Math.abs(lx - pressPoint.x) < DRAG_SLOP && Math.abs(ly - pressPoint.y) < DRAG_SLOP)
				{
					return consume(e);
				}

				slotDragActive = true;
				final int px = pressPoint.x;
				final int py = pressPoint.y;
				controller.post(() -> controller.getViewModel().beginDrag(px, py));
			}

			controller.post(() -> controller.getViewModel().updateDrag(lx, ly));
			return consume(e);
		}

		if (tabDragArmed && pressPoint != null)
		{
			if (!tabDragActive)
			{
				if (Math.abs(lx - pressPoint.x) < DRAG_SLOP && Math.abs(ly - pressPoint.y) < DRAG_SLOP)
				{
					return consume(e);
				}

				tabDragActive = true;
				final int stripIndex = tabPressStripIndex;
				controller.post(() -> controller.getViewModel().beginTabDrag(stripIndex));
			}

			controller.post(() -> controller.getViewModel().updateTabDrag(lx, ly));
			return consume(e);
		}

		return pressConsumed ? consume(e) : e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		trackMouse(e);

		final boolean wasDragging = titleDrag || thumbDrag || hThumbDrag || slotDragActive
			|| tabDragActive || resizeDrag;
		final boolean consumed = pressConsumed || (open && (inside(e) || wasDragging));

		if (titleDrag)
		{
			controller.savePosition();
		}
		else if (resizeDrag)
		{
			// saveViewState() reads visibleCols / visibleRows / mode / activeTab straight off the view
			// model, which
			// is client-thread confined, so it goes through the queue like every other mutation.
			controller.post(controller::saveViewState);
		}
		else if (slotDragActive)
		{
			final int lx = localX(e);
			final int ly = localY(e);
			controller.post(() ->
			{
				final DropTarget target = controller.getViewModel().endDrag(lx, ly);
				if (target != null && target.getType() != DropTarget.Type.CANCEL)
				{
					controller.saveLayoutIfChanged();
				}
			});
		}
		else if (tabDragActive)
		{
			final int lx = localX(e);
			final int ly = localY(e);
			controller.post(() ->
			{
				final DropTarget target = controller.getViewModel().endTabDrag(lx, ly);
				if (target != null && target.getType() != DropTarget.Type.CANCEL)
				{
					controller.saveLayoutIfChanged();
				}
			});
		}

		clearDragState();
		clickConsumed = consumed;
		pressConsumed = false;

		return consumed ? consume(e) : e;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		final boolean consume = clickConsumed || inside(e);
		clickConsumed = false;
		return consume ? consume(e) : e;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent e)
	{
		lastMouse = null;
		return e;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
	{
		if (!open || altHeld || !bounds.contains(e.getPoint()))
		{
			return e;
		}

		final int delta = e.getWheelRotation() * BankGeometry.SCROLL_STEP;
		// Shift + wheel scrolls sideways, the convention everywhere else a grid is wider than its
		// window. Without shift the wheel always scrolls vertically, as before.
		final boolean horizontal = e.isShiftDown();
		controller.post(() -> {
			final BankViewModel model = controller.getViewModel();
			if (horizontal)
			{
				model.hScrollBy(delta);
			}
			else
			{
				model.scrollBy(delta);
			}
		});
		e.consume();
		return e;
	}

	// ---- keyboard --------------------------------------------------------------------------

	@Override
	public void keyTyped(KeyEvent e)
	{
		// Nothing: search text is typed into RuneLite's chatbox text input (card 32), never into a
		// field of ours, so no printable character is ever ours to take. Kept because KeyListener
		// demands it.
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		// Our key listener registers before the chatbox panel's, so while the game's item search is
		// open every key - Escape above all, which closes that search - has to be left to it. The
		// window stays open behind it either way.
		if (!controller.isOpen() || controller.isChatboxInputOpen())
		{
			return;
		}

		switch (e.getKeyCode())
		{
			case KeyEvent.VK_ESCAPE:
				// Escape always belongs to us while the view is open: it closes the topmost menu,
				// otherwise the window (board decision: Escape closes the window whenever it is
				// open). It never reaches here while the search prompt is up - that Escape is the
				// chatbox input's own, left to it by the isChatboxInputOpen() bail-out above. An
				// active filter is cleared with the search icon (card 31), not with Escape.
				controller.post(() ->
				{
					final BankViewModel model = controller.getViewModel();
					if (model.isMenuOpen())
					{
						model.closeMenu();
					}
					else
					{
						controller.setOpen(false);
					}
				});
				e.consume();
				break;
			default:
				break;
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		// nothing
	}

	@Override
	public void focusLost()
	{
		clearDragState();
		pressConsumed = false;
		clickConsumed = false;

		controller.post(() ->
		{
			final BankViewModel model = controller.getViewModel();
			model.cancelDrag();
			model.cancelTabDrag();
			model.closeMenu();
			model.setSearchFocused(false);
		});
	}
}

package io.robrichardson.banklessbank.ui;

import io.robrichardson.banklessbank.BanklessBankConfig;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.QuantityFormatter;

/**
 * Draws the bank view. Self-positioned: a {@code DYNAMIC} overlay with no preferred location is
 * drawn at whatever {@link #getBounds()} says, so writing the bounds location each frame from the
 * controller is all the positioning we need. Not movable, so RuneLite's alt-drag ignores it and
 * the title bar is the only drag handle.
 *
 * <p>The chrome is drawn from the game's own interface sprites through {@link SpriteManager}: the
 * steel window frame, the close button, the bank tab buttons and their infinity / plus icons, the
 * scrollbar arrows and dragger, and the bank's search icon. {@code SpriteManager.getSprite} returns
 * null before the cache is up (and always in the headless render harness, which has no game), so
 * every sprite has a flat-colour fallback painted from the palette sampled off a real bank
 * screenshot. Sprites are cached here as well as in {@code SpriteManager}, and only ever fetched
 * from {@link #render}, which RuneLite calls on the client thread.
 */
@Singleton
public class BankOverlay extends Overlay
{
	// Palette sampled from a screenshot of the real bank interface.
	private static final Color PANEL = new Color(0x49, 0x40, 0x34);
	private static final Color PANEL_DARK = new Color(0x3A, 0x33, 0x29);
	private static final Color FRAME = new Color(0x2B, 0x2A, 0x26);
	private static final Color FRAME_LIGHT = new Color(0x54, 0x52, 0x49);
	private static final Color FRAME_DARK = new Color(0x0E, 0x0E, 0x0C);
	private static final Color RIVET = new Color(0x6B, 0x69, 0x5E);
	private static final Color TITLE = JagexColors.DARK_ORANGE_INTERFACE_TEXT;
	private static final Color COUNT = JagexColors.YELLOW_INTERFACE_TEXT;
	private static final Color TEXT_DIM = new Color(0xC8, 0xC8, 0xC8);
	private static final Color HOVER = new Color(255, 255, 255, 30);
	private static final Color STONE = new Color(0x54, 0x53, 0x4B);
	private static final Color STONE_LIGHT = new Color(0x74, 0x72, 0x67);
	private static final Color STONE_DARK = new Color(0x2A, 0x2A, 0x26);
	private static final Color STONE_PRESSED = new Color(0x3E, 0x3D, 0x37);
	private static final Color ICON = new Color(0xC8, 0xC2, 0xB0);
	private static final Color SCROLL_TRACK = new Color(0x25, 0x20, 0x19);
	private static final Color SCROLL_THUMB = new Color(0x6E, 0x6B, 0x5F);
	// The game's own "Choose Option" menu, matched exactly: a tan frame whose colour is reused for
	// the header text, a black body, a grey hover bar, white options and orange targets. RuneLite
	// only publishes the last of these (JagexColors.MENU_TARGET) - the client draws the rest
	// natively, so the others are transcribed from it.
	private static final Color MENU_FRAME = new Color(0x5D, 0x54, 0x47);
	private static final Color MENU_BG = Color.BLACK;
	private static final Color MENU_HILIGHT = new Color(0x80, 0x80, 0x80);
	private static final Color MENU_TEXT = Color.WHITE;
	private static final Color MENU_SHADOW = Color.BLACK;
	private static final Color CARET = new Color(0xFF, 0xFF, 0x00);
	private static final Color DROP_TAB = new Color(0xFF, 0xFF, 0x00, 90);
	private static final Color TAB_REORDER_MARKER = Color.WHITE;

	private static final Rectangle EMPTY = new Rectangle();

	/** Spacing of the decorative rivets along the top and bottom of the frame. */
	private static final int RIVET_PITCH = 14;

	// Self-drawn tooltip geometry, mirroring RuneLite's own tooltip placement (see the class doc on
	// drawTooltip for why we no longer route through TooltipManager).
	private static final int TOOLTIP_CURSOR_DX = 10;
	private static final int TOOLTIP_CURSOR_DY = 18;
	private static final int TOOLTIP_PAD_X = 4;
	private static final int TOOLTIP_PAD_Y = 3;
	private static final int TOOLTIP_LINE_GAP = 2;
	private static final Color TOOLTIP_BG = new Color(0x00, 0x00, 0x00, 0xC0);
	private static final Color TOOLTIP_BORDER = new Color(0x5F, 0x54, 0x3F);

	private final Client client;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;
	private final BanklessBankConfig config;
	private final BankViewController controller;
	private final BankInputListener listener;

	/** Client-thread only. Sprite id -> image, populated the first frame the cache can serve it. */
	private final Map<Integer, BufferedImage> spriteCache = new HashMap<>();

	@Inject
	BankOverlay(Client client, ItemManager itemManager, SpriteManager spriteManager,
		BanklessBankConfig config, BankViewController controller, BankInputListener listener)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
		this.config = config;
		this.controller = controller;
		this.listener = listener;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGHEST);
		setMovable(false);
		setSnappable(false);
		setResizable(false);
		setResettable(false);
		setDragTargetable(false);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		controller.drainActions();

		// Config-to-model sync must happen before refresh(), which may run syncLayout() (and persist
		// the result) even while the view is closed. Both setters no-op when the value is unchanged,
		// so this is cheap to do every frame regardless of open state.
		final BankViewModel model = controller.getViewModel();
		model.setPlaceholdersEnabled(config.placeholders());
		model.setShowEmptyStorages(config.showEmptyStorages());

		controller.refresh();

		if (!controller.isOpen())
		{
			listener.publish(false, EMPTY, false, false);
			return null;
		}

		model.rebuild();

		// OverlayRenderer translated the graphics to getBounds()'s location before calling us, using
		// the value from the previous frame. Correct the translation so the window is drawn where the
		// controller says it is this frame, not one frame late. The renderer restores the transform
		// after render() returns.
		final Point origin = controller.getPosition();
		final Point drawnAt = getBounds().getLocation();
		graphics.translate(origin.x - drawnAt.x, origin.y - drawnAt.y);
		getBounds().setLocation(origin);

		final Dimension size = model.size();
		final Point mouse = listener.getLastMouse();
		final Point local = mouse == null ? null : new Point(mouse.x - origin.x, mouse.y - origin.y);

		drawPanel(graphics, size);
		drawGrid(graphics, model, local);
		if (model.isVScrollbarVisible())
		{
			drawScrollbar(graphics, model, local);
		}
		if (model.isHScrollbarVisible())
		{
			drawHScrollbar(graphics, model, local);
		}
		drawTabs(graphics, model, local);
		drawBottomBar(graphics, model, local);
		drawFrame(graphics, size);
		drawResizeGrip(graphics, model, local);
		drawTitle(graphics, model, local);
		drawDrag(graphics, model, local);
		drawMenu(graphics, model, local);
		drawTooltip(graphics, model, local);

		listener.publish(true, new Rectangle(origin.x, origin.y, size.width, size.height),
			client.isKeyPressed(KeyCode.KC_ALT), model.isMenuOpen());
		controller.publishSearchFocused(model.isSearchFocused());

		return size;
	}

	// ---- sprites ---------------------------------------------------------------------------

	/**
	 * The interface sprite, or null while the cache cannot serve it. Client thread only:
	 * {@code SpriteManager.getSprite} asserts as much, and returns null before the login screen.
	 */
	private BufferedImage sprite(int spriteId)
	{
		final BufferedImage cached = spriteCache.get(spriteId);
		if (cached != null)
		{
			return cached;
		}

		BufferedImage loaded = null;
		try
		{
			loaded = spriteManager.getSprite(spriteId, 0);
		}
		catch (RuntimeException ignored)
		{
			// The cache can be mid-load, or the id can be missing on an old revision. Fall back.
		}

		if (loaded != null)
		{
			spriteCache.put(spriteId, loaded);
		}
		return loaded;
	}

	/** Draws {@code image} at its natural size, centred in {@code r}. */
	private static void drawCentred(Graphics2D graphics, BufferedImage image, Rectangle r)
	{
		graphics.drawImage(image, r.x + (r.width - image.getWidth()) / 2,
			r.y + (r.height - image.getHeight()) / 2, null);
	}

	/** Draws {@code image} scaled down to fit inside {@code r}, never scaled up. */
	private static void drawFitted(Graphics2D graphics, BufferedImage image, Rectangle r)
	{
		final int w = image.getWidth();
		final int h = image.getHeight();
		if (w <= r.width && h <= r.height)
		{
			drawCentred(graphics, image, r);
			return;
		}

		final double scale = Math.min(r.width / (double) w, r.height / (double) h);
		final int dw = Math.max(1, (int) Math.round(w * scale));
		final int dh = Math.max(1, (int) Math.round(h * scale));
		graphics.drawImage(image, r.x + (r.width - dw) / 2, r.y + (r.height - dh) / 2, dw, dh, null);
	}

	/** Repeats {@code image} left to right across {@code width}, clipped to it. */
	private void tileHorizontally(Graphics2D graphics, BufferedImage image, int x, int y, int width,
		boolean flipVertically)
	{
		final Shape oldClip = graphics.getClip();
		graphics.clipRect(x, y, width, image.getHeight());
		for (int dx = 0; dx < width; dx += image.getWidth())
		{
			if (flipVertically)
			{
				graphics.drawImage(image, x + dx, y, x + dx + image.getWidth(), y + image.getHeight(),
					0, image.getHeight(), image.getWidth(), 0, null);
			}
			else
			{
				graphics.drawImage(image, x + dx, y, null);
			}
		}
		graphics.setClip(oldClip);
	}

	/** Repeats {@code image} top to bottom down {@code height}, clipped to it. */
	private void tileVertically(Graphics2D graphics, BufferedImage image, int x, int y, int height,
		boolean flipHorizontally)
	{
		final Shape oldClip = graphics.getClip();
		graphics.clipRect(x, y, image.getWidth(), height);
		for (int dy = 0; dy < height; dy += image.getHeight())
		{
			if (flipHorizontally)
			{
				graphics.drawImage(image, x, y + dy, x + image.getWidth(), y + dy + image.getHeight(),
					image.getWidth(), 0, 0, image.getHeight(), null);
			}
			else
			{
				graphics.drawImage(image, x, y + dy, null);
			}
		}
		graphics.setClip(oldClip);
	}

	// ---- chrome ----------------------------------------------------------------------------

	/** The flat interior. Everything else is drawn on top of it. */
	private void drawPanel(Graphics2D graphics, Dimension size)
	{
		graphics.setColor(PANEL);
		graphics.fillRect(0, 0, size.width, size.height);
	}

	/**
	 * The steel window frame, 9-sliced from the game's border sprites: four corners at their
	 * natural size, the top edge tiled across (and flipped for the bottom), the right edge tiled
	 * down (and flipped for the left).
	 */
	private void drawFrame(Graphics2D graphics, Dimension size)
	{
		final BufferedImage topLeft = sprite(SpriteID.Steelborder.TOP_LEFT);
		final BufferedImage topRight = sprite(SpriteID.Steelborder.TOP_RIGHT);
		final BufferedImage bottomLeft = sprite(SpriteID.Steelborder.BOTTOM_LEFT);
		final BufferedImage bottomRight = sprite(SpriteID.Steelborder.BOTTOM_RIGHT);
		final BufferedImage edgeTop = sprite(SpriteID.Steelborder2.EDGE_TOP);
		final BufferedImage edgeRight = sprite(SpriteID.Steelborder2.EDGE_RIGHT);

		if (topLeft == null || topRight == null || bottomLeft == null || bottomRight == null
			|| edgeTop == null || edgeRight == null)
		{
			drawFrameFallback(graphics, size);
			return;
		}

		final int w = size.width;
		final int h = size.height;

		final int innerX = topLeft.getWidth();
		final int innerW = Math.max(0, w - topLeft.getWidth() - topRight.getWidth());
		tileHorizontally(graphics, edgeTop, innerX, 0, innerW, false);
		tileHorizontally(graphics, edgeTop, innerX, h - edgeTop.getHeight(), innerW, true);

		final int innerY = topLeft.getHeight();
		final int innerH = Math.max(0, h - topLeft.getHeight() - bottomLeft.getHeight());
		tileVertically(graphics, edgeRight, w - edgeRight.getWidth(), innerY, innerH, false);
		tileVertically(graphics, edgeRight, 0, innerY, innerH, true);

		graphics.drawImage(topLeft, 0, 0, null);
		graphics.drawImage(topRight, w - topRight.getWidth(), 0, null);
		graphics.drawImage(bottomLeft, 0, h - bottomLeft.getHeight(), null);
		graphics.drawImage(bottomRight, w - bottomRight.getWidth(), h - bottomRight.getHeight(), null);
	}

	/** Flat stand-in for the steel frame: dark bands, a bevel, and a row of rivets top and bottom. */
	private void drawFrameFallback(Graphics2D graphics, Dimension size)
	{
		final int w = size.width;
		final int h = size.height;
		final int b = BankGeometry.BORDER;

		graphics.setColor(FRAME);
		graphics.fillRect(0, 0, w, b);
		graphics.fillRect(0, h - b, w, b);
		graphics.fillRect(0, 0, b, h);
		graphics.fillRect(w - b, 0, b, h);

		// Dark outside, light lip on the inside, which is how the steel frame reads against the panel.
		graphics.setColor(FRAME_DARK);
		graphics.drawRect(0, 0, w - 1, h - 1);
		graphics.setColor(FRAME_LIGHT);
		graphics.drawLine(1, 1, w - 2, 1);
		graphics.drawLine(1, 1, 1, h - 2);
		graphics.setColor(RIVET);
		graphics.drawRect(b - 1, b - 1, w - b * 2 + 1, h - b * 2 + 1);
		graphics.setColor(FRAME_DARK);
		graphics.drawRect(b - 2, b - 2, w - b * 2 + 3, h - b * 2 + 3);

		// The frame's segment joints, then a rivet in the middle of each segment.
		graphics.setColor(FRAME_DARK);
		for (int x = RIVET_PITCH; x < w; x += RIVET_PITCH)
		{
			graphics.drawLine(x, 2, x, b - 3);
			graphics.drawLine(x, h - b + 2, x, h - 3);
		}
		for (int y = RIVET_PITCH; y < h; y += RIVET_PITCH)
		{
			graphics.drawLine(2, y, b - 3, y);
			graphics.drawLine(w - b + 2, y, w - 3, y);
		}

		for (int x = RIVET_PITCH / 2; x < w; x += RIVET_PITCH)
		{
			rivet(graphics, x, 2);
			rivet(graphics, x, h - 5);
		}
		for (int y = RIVET_PITCH / 2; y < h; y += RIVET_PITCH)
		{
			rivet(graphics, 2, y);
			rivet(graphics, w - 5, y);
		}
	}

	/** One 3x3 stud: a light face with a dark shadow down its right and bottom. */
	private static void rivet(Graphics2D graphics, int x, int y)
	{
		graphics.setColor(RIVET);
		graphics.fillRect(x, y, 2, 2);
		graphics.setColor(FRAME_DARK);
		graphics.drawLine(x + 2, y, x + 2, y + 2);
		graphics.drawLine(x, y + 2, x + 2, y + 2);
	}

	/**
	 * Self-drawn bottom-right resize grip: three diagonal hatch lines, the same shape a resizable
	 * desktop window uses. Drawn on top of the frame corner. Resizes both axes, in whole columns
	 * and whole rows.
	 */
	private void drawResizeGrip(Graphics2D graphics, BankViewModel model, Point local)
	{
		final Rectangle r = model.resizeGripRect();
		final boolean hovered = local != null && r.contains(local.x, local.y);

		for (int d : new int[]{3, 7, 11})
		{
			final int x1 = r.x + r.width - 2;
			final int y1 = r.y + r.height - 2 - d;
			final int x2 = r.x + r.width - 2 - d;
			final int y2 = r.y + r.height - 2;

			graphics.setColor(FRAME_DARK);
			graphics.drawLine(x1 + 1, y1 + 1, x2 + 1, y2 + 1);

			graphics.setColor(hovered ? new Color(255, 255, 255, 140) : RIVET);
			graphics.drawLine(x1, y1, x2, y2);
		}
	}

	/** A raised stone button, the shape the bank's bottom-bar buttons use. */
	private void drawStoneButton(Graphics2D graphics, Rectangle r, boolean pressed, boolean hovered)
	{
		graphics.setColor(pressed ? STONE_PRESSED : (hovered ? STONE_LIGHT : STONE));
		graphics.fillRect(r.x, r.y, r.width, r.height);

		graphics.setColor(pressed ? STONE_DARK : STONE_LIGHT);
		graphics.drawLine(r.x, r.y, r.x + r.width - 2, r.y);
		graphics.drawLine(r.x, r.y, r.x, r.y + r.height - 2);

		graphics.setColor(pressed ? STONE_LIGHT : STONE_DARK);
		graphics.drawLine(r.x + r.width - 1, r.y + 1, r.x + r.width - 1, r.y + r.height - 1);
		graphics.drawLine(r.x + 1, r.y + r.height - 1, r.x + r.width - 1, r.y + r.height - 1);

		graphics.setColor(FRAME_DARK);
		graphics.drawRect(r.x - 1, r.y - 1, r.width + 1, r.height + 1);
	}

	private void drawTitle(Graphics2D graphics, BankViewModel model, Point local)
	{
		final Rectangle title = model.titleBarRect();

		graphics.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = graphics.getFontMetrics();
		final String name = titleText(model);
		graphics.setColor(TITLE);
		graphics.drawString(name, title.x + (title.width - fm.stringWidth(name)) / 2,
			baseline(fm, title.y, title.height));

		// The real bank puts "used / capacity" stacked top-left. A viewer has no capacity, so line 1
		// is a plain count of owned items across every tab; line 2, dim, is the placeholder total,
		// shown only when non-zero so a fully-owned layout keeps the single-line look.
		graphics.setFont(FontManager.getRunescapeSmallFont());
		final FontMetrics small = graphics.getFontMetrics();
		final int totalText = model.getTotalItemCount();
		final int placeholderTotal = model.getTotalPlaceholderCount();

		if (placeholderTotal > 0)
		{
			final int lineH = small.getHeight();
			final int top = title.y + (title.height - lineH * 2) / 2 + small.getAscent();
			graphics.setColor(COUNT);
			graphics.drawString(String.valueOf(totalText), title.x + 3, top);
			graphics.setColor(TEXT_DIM);
			graphics.drawString(String.valueOf(placeholderTotal), title.x + 3, top + lineH);
		}
		else
		{
			graphics.setColor(COUNT);
			graphics.drawString(String.valueOf(totalText), title.x + 3, baseline(small, title.y, title.height));
		}

		drawCloseButton(graphics, model, local);

		// A bevelled seam between the title and the tab strip, as the bank has.
		graphics.setColor(FRAME_DARK);
		graphics.drawLine(title.x, title.y + title.height - 1, title.x + title.width - 1,
			title.y + title.height - 1);
		graphics.setColor(FRAME_LIGHT);
		graphics.drawLine(title.x, title.y + title.height, title.x + title.width - 1,
			title.y + title.height);
	}

	/**
	 * The title bar's centred text: the tab name (or "Bankless Bank" for the All tab / by-storage
	 * view), with the GE value of what it shows appended in parentheses, shortened the way
	 * {@code BankPlugin.createValueText} shortens the real bank's - "Tab 7 (905K)". Omitted when the
	 * value is zero or the config item is off.
	 */
	private String titleText(BankViewModel model)
	{
		final String base = model.titleBaseName();

		if (!config.showValue())
		{
			return base;
		}

		final long value = model.titleValue();
		return value == 0 ? base : base + " (" + QuantityFormatter.quantityToStackSize(value) + ")";
	}

	private void drawCloseButton(Graphics2D graphics, BankViewModel model, Point local)
	{
		final Rectangle close = model.closeButtonRect();
		final boolean hovered = local != null && close.contains(local.x, local.y);

		final BufferedImage image = sprite(hovered
			? SpriteID.SteelborderCloseButton._1 : SpriteID.SteelborderCloseButton._0);
		if (image != null)
		{
			drawFitted(graphics, image, close);
			return;
		}

		drawStoneButton(graphics, close, false, hovered);
		graphics.setColor(hovered ? Color.WHITE : new Color(0xE0, 0xD8, 0xC8));
		final Stroke old = graphics.getStroke();
		graphics.setStroke(new BasicStroke(2f));
		graphics.drawLine(close.x + 7, close.y + 7, close.x + close.width - 8, close.y + close.height - 8);
		graphics.drawLine(close.x + close.width - 8, close.y + 7, close.x + 7, close.y + close.height - 8);
		graphics.setStroke(old);
	}

	// ---- tabs ------------------------------------------------------------------------------

	private void drawTabs(Graphics2D graphics, BankViewModel model, Point local)
	{
		final int strip = model.getStripLength();
		final int tabCount = model.getTabCount();
		final int active = model.getActiveTab();
		final int dropTab = dropTabIndex(model, local);

		for (int i = 0; i < strip; i++)
		{
			final Rectangle r = model.tabRect(i);
			final boolean isActive = (i == 0 && active == -1) || (i > 0 && i - 1 == active);
			final boolean hovered = local != null && r.contains(local.x, local.y);

			drawTabBackground(graphics, r, isActive, hovered);

			if (i == 0)
			{
				drawAllTabIcon(graphics, r);
			}
			else if (i - 1 < tabCount)
			{
				final int iconId = model.getTabIconItemId(i - 1);
				if (iconId > 0)
				{
					// Unscaled at its natural 36x32 whenever the tab is its full BankGeometry.TAB_W
					// wide; drawFitted only scales when a narrow window has shrunk the strip's buttons
					// below the sprite, which is the one case an icon would otherwise bleed into its
					// neighbour.
					final BufferedImage icon = itemManager.getImage(iconId, 1, false);
					if (icon != null)
					{
						drawFitted(graphics, icon, r);
					}
				}
				else
				{
					drawCentredText(graphics, FontManager.getRunescapeSmallFont(),
						String.valueOf(i), r, TEXT_DIM);
				}
			}
			else
			{
				drawPlusTabIcon(graphics, r);
			}

			if (i == dropTab)
			{
				graphics.setColor(DROP_TAB);
				graphics.fillRect(r.x, r.y, r.width, r.height);
			}
		}

		if (model.isTabDragging() && model.getTabDropIndex() >= 0)
		{
			final Rectangle marker = model.tabRect(model.getTabDropIndex() + 1);
			graphics.setColor(TAB_REORDER_MARKER);
			graphics.fillRect(marker.x, marker.y, 2, marker.height);
		}
	}

	private void drawTabBackground(Graphics2D graphics, Rectangle r, boolean active, boolean hovered)
	{
		final int spriteId = active ? SpriteID.Banktabs.SELECTED
			: (hovered ? SpriteID.Banktabs.HOVERED : SpriteID.Banktabs.TAB);
		final BufferedImage image = sprite(spriteId);
		if (image != null)
		{
			graphics.drawImage(image, r.x, r.y, r.width, r.height, null);
			return;
		}

		// A rounded stone rim round a recessed face, as the bank's tab buttons have. The selected
		// tab is the lit one; the rest sit back in the panel colour.
		graphics.setColor(active ? STONE : (hovered ? STONE_PRESSED : PANEL));
		graphics.fillRoundRect(r.x + 1, r.y + 1, r.width - 2, r.height - 2, 8, 8);
		graphics.setColor(active ? STONE_LIGHT : STONE);
		graphics.drawRoundRect(r.x + 1, r.y + 1, r.width - 3, r.height - 3, 8, 8);
		graphics.setColor(STONE_DARK);
		graphics.drawRoundRect(r.x, r.y, r.width - 1, r.height - 1, 8, 8);
	}

	/** The [All] tab's infinity mark. The RuneScape fonts have no U+221E, so the fallback is drawn. */
	private void drawAllTabIcon(Graphics2D graphics, Rectangle r)
	{
		final BufferedImage image = sprite(SpriteID.BanktabIcons.ALL_ITEMS);
		if (image != null)
		{
			drawFitted(graphics, image, r);
			return;
		}

		final int d = 10;
		final int cy = r.y + (r.height - d) / 2;
		final Stroke old = graphics.getStroke();
		graphics.setStroke(new BasicStroke(2f));
		graphics.setColor(ICON);
		graphics.drawOval(r.x + r.width / 2 - d + 1, cy, d, d);
		graphics.drawOval(r.x + r.width / 2 - 1, cy, d, d);
		graphics.setStroke(old);
	}

	/** The [+] tab. */
	private void drawPlusTabIcon(Graphics2D graphics, Rectangle r)
	{
		final BufferedImage image = sprite(SpriteID.BanktabIcons.ADD);
		if (image != null)
		{
			drawFitted(graphics, image, r);
			return;
		}

		final int cx = r.x + r.width / 2;
		final int cy = r.y + r.height / 2;
		graphics.setColor(ICON);
		graphics.fillRect(cx - 1, cy - 7, 3, 15);
		graphics.fillRect(cx - 7, cy - 1, 15, 3);
	}

	/** The strip index the current drag would drop onto, or -1. */
	private int dropTabIndex(BankViewModel model, Point local)
	{
		if (local == null)
		{
			return -1;
		}
		return model.dropTabStripIndex(local.x, local.y);
	}

	// ---- grid ------------------------------------------------------------------------------

	private void drawGrid(Graphics2D graphics, BankViewModel model, Point local)
	{
		final Rectangle grid = model.gridRect();
		final Shape oldClip = graphics.getClip();
		graphics.clip(grid);

		// The bank draws no cell borders and no separate grid background: items sit straight on the
		// panel. Only the hover highlight marks a cell out.
		graphics.setFont(FontManager.getRunescapeSmallFont());

		final List<BankRow> rows = model.getRows();
		final List<BankSlot> slots = model.getSlots();
		final int scroll = model.getScroll();

		int flat = 0;
		for (BankRow row : rows)
		{
			final int y = grid.y + row.getY() - scroll;
			if (y + row.getHeight() < grid.y || y > grid.y + grid.height)
			{
				if (row.getKind() == BankRow.Kind.ITEMS)
				{
					flat += row.getSlots().size();
				}
				continue;
			}

			if (row.getKind() == BankRow.Kind.HEADER)
			{
				drawHeader(graphics, row, grid, y);
				continue;
			}

			for (int i = 0; i < row.getSlots().size(); i++)
			{
				drawSlot(graphics, model, slots.get(flat + i), flat + i, local);
			}
			flat += row.getSlots().size();
		}

		graphics.setClip(oldClip);
	}

	private void drawHeader(Graphics2D graphics, BankRow row, Rectangle grid, int y)
	{
		final FontMetrics fm = graphics.getFontMetrics();
		final int baseline = baseline(fm, y, row.getHeight()) - 1;

		graphics.setColor(PANEL_DARK);
		graphics.fillRect(grid.x, y, grid.width, row.getHeight());

		// An All-view tab divider carries an icon and reserves a left margin for it; a BY_STORAGE
		// header (headerIconItemId -1) starts its text flush left, as before.
		final boolean hasIcon = row.getHeaderIconItemId() > 0;
		final int textX = grid.x + (hasIcon ? BankGeometry.DIVIDER_ICON_W : 3);

		if (hasIcon)
		{
			final BufferedImage icon = itemManager.getImage(row.getHeaderIconItemId(), 1, false);
			if (icon != null)
			{
				drawFitted(graphics, icon,
					new Rectangle(grid.x + 2, y + 2, BankGeometry.DIVIDER_ICON_W - 4, row.getHeight() - 4));
			}
		}

		final String name = row.getHeaderText() == null ? "" : row.getHeaderText();
		graphics.setColor(TITLE);
		graphics.drawString(name, textX, baseline);

		final String subtitle = row.getHeaderSubtitle();
		int labelEndX = textX + fm.stringWidth(name);
		if (subtitle != null && !subtitle.isEmpty())
		{
			graphics.setColor(TEXT_DIM);
			graphics.drawString(subtitle, labelEndX + 6, baseline);
			labelEndX += 6 + fm.stringWidth(subtitle);
		}

		// The divider's separator line, echoing the real bank's engraved group boundary.
		if (hasIcon)
		{
			graphics.setColor(FRAME_DARK);
			final int lineY = y + row.getHeight() / 2;
			graphics.drawLine(labelEndX + 6, lineY, grid.x + grid.width - 4, lineY);
		}
	}

	private void drawSlot(Graphics2D graphics, BankViewModel model, BankSlot slot, int flatIndex, Point local)
	{
		final Rectangle r = model.slotRect(flatIndex);
		if (r.width <= 0)
		{
			return;
		}

		if (local != null && r.contains(local.x, local.y))
		{
			graphics.setColor(HOVER);
			graphics.fillRect(r.x, r.y, r.width, r.height);
		}

		if (slot.isEmpty())
		{
			return;
		}

		// Card 27: compare the dragged cell's (tabIndex, indexInTab), not its id - with duplication,
		// comparing by id would dim every copy of the dragged item instead of just the one being
		// dragged. indexInTab != -1 keeps a beyond-width blank cell from ever matching.
		final BankSlot dragged = model.getDragSlot();
		if (model.isDragging() && dragged != null
			&& dragged.getTabIndex() == slot.getTabIndex()
			&& dragged.getIndexInTab() == slot.getIndexInTab()
			&& slot.getIndexInTab() != -1)
		{
			return;
		}

		final int x = r.x + BankGeometry.ITEM_DX;
		final int y = r.y + BankGeometry.ITEM_DY;

		if (slot.isPlaceholder())
		{
			drawSprite(graphics, slot.getCanonicalId(), 1, false, x, y, 0.35f);
		}
		else
		{
			final int qty = (int) Math.max(1, Math.min(slot.getQuantity(), Integer.MAX_VALUE));
			drawSprite(graphics, slot.getCanonicalId(), qty, qty > 1, x, y, 1f);
		}
	}

	/**
	 * {@code withCount} is passed as {@code ItemManager}'s {@code stackable} flag, which is what
	 * decides whether the quantity text is drawn at all: we want bank-style counts on everything
	 * with more than one, and no "1" on singles, regardless of whether the item really stacks.
	 */
	private void drawSprite(Graphics2D graphics, int itemId, int quantity, boolean withCount,
		int x, int y, float alpha)
	{
		final BufferedImage image = itemManager.getImage(itemId, quantity, withCount);
		if (image == null)
		{
			return;
		}

		if (alpha >= 1f)
		{
			graphics.drawImage(image, x, y, null);
			return;
		}

		final Composite old = graphics.getComposite();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		graphics.drawImage(image, x, y, null);
		graphics.setComposite(old);
	}

	// ---- scrollbar -------------------------------------------------------------------------

	/**
	 * The grid's vertical scrollbar column. Unlike the geometry's rect, which is a fixed part of the
	 * grid layout, drawing it is conditional: the caller only invokes this while
	 * {@link BankViewModel#isVScrollbarVisible()}, i.e. the active tab/mode/search has content taller
	 * than the viewport. Grid slot rects never move when it is hidden - the column simply goes
	 * unpainted, so a short tab's right edge is clean instead of showing an empty track.
	 */
	private void drawScrollbar(Graphics2D graphics, BankViewModel model, Point local)
	{
		final Rectangle track = model.scrollTrackRect();

		final BufferedImage trackSprite = sprite(SpriteID.ScrollbarDraggerV2.TRACK);
		if (trackSprite != null)
		{
			tileVertically(graphics, trackSprite, track.x, track.y, track.height, false);
		}
		else
		{
			graphics.setColor(SCROLL_TRACK);
			graphics.fillRect(track.x, track.y, track.width, track.height);
			graphics.setColor(FRAME_DARK);
			graphics.drawRect(track.x, track.y, track.width - 1, track.height - 1);
		}

		drawScrollArrow(graphics, model.scrollUpRect(), true, local);
		drawScrollArrow(graphics, model.scrollDownRect(), false, local);

		drawScrollThumb(graphics, model.scrollThumbRect());
	}

	/**
	 * The grid's horizontal scrollbar. Unlike the vertical bar, which always occupies its own column,
	 * this one is not reserved space: the caller only invokes this while
	 * {@link BankViewModel#isHScrollbarVisible()}, i.e. the active tab is laid out wider than the
	 * viewport, and it draws overlaying the bottom 16px of the grid area (the last grid row is
	 * partially covered, which is fine).
	 */
	private void drawHScrollbar(Graphics2D graphics, BankViewModel model, Point local)
	{
		final Rectangle track = model.hScrollTrackRect();

		graphics.setColor(SCROLL_TRACK);
		graphics.fillRect(track.x, track.y, track.width, track.height);
		graphics.setColor(FRAME_DARK);
		graphics.drawRect(track.x, track.y, Math.max(0, track.width - 1), track.height - 1);

		drawHScrollArrow(graphics, model.hScrollLeftRect(), true, local);
		drawHScrollArrow(graphics, model.hScrollRightRect(), false, local);

		final Rectangle thumb = model.hScrollThumbRect();
		graphics.setColor(SCROLL_THUMB);
		graphics.fillRect(thumb.x, thumb.y, thumb.width, thumb.height);
		graphics.setColor(STONE_LIGHT);
		graphics.drawLine(thumb.x, thumb.y, thumb.x + thumb.width - 2, thumb.y);
		graphics.drawLine(thumb.x, thumb.y, thumb.x, thumb.y + thumb.height - 2);
		graphics.setColor(FRAME_DARK);
		graphics.drawLine(thumb.x + thumb.width - 1, thumb.y, thumb.x + thumb.width - 1,
			thumb.y + thumb.height - 1);
		graphics.drawLine(thumb.x, thumb.y + thumb.height - 1, thumb.x + thumb.width - 1,
			thumb.y + thumb.height - 1);
	}

	private void drawHScrollArrow(Graphics2D graphics, Rectangle r, boolean left, Point local)
	{
		final BufferedImage image = sprite(left
			? SpriteID.ScrollbarV2.ARROW_LEFT : SpriteID.ScrollbarV2.ARROW_RIGHT);
		if (image != null)
		{
			drawFitted(graphics, image, r);
			return;
		}

		final boolean hovered = local != null && r.contains(local.x, local.y);
		drawStoneButton(graphics, r, false, hovered);

		final int cy = r.y + r.height / 2;
		final int near = r.x + 5;
		final int far = r.x + r.width - 5;
		final int[] ys = {cy - 4, cy + 4, cy};
		final int[] xs = left ? new int[]{far, far, near} : new int[]{near, near, far};
		graphics.setColor(new Color(0x1E, 0x1B, 0x14));
		graphics.fillPolygon(xs, ys, 3);
	}

	private void drawScrollArrow(Graphics2D graphics, Rectangle r, boolean up, Point local)
	{
		final BufferedImage image = sprite(up
			? SpriteID.ScrollbarV2.ARROW_UP : SpriteID.ScrollbarV2.ARROW_DOWN);
		if (image != null)
		{
			drawFitted(graphics, image, r);
			return;
		}

		final boolean hovered = local != null && r.contains(local.x, local.y);
		drawStoneButton(graphics, r, false, hovered);

		final int cx = r.x + r.width / 2;
		final int top = r.y + 5;
		final int bottom = r.y + r.height - 5;
		final int[] xs = {cx - 4, cx + 4, cx};
		final int[] ys = up ? new int[]{bottom, bottom, top} : new int[]{top, top, bottom};
		graphics.setColor(new Color(0x1E, 0x1B, 0x14));
		graphics.fillPolygon(xs, ys, 3);
	}

	private void drawScrollThumb(Graphics2D graphics, Rectangle thumb)
	{
		final BufferedImage top = sprite(SpriteID.ScrollbarDraggerV2.TOP);
		final BufferedImage middle = sprite(SpriteID.ScrollbarDraggerV2.MIDDLE);
		final BufferedImage bottom = sprite(SpriteID.ScrollbarDraggerV2.BOTTOM);

		if (top != null && middle != null && bottom != null)
		{
			final int middleH = Math.max(0, thumb.height - top.getHeight() - bottom.getHeight());
			graphics.drawImage(top, thumb.x, thumb.y, null);
			tileVertically(graphics, middle, thumb.x, thumb.y + top.getHeight(), middleH, false);
			graphics.drawImage(bottom, thumb.x, thumb.y + thumb.height - bottom.getHeight(), null);
			return;
		}

		graphics.setColor(SCROLL_THUMB);
		graphics.fillRect(thumb.x, thumb.y, thumb.width, thumb.height);
		graphics.setColor(STONE_LIGHT);
		graphics.drawLine(thumb.x, thumb.y, thumb.x + thumb.width - 2, thumb.y);
		graphics.drawLine(thumb.x, thumb.y, thumb.x, thumb.y + thumb.height - 2);
		graphics.setColor(FRAME_DARK);
		graphics.drawLine(thumb.x + thumb.width - 1, thumb.y, thumb.x + thumb.width - 1,
			thumb.y + thumb.height - 1);
		graphics.drawLine(thumb.x, thumb.y + thumb.height - 1, thumb.x + thumb.width - 1,
			thumb.y + thumb.height - 1);
	}

	// ---- bottom bar ------------------------------------------------------------------------

	/**
	 * The bank's bottom button row, minus everything a viewer cannot do. Withdraw quantity, noted
	 * mode and insert/swap all describe withdrawals we never make, so the bar carries only the two
	 * controls that mean something here: search, and the tabs / by-storage view toggle.
	 */
	private void drawBottomBar(Graphics2D graphics, BankViewModel model, Point local)
	{
		final Rectangle bar = model.bottomBarRect();
		graphics.setColor(PANEL_DARK);
		graphics.fillRect(bar.x, bar.y, bar.width, bar.height);
		graphics.setColor(FRAME_DARK);
		graphics.drawLine(bar.x, bar.y, bar.x + bar.width - 1, bar.y);
		graphics.setColor(FRAME_LIGHT);
		graphics.drawLine(bar.x, bar.y + 1, bar.x + bar.width - 1, bar.y + 1);

		drawSearchButton(graphics, model, local);
		drawSearchField(graphics, model);
		drawAddButton(graphics, model, local);
		drawModeButton(graphics, model, local);
	}

	private void drawSearchButton(Graphics2D graphics, BankViewModel model, Point local)
	{
		final Rectangle r = model.searchButtonRect();
		final boolean hovered = local != null && r.contains(local.x, local.y);
		final boolean active = model.isSearchFocused() || !model.getSearch().isEmpty();

		final BufferedImage image = sprite(SpriteID.Bankbuttons.SEARCH);
		if (image != null)
		{
			drawStoneButton(graphics, r, active, hovered);
			drawFitted(graphics, image, r);
			return;
		}

		drawStoneButton(graphics, r, active, hovered);
		graphics.setColor(new Color(0xD8, 0xD8, 0xD0));
		final Stroke old = graphics.getStroke();
		graphics.setStroke(new BasicStroke(2f));
		graphics.drawOval(r.x + 5, r.y + 4, 11, 11);
		graphics.drawLine(r.x + 15, r.y + 14, r.x + 19, r.y + 18);
		graphics.setStroke(old);
	}

	private void drawSearchField(Graphics2D graphics, BankViewModel model)
	{
		final Rectangle r = model.searchRect();
		if (r.width <= 0)
		{
			return;
		}

		graphics.setFont(FontManager.getRunescapeSmallFont());
		final FontMetrics fm = graphics.getFontMetrics();
		final int baseline = baseline(fm, r.y, r.height);

		final String search = model.getSearch();
		if (search.isEmpty() && !model.isSearchFocused())
		{
			graphics.setColor(TEXT_DIM);
			graphics.drawString("Search...", r.x + 3, baseline);
			return;
		}

		graphics.setColor(TITLE);
		graphics.drawString(search, r.x + 3, baseline);

		if (model.isSearchFocused())
		{
			final int caretX = r.x + 4 + fm.stringWidth(search);
			graphics.setColor(CARET);
			graphics.drawLine(caretX, r.y + 4, caretX, r.y + r.height - 5);
		}
	}

	/**
	 * The "add an item" button: opens the game's own chatbox item search, whose pick is appended to
	 * the tab on show as a placeholder. Wears the bank's [+] tab glyph, the closest thing the cache
	 * has to an "add" icon.
	 */
	private void drawAddButton(Graphics2D graphics, BankViewModel model, Point local)
	{
		final Rectangle r = model.addButtonRect();
		final boolean hovered = local != null && r.contains(local.x, local.y);

		drawStoneButton(graphics, r, controller.isChatboxInputOpen(), hovered);
		drawPlusTabIcon(graphics, r);
	}

	private void drawModeButton(Graphics2D graphics, BankViewModel model, Point local)
	{
		final Rectangle r = model.modeButtonRect();
		final boolean hovered = local != null && r.contains(local.x, local.y);
		final boolean byStorage = model.getMode() == ViewMode.BY_STORAGE;

		drawStoneButton(graphics, r, byStorage, hovered);
		drawCentredText(graphics, FontManager.getRunescapeSmallFont(),
			byStorage ? "Storage" : "Tabs", r, TITLE);
	}

	// ---- drag ------------------------------------------------------------------------------

	private void drawDrag(Graphics2D graphics, BankViewModel model, Point local)
	{
		if (!model.isDragging())
		{
			return;
		}

		final int dropIndex = model.getDropSlotIndex();
		if (dropIndex >= 0)
		{
			final Rectangle r = model.slotRect(dropIndex);
			if (r.width > 0)
			{
				graphics.setColor(new Color(CARET.getRed(), CARET.getGreen(), CARET.getBlue(), 90));
				graphics.fillRect(r.x, r.y, r.width, r.height);
			}
		}

		final BankSlot dragged = model.getDragSlot();
		final Point at = local != null ? local : model.getDragPoint();
		if (dragged == null || at == null)
		{
			return;
		}

		drawSprite(graphics, dragged.getCanonicalId(), 1, false,
			at.x - BankGeometry.ITEM_SPRITE_W / 2, at.y - BankGeometry.ITEM_SPRITE_H / 2, 0.6f);
	}

	// ---- context menu ----------------------------------------------------------------------

	private void drawMenu(Graphics2D graphics, BankViewModel model, Point local)
	{
		if (!model.isMenuOpen())
		{
			return;
		}

		final ContextMenu menu = model.getMenu();
		if (menu == null)
		{
			return;
		}

		final Rectangle r = menu.getBounds();
		// Frame first, then the header band and the body punched out of it in black, exactly as the
		// client lays it out: 1px of frame all round, a 16px black header, and the frame showing
		// through as the 1px rule between header and body.
		graphics.setColor(MENU_FRAME);
		graphics.fillRect(r.x, r.y, r.width, r.height);
		graphics.setColor(MENU_BG);
		graphics.fillRect(r.x + 1, r.y + 1, r.width - 2, BankGeometry.MENU_HEADER_H - 2);
		graphics.fillRect(r.x + 1, r.y + BankGeometry.MENU_HEADER_H,
			r.width - 2, r.height - BankGeometry.MENU_HEADER_H - 1);

		final Font old = graphics.getFont();
		graphics.setFont(FontManager.getRunescapeFont());
		final FontMetrics fm = graphics.getFontMetrics();

		// The header title is drawn in the frame's own colour, as the game does.
		final Rectangle header = menu.headerRect();
		graphics.setColor(MENU_FRAME);
		graphics.drawString(ContextMenu.TITLE, header.x + BankGeometry.MENU_TEXT_X - 1,
			baseline(fm, header.y, header.height));

		final List<ContextMenuEntry> entries = menu.getEntries();
		for (int i = 0; i < entries.size(); i++)
		{
			final Rectangle er = menu.entryRect(i);
			if (er == null || er.width <= 0)
			{
				continue;
			}

			if (local != null && er.contains(local.x, local.y))
			{
				graphics.setColor(MENU_HILIGHT);
				graphics.fillRect(er.x, er.y, er.width, er.height);
			}

			final ContextMenuEntry entry = entries.get(i);
			final int tx = er.x + BankGeometry.MENU_TEXT_X - 1;
			final int by = baseline(fm, er.y, er.height);
			drawShadowed(graphics, entry.getLabel(), tx, by, MENU_TEXT);
			if (entry.hasTarget())
			{
				drawShadowed(graphics, entry.getTarget(),
					tx + fm.stringWidth(entry.getLabel() + " "), by, JagexColors.MENU_TARGET);
			}
		}

		graphics.setFont(old);
	}

	/** One string with the game's 1px black drop shadow under it. */
	private void drawShadowed(Graphics2D graphics, String text, int x, int y, Color colour)
	{
		graphics.setColor(MENU_SHADOW);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(colour);
		graphics.drawString(text, x, y);
	}

	// ---- tooltip ---------------------------------------------------------------------------

	/**
	 * Draws our own tooltip at the tracked cursor position, rather than handing text to RuneLite's
	 * {@code TooltipManager}. That manager anchors at {@code client.getMouseCanvasPosition()}, which
	 * only advances on a mouse-moved event that reaches the injected client - and we consume every
	 * such event while the cursor is inside our bounds (registered ahead of the client's own
	 * handler), so the game's notion of the mouse position freezes the instant the cursor enters the
	 * window. Consuming the move is required (it is what stops the game highlighting scenery under
	 * the window), so the tooltip has to be self-drawn instead. Painted last, over everything else.
	 */
	private void drawTooltip(Graphics2D graphics, BankViewModel model, Point local)
	{
		if (local == null || model.isDragging() || model.isMenuOpen())
		{
			return;
		}

		final List<String> lines = tooltipLinesWithPrice(model, local);
		if (lines.isEmpty())
		{
			return;
		}

		graphics.setFont(FontManager.getRunescapeFont());
		final FontMetrics fm = graphics.getFontMetrics();
		final int lineH = fm.getHeight();

		int maxWidth = 0;
		for (String line : lines)
		{
			maxWidth = Math.max(maxWidth, fm.stringWidth(line));
		}

		final int w = TOOLTIP_PAD_X * 2 + maxWidth;
		final int h = TOOLTIP_PAD_Y * 2 + lines.size() * lineH + (lines.size() - 1) * TOOLTIP_LINE_GAP;

		final Point origin = controller.getPosition();
		final int canvasW = client.getCanvasWidth();
		final int canvasH = client.getCanvasHeight();

		int x = local.x + TOOLTIP_CURSOR_DX;
		x = Math.min(x, canvasW - origin.x - w);
		x = Math.max(x, -origin.x);

		int y = local.y + TOOLTIP_CURSOR_DY;
		final int clampedY = Math.min(y, canvasH - origin.y - h);
		if (y - clampedY > TOOLTIP_CURSOR_DY)
		{
			// The downward clamp would have pushed the tooltip up by more than one cursor offset;
			// flip it above the cursor instead of letting it ride the canvas edge next to the pointer.
			y = local.y - TOOLTIP_CURSOR_DY / 2 - h;
		}
		else
		{
			y = clampedY;
		}
		y = Math.max(y, -origin.y);

		graphics.setColor(TOOLTIP_BG);
		graphics.fillRect(x, y, w, h);
		graphics.setColor(TOOLTIP_BORDER);
		graphics.drawRect(x, y, w - 1, h - 1);

		int lineY = y + TOOLTIP_PAD_Y + fm.getAscent();
		for (int i = 0; i < lines.size(); i++)
		{
			graphics.setColor(i == 0 ? JagexColors.DARK_ORANGE_INTERFACE_TEXT : TEXT_DIM);
			graphics.drawString(lines.get(i), x + TOOLTIP_PAD_X, lineY);
			lineY += lineH + TOOLTIP_LINE_GAP;
		}
	}

	/**
	 * {@link BankViewModel#tooltipLines} stays free of formatting (a pure-tier method cannot reach
	 * {@code QuantityFormatter}), so for a slot this inserts the GE price line - or "Placeholder" -
	 * right after the item name here, where the formatter is available.
	 */
	private List<String> tooltipLinesWithPrice(BankViewModel model, Point local)
	{
		final List<String> base = model.tooltipLines(local.x, local.y);
		if (base.isEmpty())
		{
			return base;
		}

		final BankSlot slot = model.slotAt(local.x, local.y);
		if (slot == null)
		{
			return base;
		}

		final List<String> lines = new ArrayList<>();
		lines.add(base.get(0));

		if (slot.isPlaceholder())
		{
			lines.add("Placeholder");
		}
		else
		{
			final long price = model.unitPrice(slot.getCanonicalId());
			if (price > 0)
			{
				final long qty = slot.getQuantity();
				String geLine = "GE: " + QuantityFormatter.formatNumber(qty * price);
				if (qty > 1)
				{
					geLine += " (" + QuantityFormatter.formatNumber(price) + " ea)";
				}
				lines.add(geLine);
			}
		}

		lines.addAll(base.subList(1, base.size()));
		return lines;
	}

	private void drawCentredText(Graphics2D graphics, Font font, String text, Rectangle r, Color color)
	{
		final Font old = graphics.getFont();
		graphics.setFont(font);
		final FontMetrics fm = graphics.getFontMetrics();
		graphics.setColor(color);
		graphics.drawString(text, r.x + (r.width - fm.stringWidth(text)) / 2,
			baseline(fm, r.y, r.height));
		graphics.setFont(old);
	}

	/** Baseline y that vertically centres a line of this font in a band of {@code height} at {@code y}. */
	private static int baseline(FontMetrics fm, int y, int height)
	{
		return y + (height + fm.getAscent() - fm.getDescent()) / 2;
	}
}

package io.robrichardson.banklessbank.ui;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

/** One row of content: {@code HEADER} (storage name) or {@code ITEMS} (up to 8 {@link BankSlot}s),
 * with its content-space {@code y} and {@code height}. */
@Getter
@EqualsAndHashCode
@ToString
public final class BankRow
{
	public enum Kind
	{
		HEADER, ITEMS
	}

	private final Kind kind;
	private final int y;
	private final int height;
	private final String headerText;
	private final String headerSubtitle;
	private final List<BankSlot> slots;
	/** The tab this row belongs to in TABS mode, or -1 for BY_STORAGE and search rows. */
	private final int tabIndex;
	/** The tab's icon item id for a header row in the All view, or -1. */
	private final int headerIconItemId;

	public BankRow(Kind kind, int y, int height, String headerText, String headerSubtitle, List<BankSlot> slots)
	{
		this(kind, y, height, headerText, headerSubtitle, slots, -1, -1);
	}

	public BankRow(Kind kind, int y, int height, String headerText, String headerSubtitle, List<BankSlot> slots,
		int tabIndex, int headerIconItemId)
	{
		this.kind = kind;
		this.y = y;
		this.height = height;
		this.headerText = headerText;
		this.headerSubtitle = headerSubtitle;
		this.slots = Collections.unmodifiableList(new ArrayList<>(slots));
		this.tabIndex = tabIndex;
		this.headerIconItemId = headerIconItemId;
	}
}

package io.robrichardson.banklessbank.ui;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

/** One drawable cell: canonical id, display name, summed quantity, {@code placeholder} flag,
 * {@code sources}, and its {@code (tabIndex, indexInTab)} origin.
 *
 * <p>A cell drawn past a tab's own layout width has no slot in that tab yet, so it carries
 * {@code indexInTab == -1} and instead records the {@code (gridRow, gridCol)} it is drawn at - see
 * {@link #beyondWidth}. Every other cell leaves those at -1. */
@Getter
@EqualsAndHashCode
@ToString
public final class BankSlot
{
	private final int canonicalId;
	private final String name;
	private final long quantity;
	private final boolean stackable;
	private final boolean placeholder;
	private final List<SlotSource> sources;
	private final int tabIndex;
	private final int indexInTab;
	/** Grid row this cell is drawn at, for a beyond-width cell only; -1 otherwise. */
	private final int gridRow;
	/** Grid column this cell is drawn at, for a beyond-width cell only; -1 otherwise. */
	private final int gridCol;

	public BankSlot(int canonicalId, String name, long quantity, boolean stackable,
		boolean placeholder, List<SlotSource> sources, int tabIndex, int indexInTab)
	{
		this(canonicalId, name, quantity, stackable, placeholder, sources, tabIndex, indexInTab, -1, -1);
	}

	private BankSlot(int canonicalId, String name, long quantity, boolean stackable,
		boolean placeholder, List<SlotSource> sources, int tabIndex, int indexInTab,
		int gridRow, int gridCol)
	{
		this.canonicalId = canonicalId;
		this.name = name;
		this.quantity = quantity;
		this.stackable = stackable;
		this.placeholder = placeholder;
		this.sources = Collections.unmodifiableList(new ArrayList<>(sources));
		this.tabIndex = tabIndex;
		this.indexInTab = indexInTab;
		this.gridRow = gridRow;
		this.gridCol = gridCol;
	}

	/** An unoccupied grid cell: canonicalId -1, no name, no quantity, not a placeholder. */
	public static BankSlot empty(int tabIndex, int indexInTab)
	{
		return new BankSlot(-1, "", 0, false, false, Collections.emptyList(), tabIndex, indexInTab);
	}

	/**
	 * A blank cell drawn to the right of a tab's own layout width, because the window is wider than
	 * the tab is. It holds no slot index - the tab has none for that column - only where it is drawn,
	 * so that a drop onto it can widen the tab to {@code gridCol + 1} and place the item at
	 * {@code (gridRow, gridCol)} in the widened grid.
	 */
	public static BankSlot beyondWidth(int tabIndex, int gridRow, int gridCol)
	{
		return new BankSlot(-1, "", 0, false, false, Collections.emptyList(), tabIndex, -1, gridRow, gridCol);
	}

	/** True for a cell produced by {@link #empty} or {@link #beyondWidth}. */
	public boolean isEmpty()
	{
		return canonicalId <= 0;
	}

	/** True for a cell produced by {@link #beyondWidth}: a column the tab does not yet reach. */
	public boolean isBeyondWidth()
	{
		return gridCol >= 0;
	}
}

package io.robrichardson.banklessbank.ui;

import io.robrichardson.banklessbank.BanklessBankConfig;
import io.robrichardson.banklessbank.BanklessBankPlugin;
import io.robrichardson.banklessbank.model.BankLayout;
import io.robrichardson.banklessbank.model.BankTab;
import io.robrichardson.banklessbank.model.LayoutStore;
import io.robrichardson.banklessbank.tracking.ItemStack;
import io.robrichardson.banklessbank.tracking.StorageManager;
import io.robrichardson.banklessbank.tracking.death.ExpiringDeathStorage;
import java.awt.Dimension;
import java.awt.Point;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentLinkedQueue;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.chatbox.ChatboxItemSearch;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.game.chatbox.ChatboxTextInput;

/**
 * The seam between the pure {@link BankViewModel} and the client. Owns the view model, which is
 * only ever touched on the client thread: everything the AWT input listener wants to do arrives
 * here as a {@link Runnable} and is run at the top of the next frame by {@link BankOverlay}.
 */
@Slf4j
@Singleton
public class BankViewController
{
	static final String KEY_VIEW_X = "viewX";
	static final String KEY_VIEW_Y = "viewY";
	static final String KEY_VIEW_ROWS = "viewRows";
	static final String KEY_VIEW_COLS = "viewCols";
	static final String KEY_VIEW_MODE = "viewMode";
	static final String KEY_VIEW_TAB = "viewTab";

	/** Layout writes are coalesced to at most one every this many milliseconds. */
	private static final long SAVE_INTERVAL_MS = 1000L;

	private final BanklessBankPlugin plugin;
	private final Client client;
	private final ItemManager itemManager;
	private final ConfigManager configManager;
	private final BanklessBankConfig config;
	private final LayoutStore layoutStore;
	private final ChatboxItemSearch itemSearch;
	private final ChatboxTextInput tabRenameInput;
	private final ChatboxTextInput searchInput;
	private final ChatboxPanelManager chatboxPanelManager;

	@Getter
	private final BankViewModel viewModel = new BankViewModel();

	private final ConcurrentLinkedQueue<Runnable> actions = new ConcurrentLinkedQueue<>();

	/** Canonical id to display name, for placeholders whose storages are long gone. */
	private final Map<Integer, String> knownNames = new HashMap<>();

	/** Canonical id to GE unit price, refreshed alongside {@link #knownNames}. */
	private final Map<Integer, Long> unitPrices = new HashMap<>();

	/** Storage instance to owning manager config key. Rebuilt lazily; identity keyed. */
	private final Map<Object, String> categories = new IdentityHashMap<>();

	private volatile boolean open;

	/** Published from the client thread each frame; read by the AWT key/mouse listener. */
	private volatile boolean searchFocused;

	/**
	 * True while either of our two chatbox UIs - the item search or the tab-rename text input - is
	 * up. Read by the AWT key listener, which must leave every key alone while either is open: it
	 * registers ahead of the chatbox panel's own listener and would otherwise swallow the keys they
	 * need (Escape above all).
	 */
	private volatile boolean chatboxInputOpen;

	/** True only while <em>our search prompt</em> is the chatbox panel on show. */
	private volatile boolean searchPromptOpen;

	/** Overlay top-left in canvas coordinates. {@code null} until the first open centres it. */
	private volatile Point position;

	private String loadedProfileKey;
	/** Active tab restored from config, applied to the first profile load then cleared to -1. */
	private int pendingActiveTab = -1;
	private boolean layoutDirty;
	private long lastSaveMs;
	private volatile boolean started;

	@Inject
	BankViewController(BanklessBankPlugin plugin, Client client, ItemManager itemManager,
		ConfigManager configManager, BanklessBankConfig config, LayoutStore layoutStore,
		ChatboxItemSearch itemSearch, ChatboxTextInput tabRenameInput, ChatboxTextInput searchInput,
		ChatboxPanelManager chatboxPanelManager)
	{
		this.plugin = plugin;
		this.client = client;
		this.itemManager = itemManager;
		this.configManager = configManager;
		this.config = config;
		this.layoutStore = layoutStore;
		this.itemSearch = itemSearch;
		this.tabRenameInput = tabRenameInput;
		this.searchInput = searchInput;
		this.chatboxPanelManager = chatboxPanelManager;
	}

	// ---- lifecycle -------------------------------------------------------------------------

	/** Restores the window position and view state that were saved globally (not per profile). */
	public void startUp()
	{
		int x = readInt(KEY_VIEW_X, -1);
		int y = readInt(KEY_VIEW_Y, -1);
		position = (x < 0 || y < 0) ? null : new Point(x, y);

		viewModel.setVisibleRows(readInt(KEY_VIEW_ROWS, BankGeometry.DEFAULT_ROWS));
		viewModel.setVisibleCols(readInt(KEY_VIEW_COLS, BankGeometry.DEFAULT_COLS));

		String mode = configManager.getConfiguration(BanklessBankConfig.CONFIG_GROUP, KEY_VIEW_MODE);
		if (ViewMode.BY_STORAGE.name().equals(mode))
		{
			viewModel.setMode(ViewMode.BY_STORAGE);
		}

		// Held back rather than applied now: the first profile load replaces the layout, and
		// syncProfile() has to reset the active tab for a genuine profile *change*. Applying the
		// saved value there instead is what makes it survive startup.
		pendingActiveTab = readInt(KEY_VIEW_TAB, -1);
		viewModel.setActiveTab(-1);

		open = false;
		started = true;
		actions.clear();
	}

	/** Stops the controller from doing further work. Safe from any thread. */
	public void stop()
	{
		started = false;
		open = false;
		searchFocused = false;
		closeSearchPrompt();
		chatboxInputOpen = false;
		searchPromptOpen = false;
		actions.clear();
	}

	/** Flushes the layout and the window position. Client thread only: touches shared view state. */
	public void flush()
	{
		if (loadedProfileKey != null)
		{
			layoutStore.save(loadedProfileKey, viewModel.getLayout());
			layoutDirty = false;
		}

		savePosition();
		saveViewState();
	}

	// ---- open / closed ---------------------------------------------------------------------

	public boolean isOpen()
	{
		return open;
	}

	/** Safe from any thread. */
	public void setOpen(boolean open)
	{
		if (this.open == open)
		{
			return;
		}

		this.open = open;

		if (!open)
		{
			searchFocused = false;
			closeSearchPrompt();
			post(() ->
			{
				viewModel.cancelDrag();
				viewModel.closeMenu();
				viewModel.setSearchFocused(false);
			});
		}
	}

	public void toggle()
	{
		setOpen(!open);
	}

	/** Client thread, from {@link BankOverlay#render}. Read from the AWT thread by the listener. */
	public void publishSearchFocused(boolean focused)
	{
		this.searchFocused = focused;
	}

	/** Safe from any thread; read by the AWT key/mouse listener to decide whether to consume input. */
	public boolean isSearchFocused()
	{
		return searchFocused;
	}

	// ---- manual item add -------------------------------------------------------------------

	/**
	 * Safe from any thread. True while the game's chatbox item search or the tab-rename text input is
	 * open, which is the AWT key listener's cue to leave every key alone - it registers ahead of the
	 * chatbox panel's own listener and would otherwise swallow the keys either needs.
	 */
	public boolean isChatboxInputOpen()
	{
		return chatboxInputOpen;
	}

	/**
	 * Opens RuneLite's own in-game item search in the chatbox and adds whatever the player picks to
	 * the end of the tab on show. Client thread only ({@code build()} opens a chatbox panel), which
	 * is where the input listener's posted runnable runs it.
	 *
	 * <p>The selection callback can arrive on either thread - the widget listener fires on the client
	 * thread, Enter on a highlighted result fires on AWT - so it is posted through the action queue
	 * like any other mutation rather than touching the view model directly.
	 */
	public void openItemSearch()
	{
		chatboxInputOpen = true;
		itemSearch
			.tooltipText("Add to bank")
			.onItemSelected(id ->
			{
				// Cleared here as well as in onClose: the search is a shared singleton, so another
				// plugin opening it replaces both callbacks, and a click on our button is then the
				// only way back. Re-opening unconditionally is what makes that recovery work.
				chatboxInputOpen = false;
				post(() -> addItem(id));
			})
			.onClose(() -> chatboxInputOpen = false)
			.build();
	}

	/** Client thread. Adds a canonicalised id to the view and persists the layout if it changed. */
	private void addItem(int itemId)
	{
		if (viewModel.addItem(itemManager.canonicalize(itemId)))
		{
			saveLayoutIfChanged();
		}
		saveViewState();
	}

	// ---- search ----------------------------------------------------------------------------

	/**
	 * Opens the search filter as a chatbox text input, the way the real bank does, instead of the
	 * field we used to draw and type into ourselves (card 32).
	 *
	 * <p>This is not cosmetic. RuneLite's Key Remapping plugin ("WASD camera") rewrites W/A/S/D
	 * {@code KeyEvent}s in place and eats the follow-up {@code KEY_TYPED} before any later listener
	 * sees them, and {@code KeyManager} has no priority API for us to get ahead of it. Opening a
	 * chatbox panel strips the chatbox's own key listener, which is exactly the condition that plugin
	 * checks before remapping - so every keyboard plugin stands aside for free.
	 *
	 * <p>{@code onChanged} fires on every edit, so the filter updates live; it is posted through the
	 * action queue like every other mutation, leaving the filtering itself in the pure tier. Enter
	 * ({@code onDone}) closes the panel and leaves the filter applied, as the real bank does; Escape
	 * closes it the same way through {@code onClose}.
	 *
	 * <p>Client thread only ({@code build()} opens a chatbox panel), which is where the input
	 * listener's posted runnable runs it.
	 */
	public void openSearch()
	{
		chatboxInputOpen = true;
		searchPromptOpen = true;
		searchFocused = true;
		viewModel.setSearchFocused(true);
		searchInput
			.prompt("Show items whose names contain the following text:")
			.value(viewModel.getSearch())
			.onChanged((String text) -> post(() -> viewModel.setSearch(text)))
			.onDone((String text) -> post(() ->
			{
				viewModel.setSearch(text);
				viewModel.setSearchFocused(false);
			}))
			.onClose(() ->
			{
				chatboxInputOpen = false;
				searchPromptOpen = false;
				post(() -> viewModel.setSearchFocused(false));
			})
			.build();
	}

	/**
	 * Closes our search prompt if it is the panel on show - on the search icon's clear (card 31) and
	 * whenever the window itself closes. Safe from any thread
	 * ({@code ChatboxPanelManager.close()} hops to the client thread itself), and guarded by
	 * {@link #searchPromptOpen} so we never close another plugin's chatbox panel.
	 */
	public void closeSearchPrompt()
	{
		if (searchPromptOpen)
		{
			searchPromptOpen = false;
			chatboxPanelManager.close();
		}
	}

	// ---- tab rename ------------------------------------------------------------------------

	/**
	 * Opens a chatbox text input pre-filled with the tab's current name, following the same shape as
	 * {@link #openItemSearch()}: the input is a shared, constructor-injected instance, so opening it
	 * unconditionally re-registers our callbacks even if another plugin (or a previous, abandoned
	 * rename) still holds them. Client thread only ({@code build()} opens a chatbox panel), which is
	 * where the input listener's posted runnable runs it, from {@link BankViewModel#consumeRenameTabRequest()}.
	 *
	 * <p>{@code onDone} fires on Enter (client thread's widget dispatch or AWT, same ambiguity as the
	 * item search), so the actual rename is posted through the action queue rather than touching the
	 * view model directly. A no-op for a tab index that no longer exists (e.g. deleted by the time the
	 * player submits, which is not currently reachable but is the safe default).
	 */
	public void openTabRename(int tabIndex)
	{
		BankTab tab = viewModel.getLayout().getTab(tabIndex);
		if (tab == null)
		{
			return;
		}

		chatboxInputOpen = true;
		tabRenameInput
			.prompt("Enter tab name")
			.value(tab.getName())
			.onDone((String newName) -> post(() -> renameTab(tabIndex, newName)))
			.onClose(() -> chatboxInputOpen = false)
			.build();
	}

	/** Client thread. Renames a tab and persists the layout if the name actually changed. */
	private void renameTab(int tabIndex, String newName)
	{
		if (viewModel.renameTab(tabIndex, newName))
		{
			saveLayoutIfChanged();
		}
	}

	// ---- position --------------------------------------------------------------------------

	/**
	 * The overlay's top-left in canvas coordinates. Centres on the canvas the first time, which is
	 * why this must be called on the client thread (it reads the canvas size).
	 */
	public Point getPosition()
	{
		final Dimension size = viewModel.size();
		final int canvasW = Math.max(client.getCanvasWidth(), size.width);
		final int canvasH = Math.max(client.getCanvasHeight(), size.height);

		Point p = position;
		if (p == null)
		{
			p = new Point((canvasW - size.width) / 2, (canvasH - size.height) / 2);
			position = p;
			return p;
		}

		// A restored position can be off-canvas after a resize, or after the row count changed.
		final int x = clamp(p.x, 0, canvasW - size.width);
		final int y = clamp(p.y, 0, canvasH - size.height);
		if (x != p.x || y != p.y)
		{
			p = new Point(x, y);
			position = p;
		}
		return p;
	}

	private static int clamp(int v, int lo, int hi)
	{
		return Math.max(lo, Math.min(hi, v));
	}

	public void setPosition(int x, int y)
	{
		position = new Point(Math.max(0, x), Math.max(0, y));
	}

	/** Persists the current position. Called when a title-bar drag ends, and on shutdown. */
	public void savePosition()
	{
		Point p = position;
		if (p == null)
		{
			return;
		}

		configManager.setConfiguration(BanklessBankConfig.CONFIG_GROUP, KEY_VIEW_X, p.x);
		configManager.setConfiguration(BanklessBankConfig.CONFIG_GROUP, KEY_VIEW_Y, p.y);
	}

	/** Persists the window size (rows and columns), mode and active tab. */
	public void saveViewState()
	{
		configManager.setConfiguration(BanklessBankConfig.CONFIG_GROUP, KEY_VIEW_ROWS, viewModel.getVisibleRows());
		configManager.setConfiguration(BanklessBankConfig.CONFIG_GROUP, KEY_VIEW_COLS, viewModel.getVisibleCols());
		configManager.setConfiguration(BanklessBankConfig.CONFIG_GROUP, KEY_VIEW_MODE, viewModel.getMode().name());
		configManager.setConfiguration(BanklessBankConfig.CONFIG_GROUP, KEY_VIEW_TAB, viewModel.getActiveTab());
	}

	// ---- action queue ----------------------------------------------------------------------

	/** Queues work to run on the client thread at the top of the next frame. Any thread. */
	public void post(Runnable action)
	{
		if (action != null)
		{
			actions.add(action);
		}
	}

	/** Client thread. Runs everything the input listener queued since the last frame. */
	public void drainActions()
	{
		Runnable action;
		while ((action = actions.poll()) != null)
		{
			try
			{
				action.run();
			}
			catch (RuntimeException e)
			{
				log.warn("Bank view action failed", e);
			}
		}
	}

	// ---- refresh ---------------------------------------------------------------------------

	/**
	 * Client thread. Reloads the layout on a profile change, rebuilds the snapshots when the
	 * tracking layer says they are stale, syncs the layout to what is owned and saves when needed.
	 */
	public void refresh()
	{
		if (!started || plugin.getLoadedProfileKey() == null)
		{
			return;
		}

		viewModel.setMaxRows(viewModel.rowsForHeight(client.getCanvasHeight()));
		viewModel.setMaxCols(BankGeometry.colsForWidth(client.getCanvasWidth()));

		boolean profileChanged = syncProfile();
		boolean rebuilt = false;

		if (profileChanged || plugin.isStoragesDirty())
		{
			rebuildSnapshots();
			rebuilt = true;
		}

		if (rebuilt && viewModel.syncLayout())
		{
			viewModel.closeMenu();
			layoutDirty = true;
		}

		if (layoutDirty && loadedProfileKey != null)
		{
			long now = System.currentTimeMillis();
			if (now - lastSaveMs >= SAVE_INTERVAL_MS)
			{
				layoutStore.save(loadedProfileKey, viewModel.getLayout());
				lastSaveMs = now;
				layoutDirty = false;
			}
		}
	}

	/** Marks the layout as needing a write. Called after any menu or drag mutation. */
	public void saveLayoutIfChanged()
	{
		layoutDirty = true;
	}

	/**
	 * Re-reads window position, size, mode and active tab from config and forces the layout to be
	 * reloaded on the next {@link #refresh()}. Used after an import replaces the config underneath
	 * us. Client thread only.
	 */
	public void reloadFromConfig()
	{
		layoutDirty = false;          // must precede the null, or syncProfile() saves the stale layout
		loadedProfileKey = null;      // makes syncProfile() reload on the next refresh()

		int x = readInt(KEY_VIEW_X, -1);
		int y = readInt(KEY_VIEW_Y, -1);
		position = (x < 0 || y < 0) ? null : new Point(x, y);

		viewModel.setVisibleRows(readInt(KEY_VIEW_ROWS, BankGeometry.DEFAULT_ROWS));
		viewModel.setVisibleCols(readInt(KEY_VIEW_COLS, BankGeometry.DEFAULT_COLS));

		String mode = configManager.getConfiguration(BanklessBankConfig.CONFIG_GROUP, KEY_VIEW_MODE);
		viewModel.setMode(ViewMode.BY_STORAGE.name().equals(mode) ? ViewMode.BY_STORAGE : ViewMode.TABS);

		pendingActiveTab = readInt(KEY_VIEW_TAB, -1);
		viewModel.setActiveTab(-1);
		viewModel.setScroll(0);
		viewModel.invalidate();
	}

	private boolean syncProfile()
	{
		String profileKey = plugin.getLoadedProfileKey();
		if (profileKey == null)
		{
			return false;
		}

		if (Objects.equals(profileKey, loadedProfileKey))
		{
			return false;
		}

		if (loadedProfileKey != null && layoutDirty)
		{
			layoutStore.save(loadedProfileKey, viewModel.getLayout());
		}

		loadedProfileKey = profileKey;
		layoutDirty = false;
		lastSaveMs = System.currentTimeMillis();

		BankLayout layout = layoutStore.load(profileKey);
		viewModel.setLayout(layout);
		viewModel.setActiveTab(pendingActiveTab >= 0 && pendingActiveTab < layout.getTabs().size()
			? pendingActiveTab : -1);
		pendingActiveTab = -1;
		viewModel.setScroll(0);
		categories.clear();
		knownNames.clear();
		unitPrices.clear();
		return true;
	}

	private void rebuildSnapshots()
	{
		if (categories.isEmpty())
		{
			cacheCategories();
		}

		List<StorageSnapshot> out = new ArrayList<>();

		plugin.getStorageManagerManager().getViewableStorages().forEach(storage ->
		{
			List<ItemSnapshot> items = new ArrayList<>();

			for (ItemStack stack : storage.getItems())
			{
				if (stack.getId() <= 0 || stack.getQuantity() <= 0)
				{
					continue;
				}

				int canonical = itemManager.canonicalize(stack.getId());
				String name = stack.getName();
				if (name == null || name.isEmpty() || "Loading".equals(name))
				{
					name = nameOf(canonical);
				}
				items.add(new ItemSnapshot(canonical, name, stack.getQuantity(), stack.isStackable()));
				knownNames.put(canonical, name);
				unitPrices.put(canonical, itemManager.getItemPrice(canonical));
			}

			if (items.isEmpty() && !config.showEmptyStorages())
			{
				return;
			}

			String subtitle = storage instanceof ExpiringDeathStorage
				? ((ExpiringDeathStorage) storage).getExpireText()
				: null;

			String category = categories.get(storage);
			out.add(new StorageSnapshot(category == null ? "" : category, storage.getName(), subtitle, items));
		});

		seedPlaceholderNames();

		viewModel.setKnownNames(knownNames);
		viewModel.setUnitPrices(unitPrices);
		viewModel.setSnapshots(out);
		plugin.clearStoragesDirty();
	}

	private void cacheCategories()
	{
		for (StorageManager<?, ?> manager : plugin.getStorageManagerManager().getStorageManagers())
		{
			for (Object storage : manager.getStorages())
			{
				categories.put(storage, manager.getConfigKey());
			}
		}
	}

	/**
	 * Fills in names and GE prices for layout ids we have never seen a storage for (a placeholder,
	 * or a released-then-returned item), so a placeholder-only tab still gets a tooltip price.
	 */
	private void seedPlaceholderNames()
	{
		viewModel.getLayout().getTabs().forEach(tab -> tab.getSlots().forEach(id ->
		{
			if (id == null)
			{
				return;
			}
			if (!knownNames.containsKey(id))
			{
				knownNames.put(id, nameOf(id));
			}
			if (!unitPrices.containsKey(id))
			{
				unitPrices.put(id, itemManager.getItemPrice(id));
			}
		}));
	}

	/** Client thread only. */
	private String nameOf(int canonicalId)
	{
		try
		{
			String name = itemManager.getItemComposition(canonicalId).getName();
			return name == null ? "Item " + canonicalId : name;
		}
		catch (RuntimeException e)
		{
			return "Item " + canonicalId;
		}
	}

	private int readInt(String key, int fallback)
	{
		Integer value = configManager.getConfiguration(
			BanklessBankConfig.CONFIG_GROUP, key, int.class);
		return value == null ? fallback : value;
	}
}

package io.robrichardson.banklessbank.ui;

import io.robrichardson.banklessbank.model.BankLayout;
import io.robrichardson.banklessbank.model.BankTab;
import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * The whole view: owns a {@link BankLayout}, storage snapshots, search text, mode, active tab,
 * scroll, drag state and context menu. Builds rows, hit-tests, and mutates the layout.
 *
 * <p>Client-thread confined at runtime, but has zero platform dependencies so tests drive it
 * directly.
 */
public class BankViewModel
{
	private static final String UNKNOWN_ITEM_PREFIX = "Item ";

	// ---- inputs ----
	private BankLayout layout = new BankLayout();
	private List<StorageSnapshot> snapshots = Collections.emptyList();
	private Map<Integer, String> knownNames = new HashMap<>();
	/** Canonical id -> GE unit price, pushed by the controller from {@code ItemManager}. */
	private Map<Integer, Long> unitPrices = new HashMap<>();
	private boolean placeholdersEnabled = true;
	private boolean showEmptyStorages;
	private int visibleRows = BankGeometry.DEFAULT_ROWS;
	private int visibleCols = BankGeometry.DEFAULT_COLS;
	/** How many rows the canvas can actually hold, published by the controller each frame. */
	private int maxRows = BankGeometry.MAX_ROWS;
	/** How many columns the canvas can actually hold, published by the controller each frame. */
	private int maxCols = BankGeometry.MAX_COLS;
	/** Cached {@code (visibleCols, visibleRows)} geometry; replaced whenever either changes. */
	/**
	 * Cache behind {@link #geom()}; never read directly. The geometry's third dimension, the number of
	 * tab-strip rows, follows the tab count, which changes without going through any setter, so the
	 * cache is validated on every read rather than only when the window is resized.
	 */
	private BankGeometry geom = BankGeometry.defaults();

	// ---- view state ----
	private ViewMode mode = ViewMode.TABS;
	private int activeTab = -1;
	private String search = "";
	/** {@link #search} lower-cased once, so the filter does not re-fold it per item. */
	private String searchLower = "";
	private boolean searchFocused;

	// ---- owned-item data, recomputed whenever snapshots change (independent of dirty rows) ----
	private Set<Integer> ownedIds = new LinkedHashSet<>();
	private Map<Integer, Long> qtyById = new LinkedHashMap<>();
	private Map<Integer, List<SlotSource>> sourcesById = new LinkedHashMap<>();
	private Map<Integer, ItemSnapshot> firstSnapshotById = new LinkedHashMap<>();

	// ---- rebuild output ----
	private boolean dirty = true;
	private List<BankRow> rows = Collections.emptyList();
	private List<BankSlot> slots = Collections.emptyList();
	private int contentHeight;
	/**
	 * Widest row built, in pixels - the grid's virtual width. Never below the viewport, so it is only
	 * wider than the window when some tab's layout is wider than the window.
	 */
	private int contentWidth;

	// ---- scroll ----
	private int scroll;
	/** Scroll remembered per tab, keyed by identity since indices shift under reorder/delete. */
	private final Map<BankTab, Integer> scrollByTab = new IdentityHashMap<>();
	private int allTabScroll;

	// ---- horizontal scroll: only reaches past zero when a tab is laid out wider than the window ----
	private int hScroll;
	private final Map<BankTab, Integer> hScrollByTab = new IdentityHashMap<>();
	private int allTabHScroll;

	// ---- drag ----
	private boolean dragging;
	private BankSlot dragSlot;
	private Point dragPoint;
	/** Flat index of the grid cell under the cursor while dragging, or -1. */
	private int dropSlotIndex = -1;

	// ---- tab drag ----
	private boolean tabDragging;
	private int tabDragFrom = -1;
	private int tabDropIndex = -1;

	// ---- context menu ----
	private boolean menuOpen;
	private ContextMenu menu;
	/** Anchor point the open menu was built at, so a step-2 menu can reopen at the same point. */
	private Point menuAnchor;

	/** Raised by the title-bar menu's "Close" entry; the controller consumes it. */
	private boolean closeRequested;

	/**
	 * The tab index the "Rename tab" entry was activated on, or -1. Renaming needs a chatbox text
	 * input, which is RuneLite-tier, so the pure view model only raises the request; the controller
	 * consumes it and opens the input, then posts the actual {@link #renameTab(int, String)} back.
	 */
	private int renameTabRequest = -1;

	// =========================================================================================
	// Inputs
	// =========================================================================================

	public void setSnapshots(List<StorageSnapshot> snapshots)
	{
		this.snapshots = new ArrayList<>(snapshots);
		recomputeOwnedData();
		invalidate();
	}

	public void setLayout(BankLayout layout)
	{
		this.layout = layout != null ? layout : new BankLayout();
		scrollByTab.clear();
		allTabScroll = 0;
		hScrollByTab.clear();
		allTabHScroll = 0;
		hScroll = 0;
		invalidate();
	}

	public BankLayout getLayout()
	{
		return layout;
	}

	public void setPlaceholdersEnabled(boolean enabled)
	{
		if (this.placeholdersEnabled == enabled)
		{
			return;
		}

		this.placeholdersEnabled = enabled;
		invalidate();
	}

	public boolean isPlaceholdersEnabled()
	{
		return placeholdersEnabled;
	}

	public void setShowEmptyStorages(boolean enabled)
	{
		if (this.showEmptyStorages == enabled)
		{
			return;
		}

		this.showEmptyStorages = enabled;
		invalidate();
	}

	public boolean isShowEmptyStorages()
	{
		return showEmptyStorages;
	}

	/** Clamps to {@code [MIN_ROWS, maxRows]}; {@code maxRows} is set by the controller each frame. */
	public void setVisibleRows(int rows)
	{
		this.visibleRows = clamp(rows, BankGeometry.MIN_ROWS, maxRows);
		// The active tab renders trailing rows down to the viewport height, so the row count is an
		// input to the grid, not just a window size.
		invalidate();
		this.scroll = clamp(scroll, 0, getMaxScroll());
	}

	public int getVisibleRows()
	{
		return visibleRows;
	}

	/**
	 * Clamps to {@code [MIN_COLS, maxCols]}. This is the viewport width only: no tab's layout width
	 * changes and nothing is written to the layout, so an item never moves when the window is
	 * resized. What does change is what the viewport shows - a wider window adds blank columns to the
	 * right of a narrower tab, a narrower one starts scrolling horizontally - so the rows are rebuilt
	 * and both scroll offsets re-clamped.
	 */
	public void setVisibleCols(int cols)
	{
		int c = clamp(cols, BankGeometry.MIN_COLS, maxCols);
		if (c == visibleCols)
		{
			return;
		}

		visibleCols = c;
		invalidate();
		rebuild();
		this.scroll = clamp(scroll, 0, getMaxScroll());
		this.hScroll = clamp(hScroll, 0, getMaxHScroll());
		recordScroll();
		recordHScroll();
	}

	public int getVisibleCols()
	{
		return visibleCols;
	}

	/** How many rows the canvas can actually hold. Set each frame by the controller. */
	public void setMaxRows(int rows)
	{
		int m = clamp(rows, BankGeometry.MIN_ROWS, BankGeometry.MAX_ROWS);
		if (m != maxRows)
		{
			maxRows = m;
			setVisibleRows(visibleRows);
		}
	}

	public int getMaxRows()
	{
		return maxRows;
	}

	/** How many columns the canvas can actually hold. Set each frame by the controller. */
	public void setMaxCols(int cols)
	{
		int m = clamp(cols, BankGeometry.MIN_COLS, BankGeometry.MAX_COLS);
		if (m != maxCols)
		{
			maxCols = m;
			setVisibleCols(visibleCols);
		}
	}

	public int getMaxCols()
	{
		return maxCols;
	}

	/**
	 * The current {@code (cols, rows, stripRows)} geometry. Every rect the view exposes comes from
	 * here. Recomputed only when one of the three actually changes, so a frame that drains the action
	 * queue before it reads any rect still sees exactly one geometry.
	 */
	public BankGeometry geometry()
	{
		return geom();
	}

	private BankGeometry geom()
	{
		final int stripRows = BankGeometry.stripRowsFor(visibleCols, getStripLength());
		if (geom.getCols() != visibleCols || geom.getRows() != visibleRows
			|| geom.getStripRows() != stripRows)
		{
			geom = BankGeometry.of(visibleCols, visibleRows, stripRows);
		}
		return geom;
	}

	/**
	 * Grid rows a window of this pixel height would hold, at the strip height the current tab count
	 * needs. The AWT-side resize drag works in pixels and posts them here, since the strip row count
	 * is client-thread state.
	 */
	public int rowsForHeight(int pixelHeight)
	{
		return BankGeometry.rowsForHeight(pixelHeight, geom().getStripRows());
	}

	/** Canonical id -> display name, used for placeholders whose id is not in any snapshot. */
	public void setKnownNames(Map<Integer, String> names)
	{
		this.knownNames = new HashMap<>(names);
		invalidate();
	}

	/** Canonical id -> GE unit price. Rebuilt whenever snapshots rebuild; does not force a redraw. */
	public void setUnitPrices(Map<Integer, Long> prices)
	{
		this.unitPrices = new HashMap<>(prices);
	}

	/** GE unit price for a canonical id, or 0 when unknown. */
	public long unitPrice(int canonicalId)
	{
		return unitPrices.getOrDefault(canonicalId, 0L);
	}

	// =========================================================================================
	// View state
	// =========================================================================================

	public ViewMode getMode()
	{
		return mode;
	}

	public void setMode(ViewMode mode)
	{
		this.mode = mode;
		this.scroll = 0;
		invalidate();
	}

	/** Flips between the tab view and the by-storage view. Bound to the bottom bar's mode button. */
	public void toggleMode()
	{
		setMode(mode == ViewMode.TABS ? ViewMode.BY_STORAGE : ViewMode.TABS);
	}

	public int getActiveTab()
	{
		return activeTab;
	}

	public void setActiveTab(int tabIndex)
	{
		if (tabIndex == activeTab)
		{
			invalidate();
			return;
		}

		activeTab = tabIndex;
		invalidate();
		scroll = rememberedScrollForActiveTab();
		hScroll = rememberedHScrollForActiveTab();
	}

	private int rememberedScrollForActiveTab()
	{
		if (!search.isEmpty())
		{
			return 0;
		}
		return activeTab < 0 ? allTabScroll : scrollByTab.getOrDefault(layout.getTab(activeTab), 0);
	}

	private int rememberedHScrollForActiveTab()
	{
		if (!search.isEmpty())
		{
			return 0;
		}
		return activeTab < 0 ? allTabHScroll : hScrollByTab.getOrDefault(layout.getTab(activeTab), 0);
	}

	/** The {@link BankTab} instance currently active, or null when no tab is active. */
	private BankTab activeTabRef()
	{
		return activeTab >= 0 ? layout.getTab(activeTab) : null;
	}

	/**
	 * Re-resolves {@link #activeTab} to wherever {@code ref} now lives after a layout mutation
	 * (tabs can be deleted or pruned, shifting indices). Matches by identity, not equality, since
	 * {@link BankTab} is a data class and distinct tabs can otherwise compare equal.
	 */
	private void syncActiveTab(BankTab ref)
	{
		if (ref == null)
		{
			if (activeTab >= layout.getTabs().size())
			{
				activeTab = -1;
			}
			return;
		}

		for (int i = 0; i < layout.getTabs().size(); i++)
		{
			if (layout.getTab(i) == ref)
			{
				activeTab = i;
				return;
			}
		}
		activeTab = -1;
	}

	public String getSearch()
	{
		return search;
	}

	public void setSearch(String text)
	{
		boolean wasEmpty = search.isEmpty();
		this.search = text == null ? "" : text;
		this.searchLower = this.search.toLowerCase(Locale.ROOT);
		invalidate();

		if (wasEmpty && !search.isEmpty())
		{
			scroll = 0;
			hScroll = 0;
		}
		else if (!wasEmpty && search.isEmpty())
		{
			scroll = rememberedScrollForActiveTab();
			hScroll = rememberedHScrollForActiveTab();
		}
		else if (!search.isEmpty())
		{
			scroll = 0;
			hScroll = 0;
		}
	}

	public boolean isSearchFocused()
	{
		return searchFocused;
	}

	public void setSearchFocused(boolean focused)
	{
		this.searchFocused = focused;
	}

	// =========================================================================================
	// Rebuild
	// =========================================================================================

	public void invalidate()
	{
		dirty = true;
	}

	public boolean isDirty()
	{
		return dirty;
	}

	/** Recomputes owned ids, rows and content height. Idempotent; no-op when not dirty. */
	public void rebuild()
	{
		if (!dirty)
		{
			return;
		}

		List<BankRow> newRows = new ArrayList<>();
		List<BankSlot> newSlots = new ArrayList<>();
		int y = 0;

		if (mode == ViewMode.TABS)
		{
			if (!search.isEmpty())
			{
				y = buildSearchRows(newRows, newSlots, y);
			}
			else if (activeTab >= 0 && layout.getTab(activeTab) != null)
			{
				y = buildTabGrid(newRows, newSlots, activeTab, layout.getTab(activeTab), true, y);
			}
			else
			{
				// A divider labels every non-empty tab's group in the All view, except when there is
				// only one tab: a single unlabelled grid reads better than a lone divider.
				final boolean emitDividers = layout.getTabs().size() > 1;
				for (int t = 0; t < layout.getTabs().size(); t++)
				{
					BankTab tab = layout.getTab(t);
					if (tab.itemCount() == 0)
					{
						continue;
					}

					if (emitDividers)
					{
						newRows.add(new BankRow(BankRow.Kind.HEADER, y, BankGeometry.HEADER_H, tab.getName(),
							null, Collections.emptyList(), t, tab.getIconItemId()));
						y += BankGeometry.HEADER_H;
					}
					y = buildTabGrid(newRows, newSlots, t, tab, false, y);
				}
			}
		}
		else
		{
			final Set<Integer> tabFilter = storageModeTabFilter();
			for (StorageSnapshot snap : snapshots)
			{
				final boolean emptyStorage = snap.getItems().isEmpty();
				if (emptyStorage && !showEmptyStorages)
				{
					continue;
				}

				List<BankSlot> built = new ArrayList<>();
				for (ItemSnapshot item : snap.getItems())
				{
					if (item.getQuantity() <= 0 || !matchesSearch(item.getName()))
					{
						continue;
					}
					if (tabFilter != null && !tabFilter.contains(item.getCanonicalId()))
					{
						continue;
					}
					List<SlotSource> src = Collections.singletonList(new SlotSource(snap.getName(), item.getQuantity()));
					built.add(new BankSlot(item.getCanonicalId(), item.getName(), item.getQuantity(),
						item.isStackable(), false, src, -1, -1));
				}

				// An empty storage still gets a header when the player asked to see empty storages and
				// is not filtering; anything else with no matching items is skipped entirely. A tab
				// filter never keeps an empty-after-filter storage: "no items of mine in here" is not
				// the same thing as "this storage itself is empty".
				final boolean keepAsEmptyStorage =
					emptyStorage && showEmptyStorages && search.isEmpty() && tabFilter == null;
				if (built.isEmpty() && !keepAsEmptyStorage)
				{
					continue;
				}

				newRows.add(new BankRow(BankRow.Kind.HEADER, y, BankGeometry.HEADER_H, snap.getName(),
					snap.getSubtitle(), Collections.emptyList()));
				y += BankGeometry.HEADER_H;
				y = appendItemRows(newRows, newSlots, built, y);
			}
		}

		rows = Collections.unmodifiableList(newRows);
		slots = Collections.unmodifiableList(newSlots);
		contentHeight = y;

		// The virtual width is the widest row built - a tab laid out wider than the window, in the
		// All view the widest of them - and never less than the viewport, so a window wider than
		// every tab simply has nothing to scroll.
		int widest = visibleCols;
		for (BankRow row : newRows)
		{
			if (row.getKind() == BankRow.Kind.ITEMS)
			{
				widest = Math.max(widest, row.getSlots().size());
			}
		}
		contentWidth = widest * BankGeometry.SLOT_W;

		scroll = clamp(scroll, 0, getMaxScroll());
		hScroll = clamp(hScroll, 0, getMaxHScroll());
		dirty = false;
	}

	/**
	 * Lays out one tab's grid at the tab's own layout width, {@link BankTab#getCols()}: every row
	 * holds exactly that many cells (occupied, placeholder, or empty), whatever the window is doing,
	 * which is why resizing never moves an item.
	 *
	 * <p>{@code active} marks the one tab the window is showing on its own. That tab renders at least
	 * {@link #visibleRows} rows past the last occupied one, so the whole viewport is a drop target,
	 * and pads each row out to the window's column count when the window is wider than the tab: those
	 * extra cells are {@link BankSlot#beyondWidth} blanks, and a drop onto one widens the tab. The All
	 * view instead gives every tab exactly its own width and just enough rows to hold its items.
	 */
	private int buildTabGrid(List<BankRow> rowsOut, List<BankSlot> slotsOut, int tabIndex, BankTab tab,
		boolean active, int y)
	{
		final int layoutCols = tab.getCols();
		final int gridCols = active ? Math.max(layoutCols, visibleCols) : layoutCols;
		int occupiedRows = (tab.maxOccupiedIndex() + 1 + layoutCols - 1) / layoutCols;
		int gridRows = active ? Math.max(occupiedRows + 1, visibleRows) : Math.max(occupiedRows, 1);

		for (int r = 0; r < gridRows; r++)
		{
			List<BankSlot> cells = new ArrayList<>(gridCols);
			for (int c = 0; c < gridCols; c++)
			{
				if (c >= layoutCols)
				{
					cells.add(BankSlot.beyondWidth(tabIndex, r, c));
					continue;
				}
				int i = r * layoutCols + c;
				Integer id = tab.itemAt(i);
				BankSlot cell = id == null ? null : buildTabSlot(id, tabIndex, i);
				cells.add(cell != null ? cell : BankSlot.empty(tabIndex, i));
			}
			rowsOut.add(new BankRow(BankRow.Kind.ITEMS, y, BankGeometry.SLOT_H, null, null, cells, tabIndex, -1));
			slotsOut.addAll(cells);
			y += BankGeometry.SLOT_H;
		}
		return y;
	}

	/** Builds the slot for an occupied cell, or null when it is a dropped/ignored placeholder. */
	private BankSlot buildTabSlot(int id, int tabIndex, int indexInTab)
	{
		if (ownedIds.contains(id))
		{
			ItemSnapshot first = firstSnapshotById.get(id);
			String name = first != null ? first.getName() : nameFor(id);
			boolean stackable = first != null && first.isStackable();
			long qty = qtyById.getOrDefault(id, 0L);
			List<SlotSource> src = sourcesById.getOrDefault(id, Collections.emptyList());
			return new BankSlot(id, name, qty, stackable, false, src, tabIndex, indexInTab);
		}

		if (!placeholdersEnabled || layout.isPlaceholderIgnored(id))
		{
			return null;
		}

		return new BankSlot(id, nameFor(id), 0, false, true, Collections.emptyList(), tabIndex, indexInTab);
	}

	/**
	 * One result per distinct id (card 27): a search result answers "do I own this and where is it",
	 * and N identical cells for a duplicated item is noise that pushes real hits off the screen. The
	 * first copy in strip order wins, so the result cell still carries a real
	 * {@code (tabIndex, indexInTab)} origin and the drag-to-tab copy gesture keeps working. Deliberate
	 * asymmetry with the All view, which shows every copy under its own tab's divider.
	 */
	private int buildSearchRows(List<BankRow> rowsOut, List<BankSlot> slotsOut, int y)
	{
		List<BankSlot> built = new ArrayList<>();
		Set<Integer> emitted = new LinkedHashSet<>();
		List<Integer> tabsToScan = new ArrayList<>();
		if (activeTab >= 0 && layout.getTab(activeTab) != null)
		{
			tabsToScan.add(activeTab);
		}
		else
		{
			for (int t = 0; t < layout.getTabs().size(); t++)
			{
				tabsToScan.add(t);
			}
		}

		for (int t : tabsToScan)
		{
			BankTab tab = layout.getTab(t);
			List<Integer> tabSlots = tab.getSlots();
			for (int i = 0; i < tabSlots.size(); i++)
			{
				Integer id = tabSlots.get(i);
				if (id == null)
				{
					continue;
				}
				BankSlot slot = buildTabSlot(id, t, i);
				if (slot != null && matchesSearch(slot.getName()) && emitted.add(id))
				{
					built.add(slot);
				}
			}
		}

		return appendItemRows(rowsOut, slotsOut, built, y);
	}

	/**
	 * Ids to show in {@code BY_STORAGE} mode: {@code null} when the All tab is active (no filter -
	 * everything owned, today's behaviour), otherwise the ids present in the active layout tab's
	 * slots, so storage mode groups by storage the same items the active tab's grid would show.
	 */
	private Set<Integer> storageModeTabFilter()
	{
		BankTab tab = activeTabRef();
		return tab == null ? null : new LinkedHashSet<>(tab.itemIds());
	}

	private String nameFor(int id)
	{
		return knownNames.getOrDefault(id, UNKNOWN_ITEM_PREFIX + id);
	}

	private boolean matchesSearch(String name)
	{
		return searchLower.isEmpty() || (name != null && name.toLowerCase(Locale.ROOT).contains(searchLower));
	}

	private int appendItemRows(List<BankRow> rowsOut, List<BankSlot> slotsOut, List<BankSlot> built, int y)
	{
		for (int i = 0; i < built.size(); i += visibleCols)
		{
			List<BankSlot> chunk = built.subList(i, Math.min(i + visibleCols, built.size()));
			rowsOut.add(new BankRow(BankRow.Kind.ITEMS, y, BankGeometry.SLOT_H, null, null, chunk));
			slotsOut.addAll(chunk);
			y += BankGeometry.SLOT_H;
		}
		return y;
	}

	private void recomputeOwnedData()
	{
		Set<Integer> owned = new LinkedHashSet<>();
		Map<Integer, Long> qty = new LinkedHashMap<>();
		Map<Integer, List<SlotSource>> src = new LinkedHashMap<>();
		Map<Integer, ItemSnapshot> first = new LinkedHashMap<>();

		for (StorageSnapshot snap : snapshots)
		{
			for (ItemSnapshot item : snap.getItems())
			{
				if (item.getQuantity() <= 0)
				{
					continue;
				}
				int id = item.getCanonicalId();
				owned.add(id);
				qty.merge(id, item.getQuantity(), Long::sum);
				src.computeIfAbsent(id, k -> new ArrayList<>()).add(new SlotSource(snap.getName(), item.getQuantity()));
				first.putIfAbsent(id, item);
			}
		}

		ownedIds = owned;
		qtyById = qty;
		sourcesById = src;
		firstSnapshotById = first;
	}

