	private void recordHScroll()
	{
		if (!search.isEmpty())
		{
			return;
		}
		if (activeTab < 0)
		{
			allTabHScroll = hScroll;
			return;
		}
		BankTab tab = layout.getTab(activeTab);
		if (tab != null)
		{
			hScrollByTab.put(tab, hScroll);
		}
	}

	private void recordScroll()
	{
		if (!search.isEmpty())
		{
			return;
		}
		if (activeTab < 0)
		{
			allTabScroll = scroll;
			return;
		}
		BankTab tab = layout.getTab(activeTab);
		if (tab != null)
		{
			scrollByTab.put(tab, scroll);
		}
	}

