	}

	// ---- mocks -----------------------------------------------------------------------------

	private void stubConfig()
	{
		Mockito.when(config.placeholders()).thenReturn(true);
		Mockito.when(config.showEmptyStorages()).thenReturn(false);
		Mockito.when(config.showHudButton()).thenReturn(true);
