			storagesDirty = false;
			return null;
		}).when(plugin).clearStoragesDirty();

		Mockito.doReturn(Collections.emptyList()).when(storageManagerManager).getStorageManagers();
		Mockito.doAnswer(inv -> fixture.storages()).when(storageManagerManager).getViewableStorages();
	}

