	// ---- synthetic input -------------------------------------------------------------------

	private static MouseEvent mouse(int id, int button, int x, int y)
	{
		final int modifiers = button == MouseEvent.BUTTON3
			? MouseEvent.BUTTON3_DOWN_MASK : MouseEvent.BUTTON1_DOWN_MASK;
		return new MouseEvent(EVENT_SOURCE, id, System.currentTimeMillis(), modifiers, x, y, 1,
			button == MouseEvent.BUTTON3, button);
	}

	public MouseEvent moveTo(int x, int y)
	{
		return listener.mouseMoved(mouse(MouseEvent.MOUSE_MOVED, MouseEvent.NOBUTTON, x, y));
	}

	public MouseEvent moveTo(Point p)
	{
		return moveTo(p.x, p.y);
	}

	public MouseEvent press(int x, int y)
	{
		return listener.mousePressed(mouse(MouseEvent.MOUSE_PRESSED, MouseEvent.BUTTON1, x, y));
	}

	public MouseEvent release(int x, int y)
	{
		return listener.mouseReleased(mouse(MouseEvent.MOUSE_RELEASED, MouseEvent.BUTTON1, x, y));
	}

	public MouseEvent drag(int x, int y)
	{
		return listener.mouseDragged(mouse(MouseEvent.MOUSE_DRAGGED, MouseEvent.BUTTON1, x, y));
	}

	public MouseEvent rightPress(int x, int y)
	{
		return listener.mousePressed(mouse(MouseEvent.MOUSE_PRESSED, MouseEvent.BUTTON3, x, y));
	}

	/** Full left click: move, press, release, click. Returns the press event. */
	public MouseEvent click(int x, int y)
	{
		moveTo(x, y);
		final MouseEvent pressed = press(x, y);
		listener.mouseReleased(mouse(MouseEvent.MOUSE_RELEASED, MouseEvent.BUTTON1, x, y));
		listener.mouseClicked(mouse(MouseEvent.MOUSE_CLICKED, MouseEvent.BUTTON1, x, y));
		return pressed;
	}

	public MouseEvent click(Point p)
	{
		return click(p.x, p.y);
	}

	public MouseWheelEvent wheel(int x, int y, int rotation)
	{
		final MouseWheelEvent e = new MouseWheelEvent(EVENT_SOURCE, MouseEvent.MOUSE_WHEEL,
			System.currentTimeMillis(), 0, x, y, 0, false, MouseWheelEvent.WHEEL_UNIT_SCROLL,
			1, rotation);
		return listener.mouseWheelMoved(e);
	}

	/** Shift + wheel, which is the horizontal scroll gesture. */
	public MouseWheelEvent shiftWheel(int x, int y, int rotation)
	{
		final MouseWheelEvent e = new MouseWheelEvent(EVENT_SOURCE, MouseEvent.MOUSE_WHEEL,
			System.currentTimeMillis(), MouseEvent.SHIFT_DOWN_MASK, x, y, 0, false,
			MouseWheelEvent.WHEEL_UNIT_SCROLL, 1, rotation);
		return listener.mouseWheelMoved(e);
	}

	/**
	 * Raw printable keystrokes at our own key listener. Since card 32 the listener ignores them
	 * outright - search text goes to the chatbox text input - so this only exists to prove that.
	 */
	public void type(String text)
	{
		for (char c : text.toCharArray())
		{
			listener.keyTyped(new KeyEvent(EVENT_SOURCE, KeyEvent.KEY_TYPED, System.currentTimeMillis(),
				0, KeyEvent.VK_UNDEFINED, c));
		}
	}

	/**
	 * Stands in for the player typing into the chatbox search prompt: replays the {@code onChanged}
	 * callback {@code openSearch()} registered on the mock once per keystroke, exactly as
	 * {@code ChatboxTextInput.keyTyped} does, so the filter updates live.
	 */
	@SuppressWarnings("unchecked")
	public void typeInSearch(String text)
	{
		final ArgumentCaptor<Consumer<String>> changed = ArgumentCaptor.forClass(Consumer.class);
		Mockito.verify(searchInput, Mockito.atLeastOnce()).onChanged(changed.capture());

		final StringBuilder value = new StringBuilder();
		for (char c : text.toCharArray())
		{
			value.append(c);
			changed.getValue().accept(value.toString());
		}
	}

	/** Enter in the search prompt: {@code onDone} then the panel closing itself. */
	@SuppressWarnings("unchecked")
	public void submitSearch(String text)
	{
		final ArgumentCaptor<Consumer<String>> done = ArgumentCaptor.forClass(Consumer.class);
		Mockito.verify(searchInput, Mockito.atLeastOnce()).onDone(done.capture());
		done.getValue().accept(text);
		closeSearchPrompt();
	}

	/** Escape in the search prompt, or the game killing the panel: {@code onClose} alone. */
	public void closeSearchPrompt()
	{
		final ArgumentCaptor<Runnable> closed = ArgumentCaptor.forClass(Runnable.class);
		Mockito.verify(searchInput, Mockito.atLeastOnce()).onClose(closed.capture());
		closed.getValue().run();
	}

	/** True once {@code openSearch()} has built the chatbox prompt at least once. */
	public boolean searchPromptOpened()
	{
		return Mockito.mockingDetails(searchInput).getInvocations().stream()
			.anyMatch(i -> "build".equals(i.getMethod().getName()));
	}

	/** How many times the search prompt has been built, for toggle assertions. */
	public long searchPromptOpenCount()
	{
		return Mockito.mockingDetails(searchInput).getInvocations().stream()
			.filter(i -> "build".equals(i.getMethod().getName()))
			.count();
	}

	/** True once the controller has asked the chatbox panel manager to close our prompt. */
	public boolean searchPromptClosedByUs()
	{
		return Mockito.mockingDetails(chatboxPanelManager).getInvocations().stream()
			.anyMatch(i -> "close".equals(i.getMethod().getName()));
	}

	public KeyEvent keyPress(int keyCode)
	{
		final KeyEvent e = new KeyEvent(EVENT_SOURCE, KeyEvent.KEY_PRESSED, System.currentTimeMillis(),
			0, keyCode, KeyEvent.CHAR_UNDEFINED);
		listener.keyPressed(e);
		return e;
	}

	// ---- scene helpers ---------------------------------------------------------------------

	/** Clicks the HUD button, which is how a player without a hotkey opens the view. */
	public void openViaHudButton()
	{
		final Rectangle hud = hudRect();
		click(hud.x + hud.width / 2, hud.y + hud.height / 2);
	}

	/** Clicks a tab-strip entry: 0 = [All], 1 = main tab, 2.. = custom tabs. */
	public void clickTab(int stripIndex)
	{
		click(rectCentre(rectOnCanvas(model().tabRect(stripIndex))));
	}

	public void clickSearchBox()
	{
		click(rectCentre(rectOnCanvas(model().searchRect())));
	}

	/** Clicks the bank's search icon, left of the search box. */
	public void clickSearchButton()
	{
		click(rectCentre(rectOnCanvas(model().searchButtonRect())));
	}

	/** Clicks the bottom bar's add button, which opens the game's item search. */
	public void clickAddButton()
	{
		click(rectCentre(rectOnCanvas(model().addButtonRect())));
	}

	/**
	 * Stands in for the player picking an item in the chatbox item search: replays the callbacks the
	 * real {@code ChatboxItemSearch} would fire - the selection, then the panel closing itself - onto
	 * the ones {@code openItemSearch()} registered on the mock.
	 */
	@SuppressWarnings("unchecked")
	public void pickInItemSearch(int itemId)
	{
		final ArgumentCaptor<Consumer<Integer>> selected = ArgumentCaptor.forClass(Consumer.class);
		Mockito.verify(itemSearch, Mockito.atLeastOnce()).onItemSelected(selected.capture());
		final ArgumentCaptor<Runnable> closed = ArgumentCaptor.forClass(Runnable.class);
		Mockito.verify(itemSearch, Mockito.atLeastOnce()).onClose(closed.capture());

		selected.getValue().accept(itemId);
		closed.getValue().run();
	}

	/**
	 * Stands in for the player typing a name and pressing Enter in the chatbox text input a tab's
	 * "Rename tab" entry opens: replays the {@code onDone} then {@code onClose} callbacks
	 * {@code openTabRename()} registered on the mock, exactly the way the real widget's Enter handler
	 * calls {@code onDone} and then closes the panel.
	 */
	@SuppressWarnings("unchecked")
	public void submitTabRename(String newName)
	{
		final ArgumentCaptor<Consumer<String>> done = ArgumentCaptor.forClass(Consumer.class);
		Mockito.verify(tabRenameInput, Mockito.atLeastOnce()).onDone(done.capture());
		final ArgumentCaptor<Runnable> closed = ArgumentCaptor.forClass(Runnable.class);
		Mockito.verify(tabRenameInput, Mockito.atLeastOnce()).onClose(closed.capture());

		done.getValue().accept(newName);
		closed.getValue().run();
	}

	private static Point rectCentre(Rectangle r)
	{
		return new Point(r.x + r.width / 2, r.y + r.height / 2);
	}
}

package io.robrichardson.banklessbank.ui.harness;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.SpriteID;

/**
 * Stand-in interface sprites for the headless harness. The real ones come out of the game cache,
 * which no test has, so {@code SpriteManager} is mocked to return either null (exercising
 * {@link io.robrichardson.banklessbank.ui.BankOverlay}'s flat-colour fallbacks) or these, which are
 * the right sizes and roughly the right palette and so exercise the sprite path: 9-slicing, tiling,
 * fitting and centring.
 *
 * <p>Only the ids the overlay actually asks for are generated. Anything else stays null, which is
 * also what the client does for an id its revision does not have.
 */
final class FakeInterfaceSprites
{
	private static final Color STEEL = new Color(0x3A, 0x39, 0x34);
	private static final Color STEEL_DARK = new Color(0x14, 0x14, 0x12);
	private static final Color STEEL_LIGHT = new Color(0x77, 0x75, 0x6A);
	private static final Color STONE = new Color(0x5B, 0x5A, 0x51);
	private static final Color STONE_DARK = new Color(0x2B, 0x2B, 0x26);
	private static final Color PANEL = new Color(0x49, 0x40, 0x34);
	private static final Color ORANGE = new Color(0xFF, 0x98, 0x1F);

	private final Map<Integer, BufferedImage> byId = new HashMap<>();

	FakeInterfaceSprites()
	{
		final int b = 8;
		byId.put(SpriteID.Steelborder.TOP_LEFT, corner(b, true, true));
		byId.put(SpriteID.Steelborder.TOP_RIGHT, corner(b, false, true));
		byId.put(SpriteID.Steelborder.BOTTOM_LEFT, corner(b, true, false));
		byId.put(SpriteID.Steelborder.BOTTOM_RIGHT, corner(b, false, false));
		byId.put(SpriteID.Steelborder2.EDGE_TOP, edgeTop(16, b));
		byId.put(SpriteID.Steelborder2.EDGE_RIGHT, edgeRight(b, 16));

		byId.put(SpriteID.SteelborderCloseButton._0, closeButton(21, false));
		byId.put(SpriteID.SteelborderCloseButton._1, closeButton(21, true));

		byId.put(SpriteID.Banktabs.TAB, tab(40, 40, STONE));
		byId.put(SpriteID.Banktabs.HOVERED, tab(40, 40, STONE.brighter()));
		byId.put(SpriteID.Banktabs.SELECTED, tab(40, 40, PANEL));
		byId.put(SpriteID.Banktabs.EMPTY, tab(40, 40, STONE_DARK));

		byId.put(SpriteID.BanktabIcons.ALL_ITEMS, infinity(22, 14));
		byId.put(SpriteID.BanktabIcons.ADD, plus(18, 18));

		byId.put(SpriteID.ScrollbarV2.ARROW_UP, arrow(16, true));
		byId.put(SpriteID.ScrollbarV2.ARROW_DOWN, arrow(16, false));
		byId.put(SpriteID.ScrollbarDraggerV2.TOP, dragger(16, 5, true, false));
		byId.put(SpriteID.ScrollbarDraggerV2.MIDDLE, dragger(16, 4, false, false));
		byId.put(SpriteID.ScrollbarDraggerV2.BOTTOM, dragger(16, 5, false, true));
		byId.put(SpriteID.ScrollbarDraggerV2.TRACK, track(16, 8));

		byId.put(SpriteID.Bankbuttons.SEARCH, magnifier(20));
	}

	BufferedImage get(int spriteId)
	{
		return byId.get(spriteId);
	}

	private static BufferedImage blank(int w, int h)
	{
		return new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
	}

	private static BufferedImage corner(int size, boolean left, boolean top)
	{
		final BufferedImage image = blank(size, size);
		final Graphics2D g = image.createGraphics();
		g.setColor(STEEL);
		g.fillRect(0, 0, size, size);
		g.setColor(STEEL_DARK);
		g.drawRect(0, 0, size - 1, size - 1);
		g.setColor(STEEL_LIGHT);
		g.fillRect(left ? 2 : size - 4, top ? 2 : size - 4, 2, 2);
		g.dispose();
		return image;
	}

	private static BufferedImage edgeTop(int w, int h)
	{
		final BufferedImage image = blank(w, h);
		final Graphics2D g = image.createGraphics();
		g.setColor(STEEL);
		g.fillRect(0, 0, w, h);
		g.setColor(STEEL_DARK);
		g.drawLine(0, 0, w - 1, 0);
		g.drawLine(0, h - 1, w - 1, h - 1);
		g.setColor(STEEL_LIGHT);
		g.fillRect(w / 2 - 1, 2, 2, 2);
		g.dispose();
		return image;
	}

	private static BufferedImage edgeRight(int w, int h)
	{
		final BufferedImage image = blank(w, h);
		final Graphics2D g = image.createGraphics();
		g.setColor(STEEL);
		g.fillRect(0, 0, w, h);
		g.setColor(STEEL_DARK);
		g.drawLine(0, 0, 0, h - 1);
		g.drawLine(w - 1, 0, w - 1, h - 1);
		g.setColor(STEEL_LIGHT);
		g.fillRect(w - 4, h / 2 - 1, 2, 2);
		g.dispose();
		return image;
	}

	private static BufferedImage closeButton(int size, boolean hovered)
	{
		final BufferedImage image = blank(size, size);
		final Graphics2D g = image.createGraphics();
		g.setColor(hovered ? STONE.brighter() : STONE);
		g.fillRect(0, 0, size, size);
		g.setColor(STEEL_DARK);
		g.drawRect(0, 0, size - 1, size - 1);
		g.setColor(new Color(0xE8, 0xE0, 0xD0));
		g.setStroke(new BasicStroke(2f));
		g.drawLine(5, 5, size - 6, size - 6);
		g.drawLine(size - 6, 5, 5, size - 6);
		g.dispose();
		return image;
	}

	private static BufferedImage tab(int w, int h, Color fill)
	{
		final BufferedImage image = blank(w, h);
		final Graphics2D g = image.createGraphics();
		g.setColor(fill);
		g.fillRoundRect(0, 0, w, h, 8, 8);
		g.setColor(STEEL_DARK);
		g.drawRoundRect(0, 0, w - 1, h - 1, 8, 8);
		g.setColor(STEEL_LIGHT);
		g.drawLine(3, 1, w - 4, 1);
		g.dispose();
		return image;
	}

	private static BufferedImage infinity(int w, int h)
	{
		final BufferedImage image = blank(w, h);
		final Graphics2D g = image.createGraphics();
		g.setColor(new Color(0xC8, 0xC2, 0xB0));
		g.setStroke(new BasicStroke(2f));
		g.drawOval(1, 2, h - 5, h - 5);
		g.drawOval(w - h + 3, 2, h - 5, h - 5);
		g.dispose();
		return image;
	}

	private static BufferedImage plus(int w, int h)
	{
		final BufferedImage image = blank(w, h);
		final Graphics2D g = image.createGraphics();
		g.setColor(new Color(0xC8, 0xC2, 0xB0));
		g.fillRect(w / 2 - 1, 2, 3, h - 4);
		g.fillRect(2, h / 2 - 1, w - 4, 3);
		g.dispose();
		return image;
	}

	private static BufferedImage arrow(int size, boolean up)
	{
		final BufferedImage image = blank(size, size);
		final Graphics2D g = image.createGraphics();
		g.setColor(STONE);
		g.fillRect(0, 0, size, size);
		g.setColor(STEEL_DARK);
		g.drawRect(0, 0, size - 1, size - 1);
		final int[] xs = {4, size - 4, size / 2};
		final int[] ys = up ? new int[]{size - 5, size - 5, 4} : new int[]{4, 4, size - 5};
		g.setColor(new Color(0x1E, 0x1B, 0x14));
		g.fillPolygon(xs, ys, 3);
		g.dispose();
		return image;
	}

	private static BufferedImage dragger(int w, int h, boolean top, boolean bottom)
	{
		final BufferedImage image = blank(w, h);
		final Graphics2D g = image.createGraphics();
		g.setColor(new Color(0x6E, 0x6B, 0x5F));
		g.fillRect(0, 0, w, h);
		g.setColor(STEEL_LIGHT);
		if (top)
		{
			g.drawLine(0, 0, w - 1, 0);
		}
		g.drawLine(0, 0, 0, h - 1);
		g.setColor(STEEL_DARK);
		g.drawLine(w - 1, 0, w - 1, h - 1);
		if (bottom)
		{
			g.drawLine(0, h - 1, w - 1, h - 1);
		}
		g.dispose();
		return image;
	}

	private static BufferedImage track(int w, int h)
	{
		final BufferedImage image = blank(w, h);
		final Graphics2D g = image.createGraphics();
		g.setColor(new Color(0x25, 0x20, 0x19));
		g.fillRect(0, 0, w, h);
		g.setColor(new Color(0x14, 0x11, 0x0D));
		g.drawLine(0, 0, 0, h - 1);
		g.drawLine(w - 1, 0, w - 1, h - 1);
		g.dispose();
		return image;
	}

	private static BufferedImage magnifier(int size)
	{
		final BufferedImage image = blank(size, size);
		final Graphics2D g = image.createGraphics();
		g.setColor(ORANGE);
		g.setStroke(new BasicStroke(2f));
		g.drawOval(2, 2, size - 8, size - 8);
		g.drawLine(size - 7, size - 7, size - 3, size - 3);
		g.dispose();
		return image;
	}
}

package io.robrichardson.banklessbank.ui.harness;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Stand-in for the game cache's item sprites. Generates a deterministic 36x32
 * {@link AsyncBufferedImage} per (id, quantity, withCount) triple: a coloured rounded rect keyed by
 * item id, a three-letter abbreviation of the item's name, and, when the overlay asked for a count,
 * the bank-style quantity text in the top-left in yellow / white / green by magnitude.
 *
 * <p>{@link AsyncBufferedImage} is constructed with a null {@code ClientThread}; nothing in the
 * render path calls {@code onLoaded}, so the field is never dereferenced.
 */
public final class FakeItemSprites
{
	private static final Color QTY_YELLOW = new Color(0xFF, 0xFF, 0x00);
	private static final Color QTY_WHITE = new Color(0xFF, 0xFF, 0xFF);
	private static final Color QTY_GREEN = new Color(0x00, 0xFF, 0x80);

	private final Map<Integer, String> names;
	private final Map<String, AsyncBufferedImage> cache = new HashMap<>();

	public FakeItemSprites(Map<Integer, String> names)
	{
		this.names = names;
	}

	public AsyncBufferedImage get(int itemId, int quantity, boolean withCount)
	{
		final String key = itemId + "/" + quantity + "/" + withCount;
		return cache.computeIfAbsent(key, k -> draw(itemId, quantity, withCount));
	}

	private AsyncBufferedImage draw(int itemId, int quantity, boolean withCount)
	{
		final int w = 36;
		final int h = 32;
		final AsyncBufferedImage image = new AsyncBufferedImage(null, w, h, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		final Color body = colourFor(itemId);
		g.setColor(body);
		g.fillRoundRect(2, 4, w - 5, h - 9, 8, 8);
		g.setColor(body.darker().darker());
		g.drawRoundRect(2, 4, w - 5, h - 9, 8, 8);

		final String abbreviation = abbreviate(names.get(itemId), itemId);
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
		final FontMetrics fm = g.getFontMetrics();
		g.setColor(contrastOn(body));
		g.drawString(abbreviation, (w - fm.stringWidth(abbreviation)) / 2, h / 2 + fm.getAscent() / 2 - 1);

		if (withCount && quantity > 1)
		{
			final String text = formatQuantity(quantity);
			g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 9));
			g.setColor(Color.BLACK);
			g.drawString(text, 2, 9);
			g.setColor(quantityColour(quantity));
			g.drawString(text, 1, 8);
		}

		g.dispose();
		return image;
	}

	/** The real bank's magnitude colouring: yellow under 100k, white under 10m, green above. */
	private static Color quantityColour(long quantity)
	{
		if (quantity < 100_000)
		{
			return QTY_YELLOW;
		}
		return quantity < 10_000_000 ? QTY_WHITE : QTY_GREEN;
	}

	private static String formatQuantity(long quantity)
	{
		if (quantity >= 10_000_000)
		{
			return (quantity / 1_000_000) + "M";
		}
		if (quantity >= 100_000)
		{
			return (quantity / 1000) + "K";
		}
		return String.valueOf(quantity);
	}

	private static String abbreviate(String name, int itemId)
	{
		if (name == null || name.isEmpty())
		{
			return String.valueOf(itemId % 1000);
		}
		final String letters = name.replaceAll("[^A-Za-z]", "");
		if (letters.length() <= 3)
		{
			return letters.isEmpty() ? String.valueOf(itemId % 1000) : letters;
		}
		return letters.substring(0, 3);
	}

	/** Stable hue per item id, so the same item is the same colour in every screenshot. */
	private static Color colourFor(int itemId)
	{
		final float hue = ((itemId * 2654435761L) % 360L) / 360f;
		return Color.getHSBColor(Math.abs(hue), 0.55f, 0.78f);
	}

	private static Color contrastOn(Color background)
	{
		final int luma = (background.getRed() * 299 + background.getGreen() * 587 + background.getBlue() * 114) / 1000;
		return luma > 140 ? Color.BLACK : Color.WHITE;
	}
}

